var ASramavAsa = [
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","శ్రీరస్తు","001","క.","శ్రీసాదనపదపద్మో | పాసనవిద్యా! శమైకపరతానిత్యా\nభ్యాసజనహృద్య! వేద | వ్యాస వచోవిభవవేద్య | హరిహరనాథా!","ప్రతిపదార్థం: శ్రీ= సంపదలకు; సాదన= నివాసమైన; పద పద్మ= తామరపూలవంటి పాదాలను; ఉపాసన= సేవించటం అనే; విద్యా!= విద్య కలవాడా! శమ= శాంతిలో; ఏకపరతా= ప్రధాన మైన తాత్పర్యంతో; నిత్య= ఎల్లవేళలా; అభ్యాస= అలవాటుగా కలిగిన; జన= జనానికి; హృద్య!ణ మనోహరమైనవాడా!; వేదవ్యాస= వేదాలను వేరు చేసిన (వ్యాస) మహర్షియొక్క; వచన్‌= వాక్యాల; విభవ= మహిమచేత; వేద్య!= తెలియదగినవాడా; హరిహరనాథా!= విష్ణు - పరమేశ్వర న్వరూపుడా! (వినుము).","తాత్పర్యం: నీపాద పద్మాలను సేవించుకొనేవారికి సంపద లిచ్చేవాడా! ఎప్పుడూ శాంతంగా ఉండే వారి హృదయాలలో నిలిచేవాడా! వ్యాసమహర్షి బ్రహ్మసూత్ర, పురాణాది వాక్యాలవలన తెలియదగినవాడా! హరిహర స్వరూపా! (తదుపరి వృత్తాంతం వినుము.)","విశేషం: పదసేవతో సిరు లివ్వటం అనే మొదటి అంశంలో హరి లక్షణమూ, శాంతపరుల హృదయంలో ఉండడం అనే రెండో అంశంలో హరలక్షణమూ, వ్యాసవాక్యాలలో తెలియబడటం అనే మూడో అంశంలో హరిహర ఉభయలక్షణమూ కనబడతాయి. శ్రీ అంటే మోక్షం కూడా. అదీ ఒక కామితమే. యుధిష్టిరాదులును గాంధారీధృతరాష్ర్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం.15-1-1)"],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","002","వ.","దేవా! జనమేజయుండు వైశంపాయనున కిట్లనియె; నట్లు పితృపితామహక్రమప్రాప్తం బయిన సామ్రాజ్యంబు జగత్పూజ్యప్రకారంబునం గైకొని మహాధ్వరప్రముఖధర్మకార్యధుర్యులును సముపాసితార్యులును దయా విధేయులు నగు - పాండవేయులు ధృతరాష్ట్రువలన నెవ్విధంబు వారై నడచిరి? హతపుత్రమిత్రామాత్యుండును గతైశ్వర్యుండును నగు నా రాజును యశోమహితయగు గాంధారియు నెట్టిభంగి వర్తించి? రత్తెఱంగు నా కెఱింగింపుము.","ప్రతిపదార్థం: దేవా= హరిహరనాథా!: జనమేజయుండు= జనమేజయమహారాజు; వైళశంపాయనునకున్‌= వైశంపాయనమునితో;ఇట్లు= ఈ విధంగా; అనియెన్‌= అన్నాడు (అట్టులోగడ చెప్పినవిధంగా); పితృ= తండ్రి; పితామహ= తాతల; క్రమ= వరుసలో; ప్రాప్తంబు అయిన= లభించిన; సాఠమ్రాజ్యంబు= సార్వభౌమత్వాన్ని; జగత్‌= ప్రజలచేత; పూజ్య= గౌరవించదగిన; ప్రకారంబునన్‌= పద్ధతిలో; కైకొని= స్వీకరించి; మహా అధ్వర= గొప్ప యజ్ఞాలు; ప్రముఖ= మొదలైన; ధర్మ= వేదవిహితాలు అయిన; కార్య= క్రియలను నిర్వహించటంలో; ధుర్యులును= నేర్పరులూ; సమ్‌ ఉపాసిత= చక్కగా సేవించబడిన; ఆర్యులును= పెద్దలు కలవారూ; దయా విధేయులును= దయకు లోబడినవారూ; అగు= అయిన; పాండవేయులు= పాండురాజు కొడుకులు; ధృతరాష్ట్ర వలనన్‌= ధృతరాష్ట్రుడి విషయంలో; ఏ+విధంబు వారు అయి= ఎటువంటి ప్రవర్తనం కలిగి; నడచిరి?= వ్యవహరించారు?; హత= చంపబడ్డ;వుత్ర= దుర్యోధనాదు లైన కొడుకులూ; మిత్ర= కౌరవపక్షాన నిల్చి యుద్ధంచేసిన రాజ స్నేహితులూ; అమాత్యుండును= మంత్రులూ కలవాడునూ; గత+ఐశ్వర్యుండును= ప్రాభవం కోల్పోయిన వాడునూ; అగు= అయిన; ఆరాజును= ఆధృతరాష్ట్రుడూ; యశస్‌ మహిత= కీర్తిచేత గొప్పది; అగు= అయిన; గాంధారియున్‌= ధృతరాష్ట్రుడిభార్యా; ఎట్టిభంగిన్‌= ఏవిధంగా; వర్తించిరి= వ్యవహరించారు; ఆ+తెఅంగు= ఆవిధం; నాకున్‌= నాకు (జనమేజయుడికి); ఎజింగింపుము= తెలుపవలసింది.","తాత్పర్యం: హరిహరదేవా! జనమేజయుడు వైశంపాయనుడితో ఇట్లా అన్నాడు. గొప్పగొప్పయజ్డాలు మొదలైన వేదకర్మలను ఆచరించేవాళ్ళూ, పెద్దలను గౌరవించేవాళ్ళూ, కరుణా స్వభావులూ అయిన పాండవులు తాతల, తండ్రుల క్రమంలో తమకు లభించిన ప్రభుత్వాన్ని సర్వజనామోదకరంగా స్వీకరించిన తర్యాత ధృతరాష్ట్రుడి విషయంలో ఎట్లా నడచుకున్నారు? కొడుకులనూ, హితులనూ, మంత్రులనూ, తనవారందరినీ, సార్వభౌమత్వాన్నీ పోగొట్టుకొన్న ధృతరాష్ర్రుడూ, మంచిపేరున్న గాంధారీ (పాండవులతో) ఎట్టా వ్యవహరించారు? ఆ సంగతి తెలియజెప్పవలసింది.","విశేషం: ఇందులో విశేషణాలన్నీ సాభిప్రాయాలు. పాండవులకు రాజ్యం హక్కుగా వచ్చిందే కాని బలవంతంగా లాక్కున్నది కాదు. దాయాదులను చంపి కాజేశారనీ, అది హేయమనీ ప్రజలు కూడా అనుకోలేదు. కాబట్టి యీవిషయంలో ధృతరాష్ట్రుడు పాండవులపై ద్వేషం పెట్టుకొనగూడదని ఉద్దేశం. ఆర్యులను సేవించే లక్షణం ఉన్నది. పైగా దయా విధేయులు గూడా కాబట్టి గాంధారీధృతరాష్ట్రలునూ పెద్దతల్లితండ్రులునూ పుత్రశోకంలో ఉంటారు. కాబట్టి సానుభూతితో గూడ పాండవులు తప్పక గౌరవించేఉంటారు. గతంలో తమ కష్టాలకు ధృతరాష్ట్రుడూ కొంత కారణం అని అతనిపై పాండవులకు కోపం ఉండదు - అని తన వంశంలో ఆర్యులైన పాండవులను గూర్చి జనమేజయుడి నమ్మకం. ఇంక హతపుత్రమిత్రామాత్యుడైన ధృతరాష్ర్రుడికే దానికి హేతువైన పాండవులమ్‌ిద కోపం ఉండక తప్పదు. 'పవనాత్మజుండు సన్నిహితు6 డైన యప్పు డజ్జనవిభుండు తన తనూజుల/ దలంచి సంతాప మందు” (16వ.) తుండడం గమనిస్తాం (ఇట్టాగే 31స.) కాబట్టి, ధృతరాష్ర్ట్రుడు పాండవులతో మనసు కలిసిఉండటం జరగదు. యశోమహిత అనటంలో గాంధారిమోద కొంత సదభిప్రాయం. మహాధ్వరకార్యధుర్యులు మొదలైన విశేషణాలు పాండవులకు సామ్రాజ్యం గైకొన్న తర్వాతే కాదు ముందూ అన్వయిస్తాయి."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","","సీ.","అనవుడు నమ్ముని యమ్మహీపతికి ని | ట్లనుఁ, బాండునందను లాంబికేయు\nనెడ భక్తివినయంబు లెసఁగంగ వర్తింతు | రతని యోగక్షేమ మరసి యెపుడుఁ\nదత్సమీపంబునఁ దగ నిల్చి తమకు నె | య్యది యైన నెఱిఁగించునట్లు గాఁగ\nనుందురు విదుర యుయుత్సు సంజయులు దా | రును నిత్యమును వచ్చి వినతిఁ జేసి","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","003","తే.","కొలిచి కూర్చుండి యా నృపు నలఘుకార్య | విధము లేర్పడ నడిగి యవ్విభుని చెప్పి\nనట్లు చేయుదు రతఁడును నాదరంబు | గాఢవత్సలత్వంబును గలిగియుండు.","వాత్సల్యాన్నీ; కలిగి ఉండున్‌= కలిగి వ్యవహరించేవాడు.","తాత్పర్యం: జనమేజయుడు అడిగినదానికి సమాధానంగా వైశంపాయనుడు ఇట్లా చెప్పుతున్నాడు: పాండవులు ధృతరాష్ట్రుడిని వినయంగా సేవించేవాళ్ళు. అతడికి మేలు కలిగేటట్టుగా, బౌన్నత్యానికి భంగం రాకుండా నడుచుకొనేవారు ఏ సమయంలో అయినా ఎటువంటి పని అయినా తమకు ఆజ్ఞాపించటానికి వీలుగా ఎప్పుడూ అతడిసమ్‌పంలో, అతడికి ఇబ్బంది కలగనివిధంగా ఉండేవాళ్ళు. విదురుడూ, యుయుత్సుడూ, సంజయుడూ ప్రత్యేకంగా పిలిపించవలసిన అవసరం లేకుండా రోజూ స్వయంగా వచ్చి ధృతరాష్రుడిని సేవించేవాళ్ళు. ఏం కావాలో అడిగి చిన్నా పెద్దా పను లన్నీ చేసిపెట్టేవాళ్ళు. ధృతరాష్ట్రుడు కూడా పాండవాదు లందరిమ్‌దా ప్రేమతో, వాత్సల్యంతో ఉండేవాడు. అ అల","విశేషం: జనమేజయుడు గతైశ్వర్యు డన్నా పాండవాదులు యోగక్షేమాలకు లోటు లేకుండా కింకరభావంతో సేవించటంవలనా, ధృతరాష్ట్రుడు 'నృపుడే” క్రమంగా చూస్తే ఆంబికేయుడికి పాండునందనులమ్‌ద ఆదరం, విదురాదులమ్‌ద గాఢవాత్సల్యం ఉన్నాయనాలి. యుయుత్వుడు న్వయానా (వైశ్యస్తీ వలన) కొడు కయితే విదుర సంజయులు మొదటినుండి తన్నాశ్రయించి ఉన్నవాళ్ళు కాబట్టి వాత్సల్యంలో గాఢత సహజమే. పాండునందనులమిీద కొంతభేదభావం అంతరాలనుండి అపుడప్పుడూ బయటపడుతుంటుంది."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","004","ఉ.","కౌరవనాథ! కుంతియును గౌరవ మొప్పఁగ వచ్చి కొల్చు గాం\nధారి నతిప్రయత్నమున ద్రౌపది తాను సుభద్రయున్‌ ముదం\nబారఁగ నిత్యముం గొలుతు రక్కురువంశమహత్తరన్‌ మహో\nదారము లైన వస్తువు లుదాత్తత నిత్తురు వార లందఱున్‌.","ప్రతిపదార్థం: కౌరవనాథ!= జనమేజయమహారాజా!; కుంతియును= కుంతీదేవి; కూడా వచ్చి= తానుగా వచ్చి; గాంధారిన్‌= ధృతరాష్ట్రుడి భార్యను; గౌరవము= గురువు అనే దృష్టి (పెద్దరికం); ఒప్పంగన్‌= మెరిసే విధంగా; కొల్చున్‌=ా సేవించేది; అతిప్రయత్నమునన్‌= మిక్కిలిపూనికతో; ద్రౌపది, తానున్‌= ఆ ద్రౌపదీ; ముదంబు ఆరణగన్‌=ా సంతోషం నిండగా; సుభద్రయున్‌= నుభ్రా; నిత్యమున్‌= ప్రతిరోజూ; ఆ+కురువంశమహత్తరన్‌= కురువంశంలో పెద్ద దయిన ఆ గాంధారిని; కొల్తురు= సేవించేవారు; వారలు+అందయిన్‌కుంతీ, ద్రౌవదీ, సుభద్రలు ముగ్గురూ; ఉదాత్తతన్‌= త్యాగబుద్ధితో; మహా+ఉదారములు+అయిన= గొప్ప విలువైన; వస్తువులు= కానుకలు; ఇత్తురు= గాంధారికి ఇస్తుండేవారు.","తాత్పర్యం: జనమేజయా? కుంతికూడ గౌరవము మెరిసే విధంగా వచ్చి గాంధారిని కొలిచేది. మిక్కిలి పూనికతో తానూ సుభద్రాకూడ సంతోషం నిండగా ఆ గాంధారిని నిత్యమూ కొలిచేవారు. వారందరూ గొప్ప విలువైన కానుకలను గాంధారికి గౌరవంతో ఇచ్చేవారు.","విశేషం: కుంతీ, ద్రౌపదీ, సుభద్రలను ప్రముఖంగా ప్రస్తావించడం విశేషం. ఈ ముగ్గురూ కురుక్షేత్రంలో తమ కొడుకులను పొగొట్టుకున్న వాళ్ళే. కుంతికి కర్ణుడూ ప్రియసుతుడే కదా! ద్రౌపదీ సుభద్రల పిల్లలు కౌరవుల మూలంగా వంచనతో మరణించినవారే అయినా వా ర దంతా మర్చిపోయారు. అందుకే ధృతరాష్ర్రుడిని గురించి భీముడు పలికే పరుషవచనాలు ద్రౌపది క్కూడా తెలియకుండా జాగ్రత్తపడడం జరిగింది. కుంతి 'గౌరవ మొప్పగ కొల్చి” అప్పగారిని గురువు చేసికొని శిష్యురాలివలె శాసించబడేది “గౌరవ మొప్పంగ వచ్చి\" - రావడంలోనే రాజమాతగా గౌరవం. కుంతిలోనూ పట్టమహిషి గావటమే కాకుండా గాంధారీ పుత్ర వినాశానికి పప్రధానకారణ మైనదీ గాబట్టి తననూ ద్రౌపదినీ చూస్తూనే గాంధారికి విపరీతభావం కలగవచ్చు. తనకూ భర్తలకూ కూడా మంచితనాన్ని సంపాదించటంలో ద్రౌపది “అతి ప్రయత్నంతో” గాంధారిని కొలువవలసివచ్చింది. ప్రియసుతుడు అభిమన్యుడిని పోగొట్టుకొన్నా కృష్ణుడి చెల్లెలు సుభద్ర - సంతోషంగానే గాంధారిని సేవించింది. (తర్వాత ఈమె మనుమలే రాజ్యం చేశారు.) 'నిత్యముం గొలుచు నక్కురు' - అనే ముద్రితప్రతులపాఠం “తీసికొంటే” చెప్పనివాడడును, నత్యముచెప్పనివాడడును ఘోర నరకపంకమున పడున్‌ - అనేవిధంగా అన్వయం."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","005","క.","చిత్రాంగదయు నులూపియు | ధాత్రీశ్వర! వత్తు రెపుడు ద్రౌపదితోడన్‌\nగాత్రములు భూరి వినయా | మాత్రములుగ సుబలసుతఁ బ్రమదమునఁ గొలువన్‌.","ప్రతిపదార్థం: ధాత్రీశ్వర!= ఓ రాజా! (జనమేజయా!); గ్యాత్రములు= శరీరాలు; భూరి వినయ ఆమాత్రములు గన్‌= మిక్కిలి అణకువతో నిండినవి కాగా; చిత్రాంగదయున్‌= చిశత్రాంగదా; ఉలూపియున్‌= ఉలూపీ; ప్రమదంబునన్‌= సంతోషంతో; సుబలసుతన్‌= గాంధారిని; కొలువన్‌= సేవించటానికి; ద్రౌపదితోడన్‌= ద్రౌపదితో కలిసి; ఎపుడున్‌= అన్నివేళలా; వత్తురు= వస్తుంటారు.","తాత్పర్యం: జనమేజయా! అర్జునుడి భార్యలైన చిత్రాంగదా, నాగకన్య ఉలూపీ అణకువతోనూ, సంతోషంతోనూ ద్రౌపదితో కలిసి వచ్చి నిత్యమూ గాంధారిని సేవిస్తుండేవాళ్ళు.","విశేషం: చిత్రాంగద అప్సరస. ఉలూపి నాగకన్య. అన్యలోక స్త్రీలు చిన్నవాళ్ళు కాబట్టి అక్కగారితో కలిసి వెళ్ళటం స్వభావానికి అనుగుణం. పైగా ఈ ముగ్గురూ అర్జునుని తీర్థయాత్రలో వలచి సతులయినవారు కావడం సాన్నిహిత్యానికి మరో కారణం. ఈ ముగ్గురి ప్రస్తావనతో ముల్లోకపు స్త్రీల సేవవలన గాంధారికి ప్రాభవం. పాండవస్త్రీలు గూడా గాంధారిని సేవించేవారే, అందులో విశేషం లేదని."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","006","క.","ఆ తల్లికిఁ దండ్రికి సం | ప్రీతి యలరఁ గుడువఁ గట్టఁ నుదాత్త\nస్ఫీతంబు లైన వస్తు | వ్రాతంబుల నిచ్చు ధర్మరా జనుదినమున్‌.","ప్రతిపదార్థం: ధర్మరాజు= ధర్మతనయుడు; అనుదినమున్‌= ప్రతిరోజూ; ఆ తల్లికిన్‌= పెదతల్లి అయిన గాంధారికీ; తండ్రికిన్‌= పెద్ద తండ్రి అయిన ధృతరా్రుడికీ; సంప్రీతి= ఇష్టం; అలరన్‌= అతిశయించేటట్టుగా; కుడువన్‌= తినడానికీ; కట్టన్‌= ధరించడానికీ; పెట్టన్‌= అలంకరించుకొనటానికీ; ఉదాత్త స్పీతంబులు ఐన= రాజులకు తగినవీ, సమృద్దము లైనవీ అయిన; వస్తు ప్రాతంబులన్‌= వస్తువుల సమూహాలను; ఇచ్చున్‌= ఇస్తుండేవాడు.","తాత్పర్యం: గాంధారీ ధృతరా్ట్రులు సంతృప్తిపడే విధంగా తినటానికీ, కట్టుకొనటానికీ, పెట్టుకొనటానికీ, రాజులకు అర్హమైన భక్త్యభోజ్యాలు, శయన, మాల్య అనులేపనాలు మొదలైన వివిధ వస్తువులు, వస్రాలు, ఆభరణాలు సమృద్దిగా ధర్మరాజు వారికి ప్రతిరోజూ అందజేసేవాడు.","విశేషం: సంప్రీతి అలరుట పుచ్చుకొన్న గాంధారీ ధృతరాష్ర్రులకే కాకుండా ఇచ్చే ధర్మరాజులోనూ అన్వయినస్తుంది. తల్లి, తండ్రి అనే భావం వలన ఇచ్చేవాడికీ, పుచ్చుకొనే వాళ్ళకూ సంప్రీతి. పెట్టన్‌ అనేది గాంధారీ ధృతరాష్ట్రులు తాము అనుభవించటానికి మాత్రమే కాక తమ కిష్టమైన వాళ్ళకు సపెట్టుకొనటానికి కూడా సరిపోయేంత సమృద్ధిగా వస్తువ్రాతం ధర్మరాజు ఇస్తున్నా డని తెలుపుతున్నది. అనుదినమూ ఇవ్వటంలో అత్యంత శ్రద్ధ, అప్రమత్తత."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","007","తే.","గుళ్ళుఁ జెఱువులుఁ గట్టించుఁ, గోరి యూళ్ళు | లగ్రహారముల్‌ గావించు నాంబికేయుఁ\nడధిప! ధర్మతనూజుఁ డత్యంత హర్ష | చిత్తవృత్తి యై యనుమతి సేయుచుండ.","ప్రతిపదార్థం: అధివ!= ఓరాజా!; ధర్మ తనూజుడు= ధర్మరాజు; అత్యంత= మిక్కిలి; హర్షణ నంతోషం నిండిన; చిత్త= మనస్సుయొక్క; వృత్తి+ఐ= వర్తనం కలవాడై; అనుమతి= అంగీకారం; చేయుచుండన్‌= తెలుపుతూ ఉండగా; ఆంబికేయుడు= ధృతరాష్ట్రుడు; కోరి= తన ఇచ్చానుసారంగా; (అడిగి); గుళ్ళున్‌= దేవాలయాలూ; చెజువులున్‌= తటాకాలూ; కట్టించున్‌= నిర్మింపజేసేవాడు; ఊళ్ళులు= గ్రామాలు; అగ్రహారముల్‌= బ్రాహ్మణ నివాసన్థలాలూ; కావించున్‌= ఏర్పాటు చేయించేవాడు.","తాత్పర్యం: జనమేజయా! ధర్మరాజు సంతోషంగా ఆమోదించగా ధృతరాష్ట్రుడు గుళ్ళూ, చెరువులూ ఏర్పరిచేవాడు. ఊళ్ళూ, ఆగ్రహారాలూ కల్పించేవాడు.","విశేషం: ధర్మరాజు గూడా కింకరభావంతో ధృతరాష్ర్రుడిని సేవిస్తూ “నీవు” రాజవుగాక నీ కేను రాజనే అంటాడు. (34.న.) అయినా ఏ కార్యమైన నెవ్వ6 డేనియు/ జేయం దొడంగు నప్పుడు పుడమివేనిచే ననుజ్ఞాతుండై కాని తొడంగం గారు” (27స.) అంటాడు ధృతరాష్ట్రుడు. అందుకే రాజానుమతి ధర్మమని తప్ప ధృతరాష్ట్రుడి ఇచ్చకు అవరోధం లేదు. ఇక్కడ వాక్య రచనా విధానంలో ధర్మరాజు అనుమతికి అంతగా ప్రాముఖ్యం కనబడకపోవడం అందుకే. గుళ్ళూ, చెరువులూ, ఊళ్ళూ, అగ్రహారాలు ధృతరాష్ర్రుడేర్పరచటం మరణించిన తనవారికి పుణ్యగతులు సాధించటానికే. అయినా 'హర్షచిత్తవృత్తితో అనుమతించటం ధర్మరాజుసౌశీల్యం. అగ్రహారాలు బ్రాహ్మణులకు మాత్రమే ఇచ్చేవి; సాధారణంగా బ్రాహ్మణులే నివసించే ప్రదేశాలు. వీటిని వంశపారంపర్యంగా అనుభవించవచ్చును. రాజు మారినా ఇవి పోవు. పన్నులు వసూలు చేసికొనే అధికారం మాత్రం ఉండదు. ఊళ్ళు దీనికి వ్యతిరిక్తాలు అంటే పన్నులు వసూలు చేసికొనవచ్చును. రాజు మారితే ఇవీ పోతాయి."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","008","క.","జనవర! ధర్మజుఁ గొలువం | జనుదెంచిన యట్టి వివిధ జనపతు లెల్లన్‌\nమును ధృతరాష్ట్రునిఁ గొలుతురు | విను మా కొడుకు మది పల్లవించున్‌ దానన్‌.","ప్రతిపదార్థం: జనవర!= రాజా! వినుము= వినవలసింది; ధర్మజున్‌= సమ్రాట్టు అయిన ధర్మరాజును; కొలువన్‌= సేవించటానికి; చనుదెంచిన అట్టి= వచ్చిన; వివిధ జనపతులు= వేర్వేరు దేశాల రాజులు; ఎల్లన్‌= అందరూ; మును= ధర్మరాజుకంటె ముందుగా; ధృతరాష్ర్రునిన్‌= ధృతరాష్ర్రడిని; కొలుతురు= సేవించేవారు; దానన్‌= సామంతుల ఆ చర్యవలన; ఆ కొడుకుమది= ధర్మరాజు మనస్సు; పల్లవించున్‌= సంతోషించేది.","తాత్సర్యం: జనమేజయ మహారాజా! వినుము. సార్వభౌముడైన ధర్మరాజును సేవించటానికి వచ్చిన సామంత రాజు లందరూ ధర్మరాజునుకంటె ముందుగా ధృతరాష్ట్రుడిని సేవించేవారు. అందుకు ధర్మరాజు సంతోషించేవాడు.","విశేషం: తన కంటె ధృతరాష్రుడికే ప్రాభవం అధికంగా ఉండడం ధర్మజుడికి సంతోషం. తన కొడుకులే మరణించగా పాండవులకు రాజ్యాధిపత్యం గల్లటంవలన కలిగే మనఃభేదం ధృతరాష్ట్రుడికి ఈ చర్యవలన ఉపశమిస్తుంది. (9స.) సామంతులు ముందుగా అతడిని కొలవటానికి కారణం అతడు ధృతరాష్ట్రుడు కావటం. ఆ తండ్రిని ముందుగా మన్నించడం వలన ధర్మజుడు తన ఆధిపత్యానికి భంగం కలిగిందని అనుకొనకపోగా సంతోషించటం. “ఆ కొడుకు” కావటం వలన పైగా వారు 'ధర్మజు/ గొలువం జనుదెంచినవారు.” వారి ఆంతర్యం ధర్మరాజుకు తెలుసు."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","009","క.","సూనులు లేమిం గలిగెడు | దీనత్వము దోఁపకుండఁ దేజస్సౌఖ్యా\nనూనులుగఁ జేయు ధర్మజుఁ | డా నరపతి నతనిదేవి నతులిత భక్తిన్‌.","ప్రతిపదార్థం: ధర్మజుడు= ధర్మరాజు; అతులిత భక్తిన్‌= సాటిలేని సేవాభావంతో; ఆ నరపతిన్‌= ఆ ధృతరాష్ట్రుడినీ; అతనిదేవిన్‌=ా ఆయన భార్య, గాంధారినీ; సూనులు= కొడుకులు; లేమిన్‌= (యుద్ధంలో మరణించడం చేత) లేకపోవడం వలన; కలిగెడు= సంభవించే; దీనత్వము= దుఃఖం; తోయపకుండన్‌= తలపులోకి రాకుండా; తేజస్‌+సౌఖ్య+అనూనులుగన్‌= ప్రాభవమూ, సుఖమూ తక్కువ కాకుండెడివారుగా; చేయున్‌= చేసేవాడు.","తాత్పర్యం: కొడుకులు లేకపోవటం వలన కలిగే బాధ మనసులోకి రాకుండా ప్రభుత్వానికీ, సుఖానికీ లోటు రాకుండా, గాంధారీ ధృతరాష్టులను చూచుకొనేవాడు ధర్మరాజు.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","","సీ.","వంశవృద్ధులు పుత్త్రవర్గ వియుక్తులై | యున్నవా రేమిట నుమ్మలింతు\nరో యను పుయిలోట నా యుధిష్ఠిరుఁడు ద | మ్ములకును దగునమాత్యులకు నిష్ట\nభృత్యులకును మీరు ప్రీతియు భక్తియు | నాంబికేయునిదెస నతిశయిల్ల\nనారాజు పంచినయట్ల చేసి చరింపుఁ | డతని నారాధించు టస్మదీయ","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","010","ఆ.","చిత్తమునకుఁ బ్రియము సేయుట యతనికి | మనసు గాని యట్టిపని యొనర్చు\nటగ్గలంపు దుఃఖ మావహించుట యని | యనుదినంబుఁ జెప్పు మనుజనాథ!","ప్రతిపదార్థం: మనుజనాథ= రాజా! (జనమేజయా!); వంశవృద్దులు= కురువంశంలో పెద్దవాళ్ళు; పుత్ర వర్గ వియుక్తులు= సపెక్కురైన కొడుకులు దూరమైనవారు; అయి ఉన్నవారు= (జీవిస్తూ) ఉన్నారు; ఏమిటన్‌=ా ఏ విషయంలో; ఉమ్మలింతురో= బాధ పడతారో; అను పుయిలోటన్‌=ా అనే సంకోచంతో; ఆ యుధిష్టిరుడు= ఆ ధర్మరాజు; తమ్ములకును= భీముడు మొదలైన తమ్ముళ్ళతోనూ; తగు అమాత్యులకున్‌= అర్హు లైన మంత్రులతోనూ; ఇష్ట భృత్యులకును= ప్రియమైన సేవకులతోనూ; అనుదినంబున్‌= ప్రతిరోజూ- (ఇట్టా చెప్తాడు); మీరు= మీరు అందరు; ఆంబికేయుని దెసన్‌= ధృతరాష్ట్రుడి మీద; ప్రీతియున్‌= ఇష్టమూ; భక్తియున్‌= సేవాదృష్టీః అతిశయిల్లన్‌= అధికం కాగా; ఆరాజు= ధృతరాష్ట్రుడు; పంచిన+అట్ట= ఆజ్ఞాపించి నవిధంగానే; చేసి= ఆయాపనులు చేసి; చరింపు€ డు= నడచుకొనండి; అతనిన్‌= ధృతరాష్రుడిని; ఆరాధించుట= సేవించటం; అస్మదీయ చిత్రమునకున్‌= నా మనస్సుకు; ప్రియము= ఇష్టం; చేయుట= కల్లించటమే; అతనికిన్‌= ధృతరాష్ర్రడికి; మనసు కాని అట్టిపని= ఇష్టం లేనిపని; ఒనర్చుట= చేయటం; అగ్గలంపు దుఃఖము= (నా మనస్సుకు) మిక్కిలి విచారం; ఆవహించుట= కల్గించటమే; అని= అనేవిధంగా; చెప్పున్‌= చెప్పుతుంటాడు.","తాత్పర్యం: రాజా! గాంధారీ, ధృతరాష్ర్రులు కురువంశంలో పెద్దవాళ్ళు. కొడుకులను పోగొట్టుకొని బ్రతుకుతున్నారు. ఎందుకైనా బాధ పడతారేమో అనే సంకోచంతో ధర్మరాజు, తమ్ములు, మంత్రులు, సేవకులతో ప్రతిరోజూ ఇట్టా చెప్పుతుంటాడు. మీరు ధృతరాష్ట్రుడు ఏ విధంగా ఆజ్ఞాపిస్తే ఆ విధంగా చేస్తూ ఆయన చెప్పిన ప్రకారం నడుచుకొనండి. అతడిని సేవిస్తేనే నా మనసూ సంతోషిస్తుంది. ధృతరాష్ట్రుడికి ఇష్టం లేని పని చేయటం అంటే నన్ను బాధ పెట్టటమే.","విశేషం: యుద్ధంలో చాలామంది పోగా మిగిలినవాళ్ళలో గాంధారీ ధృతరాష్ర్ట్రులు 'వంశవృద్దులు'. వార్డకంలో కొడుకులతోడు ఉండవలసిన సమయంలో పుత్రవియోగం. పైగా పుత్ర “వర్గా వియోగం. కొడుకులు చాలామంది ఉన్నా ఒక్కడూ మిగలకుండా పోవటం. యుయుత్వుడు క్షత్రియుడు కాదు కాబట్టి, సూనులు లేమి ఐయున్నవారు. వార్చకం, బహుపుత్ర వియోగంతో బ్రతికి ఉండటం” బాధ. దీనివల్ల “పుత్ర వియోగబాధ” అనుక్షణమూ ఉంటుంది. ఇవి వారిని సేవించవలసిన అవసరమూ, జొచిత్యమూ సూచిస్తున్నాయి. అందుకే ధర్మరాజు వారి సేవావిషయంలో “అనుదినంబు' జాగ్రత్తలు మళ్ళీ మళ్ళీ చెప్పటం."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","011","క.","విను మెల్లవారు నతని వ | చనములు మది నూఁది యట్ల చరియింప మరు\nత్తనయుండును నమ్మెయి వ | ర్తనము నడపుచుండు మనసు తద్దయు నెరియన్‌.","ప్రతిపదార్థం: వినుము= జనమేజయ రాజా! వినుము. ఎల్లవారున్‌= అందరూ కూడా; అతని వచనములు= ఆ ధర్మరాజు మాటలు; మదిన్‌= మనసులో; ఊంది= ఉంచుకొని (స్థిరపరచుకొని); అట్టు+అ= ధర్మరాజు చెప్పిన ప్రకారంగానే; చరియింపన్‌= నడుచుకుంటూ ఉండగా; మరుత్‌ తనయుండును= వాయువుత్రుడు-భీముడు కూడా; మనను= హృదయం; తద్దయున్‌= అధికంగా; ఎరియన్‌= బాధపడుతున్నా; ఆ+మెయిన్‌= ధర్మజుడు చెప్పినవిధంగా; వర్తనము= నడవడికను; నడపుచున్‌ ఉండున్‌= సాగిస్తూ ఉండేవాడు.","తాత్పర్యం: జనమేజయా! అట్టా ధర్మరాజు చెప్పిన మాటలు మనసులో ఉంచుకొని అందరూ, తమ్ములు, అమాత్యులు, భృత్యులూ, ఆ ప్రకారంగా ధృతరాష్ర్రుడిని కొలిచేవారు. భీముడు కూడా మనసులో బాధపడుతూనే అన్నగారి మాటలను అనుసరించి నడిచేవాడు.","విశేషం: భీముడు అన్నపై గౌరవం వలన ఇష్టం లేకున్నా ఎంత (నడపు-పేరణ క్రియ) బలవంతంగా ఆచరించేవాడో తెలుస్తుంది. ఎరియు ధాతువుకు మండటం అనే అర్థమూ ఉన్నది. అనిష్టుల సేవ చేయవలసివచ్చినందుకు బాధా వారిపై కోపమూను."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","012","క.","ద్యూతంబున దుర్యోధను | చేతం దమ పడిన పాటు చిత్తంబున క\nత్యాతురతఁ జేయుచుండుట | నాతఁడు ధృతరాష్ట్రుఁ జూచి యలుగు మనమునన్‌.","ప్రతిపదార్థం: ద్యూతంబునన్‌= జూదంలో; దుర్యోధనుచేతన్‌= దుర్యోధనుడు కారణంగా; తమ పడిన పాటు= తాము (పాండవులు) అనుభవించిన కష్టాలు; చిత్తంబునకున్‌= తన మనస్సుకు; అతి+ఆతురతన్‌= మిక్కిలి పీడను; చేయుచున్‌+ఉండుటన్‌= కలిగిస్తూ ఉండటం వలన; ధృతరాష్రున్‌= ధృతరాష్ర్రుడిని; చూచి అతడడు= ఆ భీముడు; మనమునన్‌=కా మనసులో; అలుగున్‌= కోవగించుకొనేవాడు.","తాత్సర్యం: దుర్యోధనుడివలన ఆనాడు జూదం మూలాన తాము అనుభవించిన కష్టాలు రాజ్యం పోవటం, భార్యకు సభలో అవమానం, అరణ్యవాసం మొదలైనవన్నీ భీముడి మనస్సును పీడిస్తుండేవి. అందువలన ధృతరాష్ర్రుడిని చూస్తేనే భీముడు మండిపడేవాడు.","విశేషం: పాండవులందరూ కష్టాలుపడ్డా ఆ స్మృతులు ఇంకా భీముడిని బాధిస్తున్నాయి. మిగిలిన నలుగురి కంటె భిన్నంగా భీముడి విషయంలోనే ఈ ప్రస్తావన. చూచి - మనసులో ఆ బాధ ఎపుడూ ఉన్నా ధృతరాష్ర్రుడిని చూసిన సమయంలో మాత్రం కోపం వచ్చేది. తమ కష్టాలకు హేతువైనవాడిని, అసలు రాజైన అన్నగారికంటె అధికంగా పూజించాల్సిరావటం కోవకారణం. మిగిలిన పాండవులు సర్దుకొన్నా స్వభావాన్ని బట్టి భీముడి కది కష్టం."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","013","తే.","శ్రాద్ధ దివసంబులందుఁ బుత్త్రవ్రజమున | కాంబికేయుండు గో కనకాది దాన\nకీర్త్యముగఁ బారలౌకిక క్రియలు సేయు | నట్లుగా సంఘటించు ధర్మాత్మజుండు.","ప్రతిపదార్థం: ఆంబికేయుండు= ధృతరాష్ట్రుడు; శ్రాద్ధ దివసంబులందున్‌= శ్రాద్ధ కర్మలను ఆచరించే మరణ తిథులలో; పు'త్రవ్రజమునకున్‌= దుర్యోధనుడు మొదలయిన కొడుకుల సముదాయానికి; పారలౌకిక క్రియలు= పుణ్యలోకాదులు కలగటం కొరకు చేసే కర్మలను; గోజ ఆవులు; కనక= బంగారం; ఆది= మొదలైన; దాన= దానాలచేత; కీర్యముగన్‌= బ్రాహ్మణాదిజనం ప్రశంసించే విధంగా; చేయునట్టుగాన్‌= నిర్వహించేటట్టుగ; ధర్మాత్మజుండు= ధర్మరాజు; సంఘటించున్‌= ఏర్పాటు చేసేవాడు.","తాత్పర్యం: “ఆందికేయుండు చేయునట్టుగా ధర్మాత్మజుండు సంఘటించు' అనడంలో ధృతరాష్ర్రుడికంటె ధర్మరాజులో ఎక్కువపూనిక వ్యక్తం అవుతున్నది. 'ధర్మాత్మజుండు” కాబట్టి ఇటువంటి శ్రియలలో శ్రద్ధ అధికం. అపకారులకు కూడ పుణ్యలోకాలు సాధించే ఉపకారబుద్ధి విశేషం. అభిమన్యు ప్రభృతిస్వజనవిషయం ప్రత్యేకంగా చెప్పనే అక్కరలేదు.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","","సీ.","అతులభోగంబును నంచితత్యాగంబుఁ | దొల్లింటియట్టుల చెల్లఁజేయు\nధృతరాష్ట్రునకు ధర్మసుతుఁడు గాంధారికిఁ | బూర్వప్రకార సంపూజ్యదాన\nనిరతిఁజెల్లించు; నక్కురువృద్ధుఁ డిమ్మెయిఁ | బాండుపుత్త్రులు దన్నుఁ బరమభక్తి\nశిష్యవర్తనమున సేవింపఁ దానును | గురునట్ల వాత్సల్యపరత నెపుడు","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","014","తే.","వారలకు శ్రీయు నాయువు వైరిజయము | మానసమున నాశాసించు మానవేంద్ర!\nయతని తొంటివర్తనముఁ దత్సుతుని కీడు | నాత్మఁ దలఁపఁ డెన్నండు ధర్మాత్మజుండు!","ప్రతిపదార్థం: మానవ+ఇంద్ర!= జనమేజయ మహారాజా!; ధర్మసుతుడు= ధర్మరాజు; ధృతరాష్ట్రునకున్‌= ధృతరాక్టుడికి; తొల్లింటి అట్టులు+అ= అతడి కొడుకులు బ్రతికివున్నపుడు సార్వభౌముడుగా ఉన్నప్పటివలెనే; అతులభోగంబునున్‌= సాటిలేనిసుఖాలూ; అంచిత త్యాగంబున్‌= పూజింపదగిన దానమూ; చెల్లన్‌ చేయున్‌= సాగేటట్టుగా చేసేవాడు; గాంధారికిన్‌= గాంధారికి కూడా; పూర్త్వ= మునుపటి (కొడుకులు జీవించి ఉన్నప్పటి); ప్రకార= విధంగానే; సంపూజ్య= పూజించదగిన; దాన= దానముయొక్క; నిరతిన్‌= ఆసక్తిని; చెల్లించున్‌= చెల్లేటట్టు చేసేవాడు; పాండుపుత్రులు= ధర్మజుడు మొదలుగా పాండురాజు కొడుకులు అందరూ; ఇమ్మెయిన్‌= ఈవిధంగా; పరమభిక్తిన్‌= శ్రేష్టమైన ఆరాధనా భావంతో; శిష్య వర్తనమునన్‌= శాసించబడే నడవడితో (శిష్యులవలె); తన్నున్‌= తనను; సేవింపన్‌= సేవిస్తూ వుండగా; ఆ+కురువృద్దుడు= కురువంశంలో పెద్దవాడైన ఆ ధృతరాష్ట్రుడు; తానును= తను కూడా; గురు+అట్టు+అ= పాండవులకు గురువువలెనే; వాత్సల్య పరతన్‌= పిన్నలయందుండేటటువంటి స్నేహభావం, ప్రధానంగా; వారలకున్‌= ఆ పాండవులకు; శ్రీయున్‌= రాజ్యాది సంపదలూ; ఆయువున్‌= అధిక జీవితకాలాన్నీ; వైరిజయమున్‌= శత్రువులను జయించే సామర్థ్యమూ కలగాలని; మానసమునన్‌కా తన మనస్సులో; ఎపుడున్‌= నిరంతరమూ; ఆశాసించున్‌= దీవించేవాడు; ధర్మాత్మజుండు= ధర్మరాజు; అతని= ఆ ధృతరాష్ట్రుడియొక్క; తొంటివర్తనమున్‌= పూర్వపు (దుర్యోధనాదులు జీవించిఉన్నప్పటి) నడవడికనూ; తద్‌ సుతుని కీడు= అతని కొడుకు దుర్యోధనుడు తమకు చేసిన అపకారమూ; ఎన్నండున్‌= ఏ సమయంలోనూ; ఆత్మన్‌= మనసులో (కూడా); తలయడు= స్మరింపడు.","తాత్పర్యం: జనమేజయా! వుత్రులు జీవించిఉన్నప్పటివలెనే ధృతరాష్ట్రుడికి సార్వభౌముడివలె సంపదలు అనుభవించటమూ, యథేష్టంగా దానం చేయటమూ సాగనిచ్చాడు ధర్మరాజు. అట్టాగే గాంధారికి కూడా ఆశ్రమవాసపర్వము : ప్రథమాశ్వాసము 417 ప్రతాదులసందర్భాలలో బ్రాహ్మణాదులకు దానం చేయటం వగైరా యథాపూర్వం సాగనిచ్చాడు. ధర్మరాజే కాదు ఇట్టా పాండవులందరూ శిష్యులవలె ఏకాగ్రతతో తనను సేవిస్తూ ఉండడంవలన ధృతరాష్ట్రుడు కూడా పాండవులను శివ్యవాత్సల్యంతో చూచేవాడు. పాండవులకు ఇంకా సంపదలూ, ఆయుస్స్ఫూ, శత్రుజయమూ కలగాలని మనస్సులో ఆశీర్వదిస్తుండేవాడు. ధర్మరాజు కూడా ధృతరాష్ట్రుడి పూర్వ ప్రవర్తననూ అతడి కొడుకు దుర్యోధనుడు తమకు చేసిన అపకారాన్నీ మనసులోనికి రానిచ్చేవాడు కాడు.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","015","క.","విను మతని తెఱఁ గెఱిఁగి పరి | జనములలో నాంబికేయు చరితము దుర్యో\nధను కొఱగామియు నెవ్వా | రును వాక్రువ్వంగ వెఱతురు కురుప్రవరా!","ప్రతిపదార్థం: కురుప్రవరా!= కురువంశంలో శ్రేష్టుడ వైన జనమేజయా!; వినుము= వినవలసినది; అతని= ఆ ధర్మరాజుయొక్క; తెఅయగు= విధం; (మనస్సు) ఎటి/గి= తెలిసి; పరిజనములలోన్‌= పరివారంలో (చుట్టూ ఉండే జనంలో); ఏ+వారును= ఏ ఒక్కడు కూడా; ఆంబికేయు= ధృతరాష్ర్ట్రుడియొక్క; చరితము= పూర్వపుప్రవర్తనం గురించీ; దుర్యోధను= దుర్యోధనుడి యొక్క; కొణ+కామియున్‌= (పనికిమాలినతనమూ) దుష్టమైన పని - కీడునూ; వాక్రువ్వంగన్‌= పలకటానికే; వెఅతురు= భయపడేవారు.","తాత్సర్యం: ఓ జనమేజయా! విను ధర్మరాజుతత్త్యం తెలిసిన అతని చుట్టు జనంలో ఎవరూ కూడా ధృతరాష్రుడి పూర్వ వర్తనమూ, దుర్యోధనుడు చేసిన అకార్యమూ ఉచ్చరించడానికే భయపడేవారు.","విశేషం: పరిజనములతో - అనే పూర్వ ముద్రితపాఠం సరికాదు. పరిజనంతో ఈ విషయాలెట్టా చెప్పుతారు? రాజు మనస్సు తెలిసికొని దానికి అనుగుణంగా రాజపరిజనం వ్యవహరిస్తుంది. అందుకే ధర్మరాజు మనసులో అతడి తొంటివర్తనమూ, తత్సుతుడి కీడూ - లే వనే విషయం గ్రహించారు - 'తెఅ6 గెజి6గి' చాల జాగ్రత్తగా పరిశీలించి తత్త్వం తెలిసికొన్నారు. అందుకే ఆంబికేయు చరితము, (అతని తొంటివర్తనము) దుర్యోధనుకొణగామి (తత్ఫుతునికీడు) గురించి ఉచ్చరించడానికీ భయపడేవారు."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","","సీ.","రాజ్యాధిపత్య సంపూజ్యత్వమున ధృత | రాష్ట్ర పాండుసుతాంతరంబు గాన\nరొకళులు జానపదోత్కరమునఁ బౌర | వర్గంబునందును వసుమతీశ!\nయమ్మెయి నడపెడు నప్పాండవాగ్రజు | వలన నిజాత్మజువలని కంటె\nనక్కురురాజు ప్రియం బందు; న ట్లున్న | యక్కాలమునఁ | బవనాత్మజుండు","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","016","తే.","సన్నిహితుఁ డైనయప్పు డజ్జనవిభుండు | తన తనూజులఁ దలఁచి సంతాప మందు;\nనతనిఁ గనుఁగొని యబ్భీముఁ డతనిసుతులు | తమ్ముఁ బఱిచిన పాటులు దలఁచి యలుగు.","ప్రతిపదార్థం: వసుమతీశో= ఓ జనమేజయ భూపాలా!; జానపద ఉత్కరమునన్‌= (గ్రామాలలో ఉండే జనాల సమూహంలోనూ; పౌర వర్గంబునందును= పట్టణాలలో ఉండే జనసముదాయంలోనూ; ఒకళులున్‌)= ఒక్కరు గూడా; రాజ్య ఆధిపత్య= రాజ్యము యొక్క దొరతనంతో; సంపూజ్యత్వమునన్‌= గౌరవింపబడేలక్షణంలో; ధృతరాష్ట్ర= ధృతరాష్ట్రుడికీ; పాండుసుత= పాండవులకూ; అంతరంబు= భేదం; కానరు= కనలేకపోయారు; ఆ+మెయిన్‌= ఆవిధంగా తన (ధృతరాకష్ర్రుడి)తో ఏకాభిప్రాయంగా; నడపెడు= పరిపాలనం సాగిస్తున్న; ఆ+పాండవ+అగ్రజువలనన్‌= పాండు కుమారులలో జ్యేమ్ణుడైన ఆ ధర్మరాజు వలన; ఆ+కురురాజు= ఆ ధృతరాష్ట్రుడు; నిజ+ఆత్మజువలనికంటెన్‌= తన సెద్దకొడుకైన దుర్యోధనుడి కంటె కూడా, ప్రియంబు= సంతోషాన్ని; అందును= పొందేవాడు; అట్టు+ఉన్న= ఆవిధంగా జరుగుతూ ఉన్న; ఆ+కాలంబునన్‌= ఆ రోజులలో; ఆ+జనవిభుండు= ఆ ధృతరాష్ట్రుడు; పవన+ఆత్మజుండు= వాయుపుత్రుడైన భీముడు; సన్నిహితుండు= దగ్గర ఉన్నవాడుగా; ఐన+అప్పుడు= అయిన సమయంలో; తన తనూజులన్‌= దుర్యోధన దుళ్ళాసనాదు లైన తన కొడుకులను; తలచి= స్మరించి; సంతాపము= మిక్కిలిబాధ; అందున్‌= పొందేవాడు; ఆ+భీముడు= ఆ సమయంలో భీముడు కూడా; అతనిన్‌= ఆ ధృతరాష్ర్రుడిని; కను/గొని= చూచి; అతని సుతులు= ధృతరాష్ర్రుడి కొడుకు లైన దుర్యోధనాదులు; తమ్మున్‌= తమను (పాండవులను); పజిచిన పాటులు= పెట్టిన కష్టాలు; తలంచి= స్మరించి; అలుగున్‌= ధృతరాష్ట్రుడి పై కోపగించేవాడు.","తాత్సర్యం: జనమేజయా! ఆ రాజ్యంలో ప్రభుత్వం నడిపే విషయంలో ధృతరా్రుడికీ, పాండవులకూ భేదం అనేది, అటు గ్రామవాసులు గాని, (ఇటు) పట్టణవాసులు గానీ చూడలేదు. ధర్మరాజు ఆ విధంగా తనను గౌరవిస్తుండటంవలన ధృతరాష్ట్రుడికి తన సొంత కొడుకుల కంటె కూడా ధర్మరాజు పైనే ఇష్టం కలిగేది. అయితే భీముడు తన దగ్గరకు వచ్చినపుడు మాత్రం కొడుకులను తలచుకొని బాధ పడేవాడు. భీముడు కూడా ధృతరాష్టుడిని చూస్తే అతనికొడుకులు తమకు కల్గించిన కష్టాలను తలచుకొని ధృతరాష్ట్రుడి పై కోపించేవాడు.","విశేషం: తన పెద్దకొడుకైనా దుర్యోధనుడితో వచ్చే అభిప్రాయభేదం ధర్మరాజుతో కలగకపోవడంవలన ధృతరాష్ట్రుడికి ధర్మరాజు కన్న కొడుకుకంటె ప్రీతిపాత్ర మయ్యాడు. అక్కడ కొడుకుమాట తాను వినవలసివచ్చేది. ఇక్కడ తనమాటే ధర్మరాజు వింటున్నాడు. ధృతరాష్ట్రుడికి భీముడిని చూస్తే పుత్రులు గుర్తుకు రావటానికి కారణం దుర్యోధన దుళశ్శాసనుల చావు భీముడివలన సంభవించడమే. భీముడిని చంపా లని న్వయంగా తానూ విఫలుడైనాడు కూడా. భీముడికీ ధృతరాష్ర్రుడిని చూస్తే గతం గుర్తుకు వస్తుంది. ఈ రెండింటిలో ముందు ధృతరాష్ట్రుడి విషయం ప్రస్తావించటం గమనించాలి. తనను చూచినపుడు ధృతరాష్రుడిలో కలిగే మార్పువలన అటువంటి “అతని” చూచినపుడు భీముడికీ గతం తలపునకు వస్తుంది."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","017","తే.","హృదయముల నొండొరులదెస నిట్టివార | లయ్యు నతఁడు నతండు నన్యోన్యభాష\nణములయప్పుడు మృదుల విన్యాస మొప్ప | నాడుదురు చుట్టములు మెచ్చునట్లు గాఁగ.","ప్రతిపదార్థం: అతడున్‌= ఆ ధృతరాష్ట్రుడూ; అతడున్‌= ఆ భీముడూ; ఒండొరులదెసన్‌= పరస్పరం, ఒకళ్ళ విషయంలో ఇంకొ కళ్ళు; హృదయములన్‌=ా తమ తమ మనస్సులలో; ఇట్టివారు= పూర్వం చెప్పినవిధంగా ద్వేషం కోపం కలిగినవారు; అయ్యున్‌= అయినప్పటికీ; అన్యోన్యభాషణముల+అవ్పుడు= పరస్పరం మాట్లాడుకొనేటవ్పుడు మాత్రం; చుట్టములు= బంధువులు; మెచ్చునట్టు+కాగన్‌= పొగడే విధంగా; మృదుల విన్యాసము= తెచ్చుకోలు మెత్తదనం; ఒప్పన్‌= ప్రకాశించేవిధంగా; ఆడుదురు= సంభాషిస్తుంటారు.","ప్రతిపదార్థం: అతడున్‌= ఆ ధృతరాష్ట్రుడూ; అతడున్‌= ఆ భీముడూ; ఒండొరులదెసన్‌= పరస్పరం, ఒకళ్ళ విషయంలో ఇంకొ కళ్ళు; హృదయములన్‌=ా తమ తమ మనస్సులలో; ఇట్టివారు= పూర్వం చెప్పినవిధంగా ద్వేషం కోపం కలిగినవారు; అయ్యున్‌= అయినప్పటికీ; అన్యోన్యభాషణముల+అవ్పుడు= పరస్పరం మాట్లాడుకొనేటవ్పుడు మాత్రం; చుట్టములు= బంధువులు; మెచ్చునట్టు+కాగన్‌= పొగడే విధంగా; మృదుల విన్యాసము= తెచ్చుకోలు మెత్తదనం; ఒప్పన్‌= ప్రకాశించేవిధంగా; ఆడుదురు= సంభాషిస్తుంటారు.","విశేషం: భీముడు అన్నగారిఆజ్ఞలను పాలించటానికి అయితే ధృతరాష్ట్రుడు తన పెద్దరికాన్ని కాపాడుకొనటానికి అయినా 'అతం డు నతడు అనే పదద్వయం వాళ్ళు కలివిడిగా లేక ఎవరికి వారుగా వేరుగా ఉండిపోవటాన్ని వ్యక్తం చేస్తున్నది. “విన్యాసం” శబ్దం మృదుత్వం తెచ్చి పెట్టుకొన్నది, కృతకమే, కాని హృద్ద్ధతం కాదని తెలుపుతున్నది."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","018","వ.","ధృతరాష్ట్రుం డేకతంబ యున్నయెడ వృకోదరుం డతనికి నింత నంత నుండి గాంధారి వినుచుండ.","ప్రతిపదార్థం: ధృతరా్ట్రుండు= ధృతరాష్ట్రుడు; ఏకతంబు+అ= ఒంటరిగా; ఉన్న+ఎడన్‌= ఉన్న సమయంలో; అతనికిన్‌= ఆ ధృతరాష్ట్రుడికి; ఇంతన్‌, అంతన్‌ ఉండి= ఇక్కడ అక్కడగా నిలిచి; గాంధారి= ధృతరాష్ర్రడిభార్య; వినుచున్‌+ఉండన్‌= వినేటట్టుుగా; వృకోదరుండు= భీముడు. (ఇట్లా అంటాడు. తర్వాతి పద్యంతో అన్వయం.)","తాత్పర్యం: ధృతరాష్ట్రుడు ఒంటరిగా ఉన్నపుడు అతడికి కొంచెం సమీపంగా ఉండి గాంధారి కూడా వినేటట్టుగా భీముడు ఇట్టా అంటాడు.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","","సీ.","‘అంధుని కొడుకులయం దొకరునిఁ దప్పి | పోనీక త్రుంచితి భూరిశక్తి\nదర్పితం బైన మద్బాహుపంజరము సొ | చ్చిన రిపురాజన్య సింహములకు\nవెడలంగ వచ్చునే? వెంగలు లై వారు | కయ్యంబు సేసిరి గాక నన్ను\nనెఱిఁగినఁ దొడరుదు రెట్టులు? దుర్యోధనాదుల ననిఁ దెగటార్చినట్టి","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","019","తే.","నాదు దోర్దండములఁ జందనం బలంది | కుసుమదామముల్‌ సుట్టి మ్రొక్కుదు మహోప\nకారు లరయంగ దైవముల్‌ గావె?’ యనుఁ ద | దీయ మర్మంబు లెల్ల భేదిల్ల నధిప!","ప్రతిపదార్థం: అధిప!= ఓ జనమేజయరాజా!; తదీయమర్మంబులు= ఆ గాంధారీ ధృతరాష్ర్టుల, జీవస్థ్రానాలు; ఎల్లన్‌= అన్నీ; భేదిల్లన్‌= చీలేటట్లుగా; అనున్‌= భీముడు ఇట్టా అన్నాడు; అంధుని కొడుకులయందున్‌= గ్రుడ్జిరాజు ధృతరాష్ట్రుడి కొడుకులలో; ఒకరునిన్‌= ఒక్కడిని కూడా; తప్పిపోన్‌+-ఈక= తప్పించుకు పోకుండ, మిగల్చకుండా; భూరి శక్తిన్‌= గొప్ప వర్యాక్రమంతో; శత్రుంచితిన్‌= చంపి వేశాను; దర్పితంబు+ఐన= మదించిన; మత్‌ బాహుపంజరము= నా భుజములు (వలయం) అనే బోనుల్‌నికి; చొచ్చిన= ప్రవేశించిన; రిపు, రాజన్య సింహములకున్‌= శత్రువులైన రాజులు అనే సింహాలకు; వెడలంగన్‌= బయటపడడానికి; వచ్చునే?= సాధ్యమా?; వారు= ఆ కౌరవులు; వెంగలులు+ఐ= తెలివితక్కువవారు. అయి; కయ్యంబు= (మాతో) యుద్దం; చేసిరి= చేశారు; కాక= (వెంగలులు) కాకపోతే; నన్నున్‌= నన్ను; ఎజి/గినన్‌= భూరిశక్తిమంతుడుగా తెలిసికొంటే; ఎట్టులు= ఏవిధంగా; తొడరుదురు?= ఎదిరిస్తారు? (యుద్దానికి పూనుకుంటారు?); అనిన్‌= యుద్ధంలో; దుర్యోధనాదులన్‌= దుర్యోధనుడు మొదలైనవారిని; తెగటార్చిన+అట్టి= చంపివేసినటువంటి; నాదు దోర్హండమున్‌= దుడ్డు కృర్రలవంటి నా భుజాలకు; చందనంబు= మంచి గంధాన్ని; అలంది= పూసి; కుసుమదామముల్‌= పూలమాలలు; చుట్టి= అలంకరించి; మ్రొక్కుదున్‌= నమస్కరిస్తాను; అరయంగన్‌= పరిశీలిస్తే; మహోపకారులు= ఇంత గొప్పమేలు చేసినవారు; దైవముల్‌= దేవతలె; కావె!= కదా!","తాత్పర్యం: జనమేజయరాజా! ఆ గాంధారీ ధృతరాష్ట్రుల ప్రాణస్థానాలు చీలిపోయేటట్లుగా భీముడు ఇట్లా అంటాడు; “గుడ్డివాడి కొడుకులలో ఒక్కడు కూడా మిగలకుండా అందరినీ చంపేశాను. నా బాహువలయం ఆనే బోనులోకి ప్రవేశించిన ఏ రాజసింహమైనా ఎట్టా బయటపడగలదు? మూర్ధులు కాబట్టి ఆ కౌరవులు మాతో యుద్దానికి వచ్చారుకాని, నా పరాక్రమం తెలిస్తే ఎదిరించేవారే కాదు. ఆ యుద్ధంలో దుర్యోధనప్రభృతు లందరినీ కూల్చిన యీ నా భుజాలకు చందనం పూసి, పూలమాలలు చుట్టి నమస్కరిస్తాను. నిజానికి ఇంత గొప్ప ఉపకారం చేసింది దేవతలే కదా!”","విశేషం: ధృతరాష్ట్రుడు అంధుడే అయినా దుర్యోధనాదుల మాటలను గుడ్డిగా నమ్మి ఇంతకు తెచ్చుకొన్నాడు కాబట్టి ఇక్కడ సాభ్మిప్రాయం. 'అంధుని కొడుకులు” కావడం చేతనే దుర్యోధనాదులు కూడా అంధులై అవివేకులై ప్రాణాలమ్‌దకు తెచ్చుకొన్నారు. “భూరిశక్తి\"' అన్నపుడు భూరి అనేది తన వరాక్రమంలో గొప్పదనాన్ని చెప్తుండగా, 1త్రుంచితి' అనేది కౌరవులను “అవలీలగా” చంపటం తెలుపుతుంది. చొచ్చిన - భూతార్థకం, ప్రవేశించడం జరిగిపోయాక - వెడలంగన్‌ ఆ తర్వాత కోరుకొన్నా తప్పుకోవటం అనేది మాత్రం వాళ్ళ చేతులలో లేదు. రోట్లో తల దూర్చాక చేసేదేం లేదు. త్రుంచితిన్‌ - అనే ఉత్తమపురుపైకవచనక్రియ, అట్టాగే “నన్ను నెజిణగిన దుర్యోధనాదుల తెగటార్చినట్టి నాదు దోర్హండములు” మొదలైన మాటలో అస్మదర్థం - భీముడి వికత్థనత్వానికీ, ధృతరాష్ట్రుడి పై కోపతీప్రతకీ నిదర్శనాలు. అంధుని మొదలుగా ఇందులో మాటలన్నీ గాంధారీ ధృతరాష్ర్రులకు మర్మభేదకాలే. మద్బాహుపంజరము చొచ్చిన - వెడలంగవచ్చునే” అనేది ధృతరాష్రుడు తన బాహు పంజరంలో చంపుదామనుకున్నా తాను (భీముడు) వెడలివచ్చిన విషయాన్ని స్మరింపజేస్తూ తన సామర్థ్యంలో ధృతరాష్ట్రుడి అసమర్థతను (వెంగలితనం) ఎత్తి చూపుతుంది. -ఈ మహోపకారం దేవతలు చేసిందే అనడం ఈ అంశాన్ని ప్రధానంగా ఉద్దేశించి ఉండవచ్చును. భీముడు బ్రతికి బయటపడ్డ దందువలననే కదా! చివర్గో ఆఖరిఘట్టమూ భీముడికి గుర్తు వచ్చింది."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","యుధిష్ఠిరాదులును గాంధారీధృతరాష్ట్రులును నొండొరులయెడల నడచికొనిన ప్రవర్తనము: (సం. 15-1-1)","020","వ.","దీని ధర్మనందనుండును ధనంజయుండునుం గుంతియు ద్రౌపదియు నెఱుంగరు; కవ లొక్కొక్క మాఱిమ్మాటలు విని సంతసిల్లుదురు; ధర్మనందను తెఱం గెఱుంగుటంజేసి పుయిలోడి తా రేమియు నాడరు; ధృతరాష్ట్రగాంధారులుం గాలపర్యాయంబు గని డెందంబులు గంద నూరకుండుదు; రట్టిభంగిఁ బంచదశవత్సరంబులు చనియె నంత నొక్కనాఁ డయ్యంధనృపతి బంధుజనంబులం గూర్చి ధర్మనందను రావించి; యతండు వినుచుండ గద్గదకంఠుం డగుచు వారలతోడ.","ప్రతిపదార్థం: దీనిన్‌= భీముడు ధృతరాష్ట్ర గాంధారులు నొచ్చుకొనేటట్టుగా మాటాడటం; ధర్మనందనుండును= ధర్మరాజూ; ధనంజయుండునున్‌= అర్జునుడూ; కుంతియున్‌= కుంతీ; ద్రౌపదియున్‌= ద్రౌపదీ; ఎబయుంగరు= తెలియరు; ఈ+మాటలు= భీముడి ఈ పలుకులు; ఒక్కొక్కమారు= అపుడప్పుడూ; విని= ఆలకించి; కవలు= నకులసహదేవులు; సంతసిల్చుదురు= సంతోషించేవారు; తారు= తాము మాత్రం; ధర్మనందను= ధర్మరాజుయొక్క; తెఅంగు= (మనస్సు) విధం; ఎయుంగుటన్‌ చేసి= తెలిసినందువలన; పుయిలోడి= సంకోచంతో; ఏమియున్‌= ఏమి; ఆడరు= మాటాడరు; ధృతరాక్ట్రగాంధారులున్‌= ధృతరాష్ర్రుడూ, గాంధారీ; (ఆ మాటలు విని) కాల వర్యాయంబు= సమయం తారుమారవటం; కని= తెలిసి; డెందంబులు= మనసులు; కందన్‌= కలత చెందగా; ఊరకుండుదురు= మిన్నకుండేవారు; అట్టిభంగిన్‌= ఆవిధంగా; పంచదళవత్సరంబులు= వదిహేను ఏండ్లు; చనియెన్‌= గడిచాయి; అంతన్‌= పనిహేనోయేడు పూర్తయినతర్వాత; ఒక్కనాడు= ఒకానొకరోజు; ఆ+అంధనృపతి= ఆ (గుడ్డిరాజు) ధృతరాష్ట్రుడు; బంధుజనబులన్‌= చుట్టాలను; కూర్చి= సమావేశపరిచి; ధర్మనందనున్‌= ధర్మరాజును; రావించి= పిలిపించి; అతండు= ఆ ధర్మరాజు; వినుచున్‌+ఉండన్‌= వింటుండగా; వారలతోడన్‌= బంధువులతో; గద్గదకంఠుండు= డగ్గుత్తిక కలవాడు; అగుచున్‌= అవుతూ-(ఇట్లా అంటున్నాడని తరువాతి పద్యంతో అన్వయం.)","తాత్పర్యం: భీముడు పలికేమాటలు ధర్మరాజుకూ, అర్జునుడికీ, కుంతికీ, ద్రాపదికీ తెలియవు. నకుల సహదేవులు మాత్రం అప్పుడప్పుడూ ఆ మాటలు విన్నా, ధర్మరాజుపట్ల ఉన్న భయం వలన వారు మారు పల్కరు. గాంధారీధృతరాష్రులు కాలవైపరీత్యాన్ని గమనించి మనసులలో బాధపడుతూ మిన్నకుండేవారు. అట్టా పదిహేనేళ్ళు గడిచాయి. ఆ తరువాత ఒకనాడు ధృతరాష్ట్రుడు బంధువులనందరినీ సమావేశపరిచి, ధర్మజుడిని పిలిచి అతడు వింటూఉండగా, బొంగురుపోయిన గొంతుతో వారందరితో ఇట్లా అన్నాడు.","విశేషం: ధర్మరాజు అర్జునుడు, కుంతితోపాటు, ద్రౌపది కూడా గతంలో కౌరవులవలన కలిగిన కష్టాలను మరిచిపోయి గాంధారీ ధృతరాష్ట్రులపై గౌరవంతో వ్యవహరిస్తున్నారు. అందుకే వా ళ్ళైవరూ వినకుండానే భీముడు సై విధంగా మాటాడేవాడు. కవలు ఆమోదించేవాళ్ళు కావటం చేతనే ఒక్కొక్కమారైనా భీముడి మాటలు వినగలిగారు. ధర్మనందను తెఅంగు భీముడికీ తెలిసినా పిన్నలు కావడంచేత నకులసహదేవులు ఏమైనా అనడానికి సంకోచించేవారు. స్వభావం వలననూ, ధర్మరాజుకు వెంటనే జన్మించినవాడు కావడంవలననూ భీముడు నిస్సంకోచంగా అనదలచుకొన్నమాట లనేవాడు. పరోక్షంగా నైనా ధృతరాష్ట్రుడికి కొడుకులు బతికున్నప్పటి వలె నడపటానికి ప్రయత్నించినవాడు ధర్మరాజు (14పద్యం) తేడా లే దనిపించటానికి ధర్మరాజు ప్రయత్నించినా భీముడివలన గాంధారీధృతరాష్ట్రులకు 'కాలపర్యయ' భావన రాక తప్పలేదు. అయినా 15 సంవత్సరాలు ఊరకుండటంలో వార్రకాదులతోపాటు ధర్మరాజునడవడీ, 'చుట్టములు మెచ్చునట్లు' ఉండాలనే అభిప్రాయం కారణం. ఇపుడొకసారి తన జీవితాన్నంతా గుర్తుచేసుకొనడమూ, నగరం విడిచిపోవటం, (ఆశ్రమవాసం) అనే నిర్ణయం ప్రకటించబోతూండటం, వలన కంఠంలో గాద్గద్యం. ధర్మరాజును రప్పించి అతడు వింటూఉండగా బంధువులకు చెపుతున్నాడు. ధర్మరాజుతో ముఖాముఖిగా చెప్పటానికి కాకుండా, తన ఆంతర్యం, యథార్థంగా పరోక్షంగా వ్యక్తం చేసినట్టుగా గూడ. గతంలో తాను పొరపాట్టు చేశానని చెపుతున్నాడు మరి. ధృతరాష్ట్రుడు ధర్మజునితో దన మనోరథంబు/౮ దెలుపుట (సం.15-5-1)"],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","","సీ.","నాకతంబునఁ జేసి యా కౌరవులకు నా | శంబు వాటిలుట దెల్లంబు మీకు\nజడుఁ గ్రూరు నతిలోభి జ్ఞాతి జనద్రోహ | కరు రాజుఁ జేసితిఁ గురుధరిత్రి\nకచ్యుతు చెప్పిన యమలవాక్యంబులు | విననేరనైతి నా తనయువలని\nఘనతరస్నేహంబునను మొగమోటను | దగియెడుమాటలఁ దఱిమి యొత్తి","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","021","తే.","యాడకుండితి; భీష్ముండు నస్త్రగురుఁడు | విదురుఁడును సంజయుండును వే విధముల\nనాకుఁజెప్పిరి; గాంధారి నన్ను దూఱి | చెప్పె; న మ్మాట లేఁ బెడచెవుల నిడితి.","ప్రతిపదార్థం: నా కతంబునన్‌+చేసి= నా కారణంగా; ఆ కౌరవులకున్‌= నా పుత్రులు మొద లైన కురువంశీయులకు; నాశంబు= చేటు; పాటిలుట= సంభవించటం; మీకున్‌= (నా బంధువు లైన) మ్‌ అందరికీ; తెల్లంబు= బాగా తెలిసిందే; కురుధరిత్రికిన్‌= కురువు అనేపేరు గల్లిన ఈ రాజ్యానికి; జడున్‌= (ఒకానొక) బుద్ధిహీనుడూ; క్రూరున్‌= దుష్ట బుడ్జీ; అతిలోభిన్‌= మిక్కిలిగా పరద్రవ్యాభిలాష ఉన్నవాడూ; జ్ఞాతిజనద్రోహకరున్‌= దాయాదులకు కీడు చేసేవాడూ అయిన దుర్యోధనుడిని; రాజున్‌= పాలకుడుగా; చేసితిన్‌= ఏర్పరిచాను; అచ్యుతు= శ్రీకృష్ణుడు; చెప్పిన= బోధించిన; అమలవాక్యంబులు= దోషం లేని (అర్థ్హవంతములైన) మాటలు; వినన్‌, నేరన్‌, ఐతిని= ఆలకించకపోయాను; నాతనయు వలని=ా దుర్యోధనుని యెడ ఉన్న; ఘనతర= మిక్కిలి అధికమైన; స్నేహంబునను= ట్రేమవలనను; మొగమోటను= నంకోచంతోనూ; తజిమి= తనమాట వినేంతవరకూ విడువకుండా; ఒత్తి= ఒత్తిడి చేసి (బలవంతంగా); తగియెడు మాటలన్‌=ా ఉచితమైన పలుకులను; ఆడక+ఉండితిన్‌= చెప్పలేదు; నాకున్‌= నాకు;భీష్ముండున్‌= పితామహుడైన భీమ్ముడూ; అస్త్ర గురుడు (ను)= పిల్లల కస్త్రవిద్య నేర్పిన ట్రోణుడూ; విదురుడును= విదురుడూ; సంజయుండును= సంజయుడూ, వేవిధములన్‌= అనేక విధాలుగా; చెప్పిరి= (కర్తవ్యం, ఉచితం) చెప్పారు; గాంధారి= నా భార్య గాంధారీ; నన్నున్‌= నన్ను; దూజి= నిందిస్తూ, దృఢంగా; చెప్పెన్‌= మంచి ఏదో (కర్తవ్యం) గట్టిగా చెప్పింది; ఏన్‌= నేను; ఆ+మాటలు= వారందరి పలుకులూ; పెడచెవులన్‌+ఇడితిన్‌= నిరాదరణంతో వినిపించుకొనలేదు.","తాత్పర్యం: నా కారణంగానే కౌరవులు నాశనమైనారని మికు బాగా తెలుసు. బుద్ది లేనివాడూ, దుర్మార్ల్గుడూ, ఇతరుల ద్రవ్యంపై అధికమైన అభిలాష ఉన్నవాడూ, దాయాదులకు కీడు చేసేవాడూ అయిన దుర్యోధనుడిని ఈ కురురాజ్యానికి రాజును చేశాను. కృష్ణుడు చెప్పినా వినలేదు, కొడుకుమ్‌ది వల్లమాలిన ప్రేమవలన వారికి మంచిని ముఖంమ్‌ద గట్టిగా చెప్పలేకపోయాను. భీష్ముడూ, ద్రోణుడూ, విదురుడూ, సంజయుడూ చెప్పినా, గాంధారి మరీ నొక్కిచెప్పినా ఆ మాట లేవీ నేను వినిపించుకొనలేదు.","విశేషం: 'నా కతంబున అని గతాని కంతా తానే కారణం కావడం అనే అంశంతోటే ప్రారంభించటం ధృతరాష్ట్రుడి ఆత్మ పరిశీలనకు అర్థం. కౌరవనాళనం అనే సారాంశం చిన్న వాక్యంలో సంగ్రహంగా ముందు ప్రతిపాదించి ఆ తర్వాత అందుకు కారణాలు క్రమంగా వివరిస్తున్నాడు. అందులో ముఖ్యమైనది దుర్యోధనుడిని రాజు చేయటమే, “రాజు జేసితి' అనటంలో అది పొరపాటు అనీ, అందువలన ధర్మరాజును చేసి వుండాల్సిందనీ వ్యక్తం అవుతుంది. 'యచ్చాహం పాండు పుత్రేషు గుణవత్సు మహాత్మను, న దత్తవాన్‌ శ్రియం దీప్తాం పితృపైతామహీ మిమామ్‌'. తెలుగులో ధృతరాషష్ట్రుడీ మాటలు వాచ్యంగా తననోటిమిదుగా ఇప్పటికీ అనలేకపోయాడు. దుర్యోధనుడిలోని గుణహీనతను ప్రతిపాదిస్తూ పాండవులు గుణవంతు లనీ, (రాజ్యం వారి కివ్వవలసిందనీ) వ్యంగ్యంగా అంగీకరిస్తున్నాడు. 'రాజు6 జేసితి కురుధరిత్రికి' అన్నపుడు కురుధరిత్రి అనేమాట పితృపైతామహీయం కాబట్టి రాజ్యం పితృపితామహ।క్రమ। ప్రాప్తం” (అనే అంశం అందరికీ తెలిసిన సామాన్య విషయంగా) అని ఈ మాట మొదటే(2వ) చెప్పటం అయింది. “రాజు జేసితి “గురుధరిత్రి\" కన్నపుడు రాజుడేసితి/ గురుధరిత్రికి అన్నప్పుడు గు” వర్షాన్ని ఎట్టా స్వీకరించడం? అల్బబుద్ధి అయిన దుర్యోధనుడిని రాజు చేయగూడదు. కొంత కొడుకున కిచ్చి, కొంత భాగాని కైనా పాండవులను రాజులను చేసి ఉంటే ఇంత అనర్థం, కౌరవనాళనం ఆగిఉండేది అని భావం. ఇక్కడ దుర్యోధనుడి గుణహీనతనూ, అల్పత్వాన్నీ ప్రతిపాదించే విశేషణాలు అర్థవంతాలు - జడుడు. మందబుద్ది. మంచిచెడులు స్వయంగా తెలియలేడు. పాండవులను ద్వేషించటంద్వారా ప్రజలకు వారిపై అభిమానం ఇనుమడింవజేశాడు. క్రూరుడు - ద్రౌపదిని పరాభవించడం వగైరా విషయాలలో క్రూరత్వం. సున్నితంగా చెప్పిన తన (ధృతరాష్ట్రుడి) మాటలు వినిపించుకొనక తనను బాధించటం వలననూ పాండవుల రాజ్యం ఆశించటంలో అయిదూళ్ళయినా ఇవ్వననటంలో అతిలోభం. -ఈ లక్షణాలు లేని ధర్మరాజును రాజు చేయవలసింది. జ్ఞాతిద్రోహకరున్‌ అనడంలో ఇతరులకు ద్రోహకారి కాదు. ప్రజలను బాగానే చూచాడు (99 పద్యం). దాయాదిశ్మత్రుత్వం సామాన్యమే అనే అభిప్రాయం ఉండవచ్చును. 'అచ్యుతు మాటలలో చ్యుతి= పొల్పు లేదు. 'వధ్యతా సా ధ్వయం పాప సామాత్య ఇతి దుర్మతిః” అని దుర్యోధనుడిని అతడి సహచరులనీ చంపుమనే చెప్పాడు కృష్ణుడు మూలంలో. తండ్రికి ఈ మాటలు ఏ సమయంలోనైనా బాధాకరాలే. ఆ మాట లేదో ధృతరాష్ర్రుడిక్కడ చెప్పలేదు. 'నీ పుత్రుల డవినీతుడగుట యెజి/గి యెటి/గి వానివశంబున నేల పోయె దీవు పాండవులకు నేమి యిచ్చి తేని నడ్డపడ నెవ్వరికి వచ్చు నధిప' (ఉద్యో 3,986) అంటాడు. ఇంతకుముందు కృష్ణుడు కురుధరిత్రి మొత్తానికి దుర్యోధనుడిని రాజు చేశాననే కదా ధృతరాష్ట్ర డిక్కడ బాధ పడుతున్నది. కృష్ణు డన్నట్టు కొంతైనా పాండవుల కిచ్చి ఉన్న ట్లయితే అచ్యుతుమాటలు అమలములుగా ఆ రోజే గ్రహించి విని ఉన్నట్టయితే తన వంశానికి 'చ్యుతి” లేకుండా ఉండేది. పాండవవళ్టపాతంతో అంటున్నాడని ఆ రోజు కృమ్ణడి మాటలు నివ్కల్మషాలుగా గుర్తించలేక పోయాడు - 'అమలవాక్యంబు లని” ఇప్పుడు తలచుకొంటున్నాడు అనుభవంలోకి వచ్చాక తెలిసింది. వుత్రుడివళంలో ఆ మార్గంలో పోవద్దన్నాడు కృష్ణుడు 'నా తనయువలని వునతరస్నేహంబునను అనేది వూర్వంలోకీ “అన్వయిన్తుంది”. అచ్యుతు చెప్పిన అమల వాక్యంబులు విననేరనైతి నా తనయువలని ఘనతరస్నేహంబున. అందువలననే పుత్ర వళవర్తి అయినాడు. దుర్యోధనుడి కిష్టం లేకుండా పాండవులకు రాజ్యం ఇవ్వలేకపోయాడు. అట్టా అని దుర్యోధనుడిని ఇష్టపణచనూ లేకపోయాడు. అదే చెప్పుతున్నాడు. స్నేహమునను మొగమోటను తగుమాటలు చెప్పలేకపోయాను కొడుక్కి అని. మొగమోటకు కారణం పుత్రస్నేహం. కొడుకు ఏం బాధపడతాడో అని అతడి కిష్టం లేని మాటలు చెప్పలేకపోయాడు. 'తజిమి యెత్తి ఆడకుండితి” తగియెడు మాటలు, వెంటబడి, బలవంతంగా చెప్పాలి దుర్యోధనుడికి, మంచిమాటలు మామూలుగా మనసు కెక్కకపోవడం దుర్యోధనుడి స్వభావం అన్నమాట తనమాటలు కొడుకు వినలేదు; భీష్మాదులు చెప్పినమాటలు తాను పెడచెవినిపెట్టాడు, కారణాలు వేరుగా ఉన్నా తండ్రికొడుకులకు మంచి వినిపించుకొకపోవడం అనే లక్షణం సమానం. అయితే తనమాటలు వినలే దని కొడుకుపై తప్పుమోపకుండా, వినేటట్టుగా నేనే చెప్పలేకపోయానన్నాడు. తగిన మాటలు చెప్పినా - తజిమి, ఒత్తి చెప్పలేదు అపుడపుడూ అనడమే తప్ప తనమాట వినేదాకా వెంటబడి చెప్పలేదు. చెప్పినపుడు వినితీరవలసినంత దృఢంగానూ చెప్పలేదు. దుర్యోధనుడి ముఖంలో కనిపించే అనిష్టభావం చూడలేక, అతడికి సమ్మతం కాని తగుమాటలు చెప్పటంలో ధృతరాష్ట్రుడికి మొగమోటమి ఘనతరస్నేహం అన్నప్పటి తరప్‌ ప్రత్యయం పాండవులకంటేె, కృష్ణాదులు చెప్పినమాటలలో హితం కంటె అధిక స్నేహాన్ని వ్యక్తం చేస్తుంది. భీష్మాదుల ప్రస్తావనలో, పెద్దలూ, పిన్నలూ, అందరూ చివరికి పతిప్రత ఐనభార్యా కూడా నిందించి మరీ చెప్పినా వినకపోవడం తప్పయిందనుకొంటున్నాడు 'ఆస్రగురుడు” కావడంవలన కౌరవపాండవుల శృస్రాస్త సామర్థ్యం ద్రోణుడికి తెలుసు. యుద్ధం వస్తే తనకొడుకులకు నాశం తప్పదని అఆస్తగురుడిమాటలతో నైనా గ్రహించవలసింది. “నన్ను దూజఉి' గాంధారి ధృతరాష్ర్రుడిలో దూరిపోయి= ప్రవేశించి అంటే నిరంతరము చెప్పింది. విననేరనైతిని, ఆడకుండితివంటి భూతార్థకాలు - అంతా అయిపోయింది. ఇపుడు బాధపడి ప్రయోజనం ఏముంది ఆనేభావం వ్యక్తం చేస్తున్నాయి 'సెడ చెవిని ఇడితి\" అనే మాటలు తేలిపోతూ, ఆ మాటలు, ఆదరించకపోవటాన్ని ధ్వనింపచేస్తున్నాయి."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","022","వ.","ఇత్తెఱం గంతరంగంబున శల్యం బై యున్నయది, యని చెప్పి వెండియు.","ప్రతిపదార్థం: ఈ-+తెఅంగు=ా పైవిధంగా ఎవరు చెప్పినా వినకుండా కొడుకులను, (హితులు మొ॥!) పోగొట్టుకోవడం; అంతరంగంబునన్‌= మనస్సులో (గుచ్చుకొని బాధించే); శల్యంబు ఐ= బాణం, అయి; ఉన్నది= నిలిచి ఉన్నది; అని చెప్పి= అని పలికి; వెండియున్‌= తిరిగి ఇట్టా అంటున్నాడు.","తాత్సర్యం: ఈ విధం నా మనస్సులో ములుకై బాధపెట్టుతున్నది అని చెప్పి మరలా ఇట్టా అన్నాడు.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","023","క.","సుతులు సమరమునఁ దిరుగక | మృతు లై సద్గతికిఁ జనిన మేలిమి యస్మ\nన్మతిఁ దలఁచి వరక్షత్త్ర చ| రిత మని యప్పనికి వగవఁ బ్రీతియ కలుగున్‌.","ప్రతిపదార్థం: సుతులు= కొడుకులు; సమరమునన్‌= యుద్ధంలో; తిరుగక= పారిపోయి తిరిగిరాకుండా; మృతులు+ఐ= చనిపోయి; సద్గతికిన్‌= ఉత్తమస్థితికి; చనిన మేలిమి= చేరుకున్న గొప్పతనాన్ని; అస్మద్‌+మతిన్‌= నామనస్సులో; తలంచి= స్మరించి;- (అది), వరక్షత్రచరితము= శ్రేష్టమైన క్షత్రియుడికి తగిన లక్షణం; అని= అనుకొని; ఆ+పనికిన్‌=యుద్ధంలో వారి మరణానికి; వగవన్‌= బాధపడను; ప్రీతి+అయ= ఇంకా (ఆ పని వలన), సంతోషమే; కలుగున్‌= కలుగుతున్నది.","తాత్పర్యం: యుద్ధం కోరిన కొడుకులు క్రమంగా అపజయం కలుగుతున్నా పారిపోయి వెనుకకు రాకుండా అందరూ మరణించి ఊర్ధ్యలోకాలకు చేరుకొన్నారు. అది క్షత్రియులకు తగినదే కాబట్టి అందుకు నేను విచారించను. ఇంకా సంతోషమే పొందుతున్నాను.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","024","వ.","అని పలికి పాండవాగ్రజుఁ జేరం బిలిచి, యతనితోడ.","ప్రతిపదార్థం: అని పలికి= బంధువులతో పైవిధంగా చెప్పి; పాండవ+అగ్రజున్‌= పాండురాజు సుతులలో పెద్దవాడైన ధర్మరాజును; చేరన్‌= దగ్గరకు; పిలిచి= రమ్మని; అతని తోడన్‌= ధర్మరాజుతో (ఇట్టా అంటున్నాడు - తరువాతి పద్యంతో అన్వయం).","తాత్పర్యం: బంధువులతో ఈ విధంగా పలికి, ధర్మరాజును దగ్గరకి పిలిచి అతడితో ఇట్టా అంటున్నాడు.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","","సీ.","నీ వరయంగ సుఖావాప్తిఁ గొఱఁత లే | కుండితిఁ జనవును నుజ్జ్వలంపుఁ\nదేజంబుఁ గలిగి వర్తించితి దానంబు లంచితములుగఁ బె క్కాచరింపఁ\nగంటి శ్రాద్ధంబులు గాంధారిసుతులకుఁ | బలుమాఱుఁ జేసితిఁ; బరమధర్మ\nశీల పాంచాలికిఁ జెట్ట చేసి రగణ్య | పుణ్యుండ వగు నీదు భూరిలక్ష్మి","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","025","తే.","నపహరించి రద్దుర్యోధనాదు లట్టి; కష్టచరితులఁ బాడిమైఁ గయ్యమునన\nనిహతులుగఁ జేసి తక్కురునికర మూర్ధ్వ; భువనగతిఁ గాంచి సుఖ మందె భూపవర్య!","ప్రతిపదార్థం: భూపవర్య!= రాజులలో క్రేష్టుడా! నీవు= నీవు (ధర్మరాజు); అరయంగన్‌= పరిశీలింపగా; సుఖ+అవాప్తిన్‌= రాజ్యం మొదలైన సుఖాలు పాందటం చేత; కొతత లేక= ఏలోటూ లేకుండా; ఉండితిన్‌= ఉన్నాను; చనవును= ప్రేమా; ఉజ్జలంపు= మిక్కుటమైన; తేజంబున్‌= ప్రకాళమూ; కలిగి= కలిగిఉండి; వర్తించితిన్‌= నడుచుకొన్నాను. (అందువలననే నేను) దానంబులు= దానాలు; పెక్కు= చాలా; అంచితంబుగన్‌= ప్రశస్తంగా; ఆచరింపన్‌+కంటిన్‌= చేయగలిగాను; గాంధారిసుతులకున్‌= దుర్యోధ నాదులకు; శ్రాద్దంబులు= శ్రాద్ధాలు; పలుమాయన్‌=ా అనేక పర్యాయాలు; చేసితిన్‌= చేశాను; దుర్యోధనాదులు= దుర్యోధనుడు మొదలైన కొడుకులు; పరమ ధర్మశీల= ఉత్తమమైన న్యాయపు నడవడి గలిగిన; పాంచాలికిన్‌= (ద్రౌపదికి; చెట్ట= కీడు; చేసిరి= చేశారు; అగణ్య= లెక్కింపరాని; పుణ్యుండవు= ధర్మములు గలిగినవాడవు; అగు= అయిన; నీదు భూరిలక్ష్మిన్‌= నీ గొప్ప సంపదను; దుర్యోధన+ఆదులు= దుర్యోధనుడు మున్నగువారు; అపహరించిరి= కాజేశారు; అట్టి= అటువంటి; కష్టచరితులన్‌= దుర్మార్గపు నడత గలిగిన దుర్యోధనాదులను; కయ్యమునన్‌+అ= యుద్దంలోనే; పాడిమైన్‌= న్యాయంగా; నిహతులుగన్‌= చంపబడినవారినిగా; చేసితివి)= చేశావు (చంపావు); ఆ+కురునికరము= యుద్ధంలో నీవు చంపిన ఆ కౌరవ వీరు లందరూ; ఊర్ద్వ భువన గతిన్‌= ఉత్తమలోకాలలో, ఉనికిని; కాంచి= పొంది; సుఖము= సుఖాన్ని; అందెన్‌= పొందారు.","తాత్పర్యం: 'రాజక్రేష్టుడా! ధర్మరాజా! నీవు ఏలోటూ లేకుండా చూస్తూ ఉండగా సుఖంగా ఉన్నాను. అభిమానాన్నీ, ఇతర జనాలపై ప్రభావాన్నీ, (అధికారమూ) చూపుతూ వ్యవహరించాను. నీవలన గొప్పదానాలు చేయగలిగాను. మా పుత్రులకు శ్రాద్ధక్రియలు పలుసార్లు మేలుగా చేయగలిగాను. ఉత్తమురాలైన పాంచాలిని పరాభవించి, నీ సంపదలు కాజేసిన దుర్యోధనాదులను న్యాయంగా యుద్దంలోనే చంపావు. వాళ్లందరూ ఉత్తమలోకాలలో సుఖంగా ఉన్నారు.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","026","క.","కావున నేమియుఁ జేయం | గా వలవదు వారికయి యకారణ కరుణా\nశ్రీవిలసితుఁ డగునీతో | నా విధముం జెప్పవలసె నరవరముఖ్యా!","ప్రతిపదార్థం: నరవరముఖ్యా!= రాజ శ్రేష్టా! (ధర్మరాజా!); కావునన్‌= అందుచేత; వారికయి= పుత్రులకొరకు; ఏమియున్‌=ా ఇంక ఏ విధమైన పనులూ; చేయంగాన్‌= చేయటం; వలవదు= అవసరం లేదు; అకారణ= హేతువు (ప్రయోజనం మొ॥) లేకుండానే;కరుణాశ్రీ= దయాసంపదతో; విలసితుడు+అగు= ప్రకాశిస్తూ ఉన్న; నీతోన్‌= నీతో; నా విధమున్‌=ా నన్ను గురించి; చెప్పవలసెన్‌= చెప్పవలసి ఉన్నది.","తాత్పర్యం: రాజా! దుర్యోధనాదులకొరకు దాన ్రాద్హాదికార్యాలు అనేకం చేశాను. కాబట్టి ఇక వారికొరకు కొత్తగా చేయవలసిం దేమి లేదు. సహజంగా దయ గలిగిన నీతో ఇపుడు నావిషయమే చెప్పుకోవలసి ఉన్నది.","విశేషం: 'అకారణ కరుణాశ్రీవిలసితుండు' అనే విశేషణం సాభిప్రాయం. ధృతరాషష్ట్రుడిపై చూపుతున్న అభిమానాన్నీ దుర్యోధనాదులకు పుణ్యలోక ప్రాప్తి దానాదు లేర్చరచటాన్నీ సూచిస్తూనే తర్వాత తాను కోరబోయే అంశం కూడా తప్పక నెరవేర్చాలి అని ధృతరాష్ర్రుడి అభిప్రాయం."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","","సీ.","ఏ కార్యమైనను నెవ్వఁడేనియుఁ జేయఁ | దొడఁగునప్పుడు విను పుడమిఱేని\nచే ననుజ్ఞాతుఁ డై కాని తొడంగఁ గా | దట్లు గావున వార్థకాభిలీఢ\nమైన మదీయకాయమునకు సంస్కార | మాచరింపఁగఁ దప మాచరించు\nపనికి భూపాల! నీయనుమతి వడయంగ | వలసి చెప్పెద రాజవంశజునకు","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","027","ఆ.","సమరమరణ మొండె, విమలతపమునకుఁ | జొచ్చి యందు నిలిచి చచ్చు టొండె\nవలయు; నస్మదీయకులముఖ్యు లిట్టుల | నడపి రనుపు నన్ను నడవి కనఘ!","విశేషం: 'అకారణ కరుణాశ్రీవిలసితుండు' అనే విశేషణం సాభిప్రాయం. ధృతరాషష్ట్రుడిపై చూపుతున్న అభిమానాన్నీ దుర్యోధనాదులకు పుణ్యలోక ప్రాప్తి దానాదు లేర్చరచటాన్నీ సూచిస్తూనే తర్వాత తాను కోరబోయే అంశం కూడా తప్పక నెరవేర్చాలి అని ధృతరాష్ర్రుడి అభిప్రాయం. సీ. పఏకార్యమైనను నెవ్వడేనియు/ జేయ/। దొడంగునప్పుడు విను పుడమిటేని","తాత్సర్యం: ధర్మరాజా! ముందుగా రాజునుండి అనుమతి తీసికొనకుండా, ఆ రాజ్యంలో వా డెవడైనా, ఎటువంటి పనైనా ప్రారంభించకూడదు. ఇపుడు ముసలితనం నా శరీరాన్ని మింగేస్తున్నది. ఈ శరీరాన్ని శుద్ధి చేయాలంటే తపస్సు చేయాలి. అందుకు నీవు అనుమతించాలి. క్షత్రియుడైన వాడు యుద్దంలోనైనా మరణించాలి. లేదా తపస్స్ఫుతోనైనా శరీరాన్ని విడిచిపెట్టాలి. (వ్యాసుడూ ఇదే మాట చెప్తాడు 48 పద్యం). ముఖ్యమైనవా శ్ళందరూ -ఈ పద్ధతినే అనుసరించారు. కాబట్టి తపస్సు చేసుకోవడం కోసం నన్ను అడవులకు పంపుము.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","028","క.","రాజు గురుఁ డెల్లవారికి; | రాజోత్తమ! గురునియాజ్ఞ రంజిల్లఁగఁ బే\nరోజం జేసిన కృత్యము | సూ జగములు రెంటియందు శోభన మిచ్చున్‌.","ప్రతిపదార్థం: రాజ+ఉత్తమ!= రాజులలో క్రేష్టుడా!? (ధర్మరాజా); ఎల్లవారికిన్‌= రాజ్యంలోని పిన్నలు పెద్దలు అందరికీ; రాజు= పాలకుడు; గురుడు= గురువు; గురుని+ఆజ్ఞ= గురువుయొక్క శాసనం; రంజిల్లంగన్‌= ఒప్పుతూ ఉండగా; పేరు+ఓబజన్‌= మిక్కిలిగా అదే క్రమంలో; చేసిన కృత్యము+చూ= చేసినటువంటి పనే సుమా; జగములు= లోకాలు; రెంటియందున్‌= రెండింటిలోనూ; (ఇహపరాలలో) శోభనము= ప్రకాశం, కీర్తిని; ఇచ్చున్‌= కలుగజేస్తుంది.","తాత్పర్యం: రాజా! రాజ్యంలో వా రందరికీ రాజే పూజ్యుడు. అటువంటి రాజు అనే గురువు యొక్క ఆజ్ఞతో చేసినపని మాత్రమే ఇహపరసుఖా లందిస్తుంది.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","029","తే.","ఏను గాంధారియును దపోమాననీయ | మునుల చేరువ వల్కలములు ధరించి\nకందమూల ఫలముల నాఁకలి హరించి | నిన్ను దీవించుచుండెద మన్న నతఁడు.","ప్రతిపదార్థం: ఏనున్‌= నేనూ (ధృతరాష్ట్రుడు); గాంధారియును= గాంధారీ; తపస్‌=ా తపస్సుచేత; మాననీయ= గౌరవించదగిన; మునుల= మునుల యొక్క; చేరువన్‌= సమీపంలో; వల్కలములు= నారవస్రాలు; ధరించి= కట్టుకొని; కంద-మూల-ఫలములన్‌= దుంపలు, వేళ్ళూ, పండ్లతో; ఆకలిన్‌= ఆకలిని; హరించి= పోగొట్టి; నిన్నున్‌= నిన్ను (ధర్మరాజును); దీవించుచున్‌+ఉండెదము= మేలు కలగాలని ఆశీర్వదిస్తూ ఉంటాము; అన్నన్‌= అని ధృతరాష్ట్రుడు అనగానే; అతడు= ఆ ధర్మరాజు- ఇట్టా అంటున్నాడు; (తరువాతి పద్యంతో అన్వయం.)","తాత్పర్యం: నేనూ గాంధారీ నారబట్టలు కట్టుకొని అడవులకు పోయి, అక్కడ మహర్షులను సేవిస్తూ, దుంపలూ, వేళ్ళూ, పండ్లూ తింటూ ఆకలి దీర్చుకొంటూ (సుఖంగా ఉండాలని) నిన్ను ఆశీర్వదిస్తూ ఉంటాము” అని ధృతరాష్ర్ట్రుడనగా అతడితో ధర్మరాజు ఇట్లా అంటున్నాడు.","విశేషం: “నిన్ను దీవిస్తూ వుంటాం” అనటంలో నగరంలో లేకపోయినా ఎక్కడ ఉన్నా, ఎలా (మునివృత్తితో) ఉన్నా (ధర్మరాజు) శ్రేయస్సు కోరుతూ ఉంటాము కాబట్టి మేం అడవులకు పోవటానికి అనుమతించవచ్చని అభిప్రాయం."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","030","క.","ధరణీరాజ్యము నాకును | నరవర! సౌఖ్యంబుఁ జేయునా! నీ విమ్మై\nదురపిల్లి దుష్కరం బగు | నరణ్యవాసమున కేఁగినట్టిది యైనన్‌.","ప్రతిపదార్థం: నరవర= రాజా; నీవు= నీవు (ధృతరాష్ట్రుడు); ఈ+మైన్‌= ఈ విధంగా; దురపిల్లి= దుఃఖించి; దుష్కరంబు+అగు= ఆచరణానికి సాధ్యం కాని; అరణ్యవాసమునకున్‌= అడవులలో నివసించటానికి; ఏగిన+అట్టిది+అ= వెళ్ళినట్లు; ఐనన్‌= అయితే; ధరణీ రాజ్యము= (నీవు లేని) ఈ భూమి పాలనం; నాకున్‌= నాకు మాత్రం; సౌఖ్యంబున్‌= సుఖాన్ని; చేయునా!= కలిగిస్తుందా?","తాత్పర్యం: మహాత్మా! నీవు ఈ విధంగా బాధపడి కఠోరమైన అరణ్యాలలో ఉండటానికి వెళ్లితే ఈ రాజ్యం నాకు మాత్రం సుఖ మిస్తుందా?","విశేషం: నీవు అడవులకు వెళ్ళితే అనటంలో నీవు లేకుంటే ఈ ప్రభుత్వం గూడా నా కక్కరలేదు. ఈ రాజ్యం కంటె నీవే ఎక్కువ అని ధర్మరాజు భావం. రాజ్యము సౌఖ్యము చేయునే - ధర్మరాజే రాజయినా పెద్దవాడుగా ధృతరాష్ట్రుడు నడిపించిన ప్రకారం పోవటంలో పాలనం బరువు ధర్మజాడికి తక్కువ. అవుడు పరిపాలనం సుఖం పెద్ద దిక్కుగా (ధృతరాష్ట్రుడు) లేకపోతే తానై అన్నిటికీ బాధ్యత తీసికొనవలసివస్తే అపుడు ప్రభుత్వంవలన సుఖం ఉండదు.ధృతరాష్ట్రుడు ధర్మరాజుతో మాటాడుతూ మొదటగా అన్నది నీ వరయంగ సుఖావాప్తి కొణ౦త లేకుండితి - భూపవర్య! (25వద్యం). దానికి సమాధానంగా ధర్మరాజు ధరణీరాజ్యంబు నాకును సౌఖ్యంబు6 జేయునా అన్నాడు. రాజ్యం సుఖం కాదు గాబట్టి దాని కొరకు దుర్యోధనాదులను చంపా వనరాదని తాత్పర్యం. 'దురపిల్లి'- ఆశ్రమవాస ధర్మనిర్వహణకుగాను అరణ్యవాసం పోతే అంటే ఇట్టా పాండవులు రాజ్యం వలన సుఖపడుతున్నారని భావించే వీలుంది. ఏడుస్తూ ధృతరాష్ట్రుడు పోతే నాకు సుఖం లేదు. మనస్‌స్పూర్తిగా నిజంగా ఆశ్రమవాసం ధృతరాష్ట్రుడు కోరటం లేదని ఆంతర్యం ధర్మరాజుకు అర్థం అయింది. ధర్మరాజాదులు సుఖపడుతున్నారనీ, బాధపడుతూ పాండవుల సుఖం చూస్తూ వాళ్ళ దగ్గర ఉండలేకపోవటంవలననే ధృతరాష్ట్రుడు అడవులకు వెళ్ళిపోదామనుకొంటున్నాడన్నమాట. ఇమ్మై- అనేమాట ధృతరాష్ట్రుడు బాధపడుతున్న కారణాలనేకంగా నిర్దేశిస్తూ - అది ఉచితం కాదని ధ్వనింపజేస్తుంది. సౌఖ్యంబు చేయునా, ఇమ్మై దురపిల్లి- అంటే - ధరణీ రాజ్యం వలన నేను సుఖపడుతున్నానని బాధపడి - ఆకారణంగా - మా సుఖం చూడలేని కారణంగా అడవులకు పోతానంటున్నావు. 'దుష్కరి మైనా అరణ్యవాసం కోరుకొనటం వలన పాండవుల రాజ్యనుఖానికి ధృతరాష్ట్రుడు ఎంతో మిక్కుటంగా విచారిస్తున్నాడని ధర్మరాజు భావంగా గోచరిస్తుంది. ఇటువంటి తక్కువస్థాయి ఆలోచనలు గలిగినవాడుగా గుర్తిస్తూ నరవర అని సంబోధించడంలో విపరీతార్థవి వక్ష ఉంది."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","031","తే.","గూఢబుద్ధి వై నమ్మించి కురువరేణ్య ! | యే నెఱుంగక యుండంగ నిట్లు శోక\nవనధిఁ దేలుచు నుండి తివ్వనట గంటి | నింక రాజ్యంబు నా కెట్టు లించుఁ జెపుమ.","ప్రతిపదార్థం: కురువరేణ్య!= కురువంశంలో (శ్రేష్టుడా!! గూఢ బుద్దినిశఐ= అనలైన ఆలోచనలను రహస్యంగా దాచుకొని; నమ్మించి= బాధలు మరచినట్టుగా, నేను (ధర్మరాజు) నమ్మేటట్టుగా నడుచుకొని; ఏను= నేను, (ధర్మరాజు); ఎయుంగక-+ ఉండంగన్‌= తెలిసికొనలేకపోగా; ఇట్టు= ఈ విధంగా; శోకవనధిన్‌= దుఃఖం అనే సముద్రంలో; తేలుచున్‌+ఉండితితి)= తేలిపోతూ ఉన్నావు: ఈ+వనట= (అందువలన), ఈ విధమైన బాధ; కంటిన్‌= నేనూ పొందాను; ఇంకన్‌= ఈ బాధ వలన; నాకున్‌= నాకు; రాజ్యంబు= ప్రభుత్వం; ఎట్టులు= ఏ విధంగా; ఇంచున్‌?= ఇష్ట మవుతుంది?; చెపుమ= నీ వే చెప్పుము.","తాత్పర్యం: కురువంశక్రేష్టా! బుద్దిని దాచుకొని నమ్మించి నాకు తెలియకుండా ఈ విధంగా శోకసముద్రంలో తేలుతూ ఉండినావు. ఈ (దాచుకొన్న) నీ బాధను ఇప్పుడు చూచినాను. ఇంక రాజ్యము నాకెట్టా ఇష్టమవుతోందో చెప్పుము.","విశేషం: 25గితం, 26 పద్యాలలో ధృతరాష్ట్రుడి మాటలలోని ఆంతర్యానికి సమాధానం ధర్మరాజు ఈ పద్యం."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","032","ఉ.","తల్లియుఁ దండ్రియున్‌ గురుఁడు దైవము నా కరయంగ నీవ భూ\nవల్లభ! నీవు కానన నివాసము గోరి చనంగ నెట్టు లే\nనుల్లము వట్టి హస్తిపురి నుండఁగ నేర్తు? యుయుత్సుఁ బెంపు శో\nభిల్లఁగ రాజుఁ జేయు; నినుఁ బ్రీతి యెలర్పఁగఁ గొల్చి వచ్చెదన్‌.","ప్రతిపదార్థం: భూవల్లభ!= ఓ రాజా! (ధృతరాష్ట్ర); అరయంగన్‌= పరిశీలించి చూస్తే; నాకున్‌= నాకు; తల్లియున్‌= తల్లీ; తండ్రియున్‌= తండ్రీ; గురుడున్‌= గురువూ; దైవమున్‌= దైవమూ; నీవు+అ= నీవే; నీవు= అటువంటి నీవు; కానన నివాసము= అడవులలో నివసించటాన్ని; కోరి= న్వయంగా అభిలషించి; చనంగన్‌= వెళ్ళిపోతే; ఏన్‌=ా నేను; ఉల్లము= మనసును; పట్టి= నిగ్రహించుకొని; హస్తిపురిన్‌= హస్తినగరంలో; ఉండగన్‌= ఉండటానికి; ఎటులు= ఏ విధంగా; నేర్తున్‌= ఓర్చుకొనగలను; పెంపు= గౌరవం; శోభిల్లంగన్‌= అతిశయించేవిధంగా; యుయుత్సున్‌= నీ కొడుకైన యుయుత్వుణ్ణి; రాజున్‌= ఈ రాజ్యానికి పాలకుడిగా;చేయుము= చేయవలసింది; ప్రీతి= ఇష్టం; ఎలర్పంగన్‌= అధికం కాగా; నినున్‌=ా నిన్ను; కొల్చి= సేవిస్తూ; వచ్చెదన్‌= నీతో అరణ్యవాసానికి నేనూ వస్తాను.","తాత్పర్యం: ఓ రాజా! పరిశీలించి చూస్తే నాకు తల్లీ, తండ్రీ, గురువూ, దైవం అన్నీ నీవే. నా సర్వస్వం అయిన నీవు బుద్ధిపూర్వకంగా అరణ్యవాసానికి వెళ్ళితే మనసు చిక్కబట్టుకుని నే నీ రాజధానిలో ఎట్లా ఉండగలను. నీ కొడుకైన యుయుత్వుడిని ఈ రాజ్యానికి రాజును చేయుము. నేను సంతోషంగా నిన్ను సేవిస్తూ నీతోపాటు అరణ్యాలకు వస్తాను.","విశేషం: రాజైన ధర్మరాజు ధృతరాష్ట్రుడిని అడవులకు అనుసరించగోరుతున్నాడు. కాబట్టి తాను హస్తిపురిలో లేకుంటే రాజ్యం అరాజకం అవుతుంది. అట్లా కాకూడదు కాబట్టి ముందుగా వేరే రాజుని ఏర్పరిచే విషయం ప్రస్తావించటం రాజనీతిజ్ఞత. అయితే యుయుత్వుడిని రాజు చేయు మనడం విశేషం. తన కొడుకులను చంపి ధర్మరాజు రాజయ్యాడని ధృతరాష్ట్రుడు బాధపడుతున్నట్టుగా అతని మాటలలో గూఢంగా ఉన్న అంశం ధర్మరాజు గ్రహించాడు. కాబట్టే ధృతరాష్ట్రుడికి కొడుకైన యుయుత్వుడిని రాజు చేయు మంటున్నాడు. తన సొంత కొడుకే రాజు అయితే ధృతరాష్ట్రుడికి కొంత బాధ తగ్గుతుంది. పాండవులు పరాయి వాళ్ళనుకొంటున్నాడు ధృతరాషష్ర్రుడు. పెంపు శోభిల్లగ - యుయుత్వుడిని రాజు చేస్తే యుయుత్వుడికే కాక ధృతరాష్ట్రుడు తనకు (తన కొడుకు రాజైనందు వలన) పెంపు శోభిల్చుతుందని భావిస్తాడు. ధర్మరాజు రాజవటం వలన తన పెంపు పోయినట్లు భావిస్తున్నాడన్నమాట. వైశ్య స్త్రీ వలన వుట్టినా రాజును చేస్తే యుయుత్వుడికి (లేని) పెంపు శోభిల్లుతుంది. వేం రాజ్యం నంపాదించుకొన్నాం. నీవు ఇవ్వలేదు కాబట్టి యుయుత్సుడు అట్టా నంపాదించలేడు. నీవే అతడిని రాజును చేయాలి అని ధృతరాష్ట్రుడి కొడుకు అసామర్థ్హ్యం సూచన. రాజ్యార్హత లేనివాడు కావటం వలననూ, ఇలాగే ప్రీతి యెలర్ప/గ - నీకు (ధృతరాష్ట్రుడికి) సంతోషం కలిగేటట్టుగా నీకు సేవచేస్తూ అడవులకు వస్తానని ధర్మరాజు భావం. యుయుత్వుడిని రాజును చేసిన తర్వాత కూడా అరణ్యవాసం చేయాలని నీవనుకుంటే అప్పటికీ పాండవులు రాజధానిలో సుఖపడతా రేమో ననే బాధ ఉండి 'అహం వనం గమిష్యామి, భవా ్రాజ్యం ప్రశాస్త్రిదమ్‌” నేనే అడవులకు పోతే నీవు రాజ్యం చేసుకోమనడం ధృతరాష్ట్రుడి దోషం మరీ ఎక్కువ చేస్తుంది. అందుకే తిక్కన ధృతరాష్ర్ట్రుడితో అరణ్యానికి వస్తా ననిపించాడు. ఇక్కడ కూడా అప్పుడు నేనూ అడవులకు వస్తా నంటాడు ధర్మరాజు."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","033","క.","అతఁ డౌరసుండు నీ కీ | క్షితి కొడయుఁడు దుర్యశంబుచేఁ గుందుట భూ\nపతివర! కని కని మీరి | ట్లతి మాత్రము చేయఁదగునె యక్కట నాకున్‌?","ప్రతిపదార్థం: భూపతివర!= రాజులలో శ్రేష్టుడ వైన ధృతరాష్ట్ర! అతడడు= ఆ యుయుత్సుడు; నీకున్‌= నీకు; బౌరసుండు= ధర్మపత్నియందు పుట్టినవాడు; ఈక్షితికిన్‌= ఈ కురురాజ్యానికి; ఒడయుడు= యజమానుడు; దుర్యశంబుచేన్‌= (కౌరవులను) చంపటం అనే అపకీర్తి చేత; కుందుట= నేను బాధపడుతూ ఉండడం; కని కనికా బాగా చూచి కూడా; అక్కట= అయ్యో; నాకున్‌= నాకు; మిరు= మీరు (గాంధారీ ధృతరాష్రులు); ఇట్టు= ఈ విధంగా; అతిమాత్రము= (ఆ దుఃఖాన్ని) ఇంకా అధికం; చేయన్‌+తగునె?= చేయటం ఒప్పుతుందా?","తాత్పర్యం: రాజులలో శ్రేష్టుడా! ఆ యుయుత్సుడు నీకు ధర్మపత్ని యందు పుట్టినవాడే కాబట్టి ఈ కౌరవరాజ్యానికి అతడే రాజు. ఇప్పటికీ బంధువినాశాదులవలన అపకీర్తితో, విచారిస్తుండటం కళ్లారా చూచి కూడా ఇంకా నాదుఃఖాన్ని అధికం చేయటం సమంజసమేనా?",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","","సీ.","నీవు రాజవు గాక నీ కేను రాజనే? | గురుని మహారాజుఁ గురువరేణ్యు\nనిటు చేయు మని పంప నే నొడయండనే? | దుర్యోధనాదుల దుష్కృతములు\nనా మదిలో నిల్ప, నేమును వారును | విధిమోహమున నైన విరస భావ\nమావహిల్లినఁ బుట్టె నంతలు పనులు; గాం | ధారియు గొంతియు గారవమున","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","034","ఆ.","నాకు నొక్కరూప; మీకుఁ గాననవాస | మెల్ల భంగిఁ గలుగు నేని యేనుఁ\nదగిలి తోన వత్తుఁ దగుమాటగా నాటఁ గాదు నాదుహృదయగతియు నిట్ల.","ప్రతిపదార్థం: రాజవు= -ఈ రాజ్యానికీ, నాకూ రాజువి; నీవు= నీవే; కాక= అంతే కాని; నీకున్‌= నీకు; ఏను= నేను; రాజనే?= రాజునా?; గురునిన్‌=ా గురువు; మహారాజున్‌= చక్రవర్తిని; కురువరేణ్యున్‌= కురువంశంలో శ్రేష్టుడూ అయిన నిన్ను; ఇటు= ఈ విధంగా; చేయుము= చేయవలసింది; అనికా అనే తీరుగా; పంపన్‌= ఆజ్ఞ చేయటానికి; నేను= నేను; ఒడయండనే?= ఏలికనా?; దుర్యోధనాదుల= దుర్యోధనుడు మొదలైన వారి (నీ కొడుకుల); దుష్ఫృతములు= చెడు పనులు; నా మదిలోన్‌= నా మనస్సులో, నిల్చన్‌= ఉంచుకోలేదు (మరిచాను); ఏమును= మేమూ (పాండవులు); వారును= దుర్యోధనాదులూ; విధిమోహమునన్‌= బ్రహ్మదేవుడు కల్పించిన అజ్ఞానం వలన; ఐన= పుట్టిన; విరసభావము= ద్వేషం; ఆవహిల్లినన్‌= ఆవరించటంవలన; అంతలు పనులు= అటువంటి దుష్క్ఫృతములు; పుట్టెన్‌= నంభవించాయి; నాకున్‌=ా నాకు; గారవమునన్‌= ఆదరం విషయంలో; గాంధారియున్‌= గాంధారీ; గొంతియున్‌= కుంతీదేవీ; ఒక్కరూపు+అ= ఒకటే; మికున్‌= అటువంటి మి యిద్దరికి; ఎల్ల భంగిన్‌= అన్ని విధాలుగానూ; కానన వాసము= అడవులలో ఉండడం; కలుగున్‌+ఏని= సంభవించే పక్షంలో; ఏనున్‌= నేను కూడా; తగిలి= వెన్నంటి; తోన్‌+అ= మీతో కలిసే; వత్తున్‌= అడవులకు వస్తాను; తగు మాటగాన్‌= మి మాటలకుబదులుగా, ఆటన్‌+కాదు= పలుకుటకాదు; నాదు హృదయగతియున్‌=ా నా మనసులో ఉన్నది కూడా; ఇట్లు+అ= ఇంతే.","తాత్పర్యం: నువ్వే (నాకూ, అందరికీ) రాజువి కాని నీకు నేను రాజును కాదు. గురువువీ, మహారాజువీ, వంశశ్రేష్టుడినీ అయిన నిన్ను ఇట్టా చేయు మని ఆజ్ఞాపించటానికి నేను అధికారిని కాదు. నీ కొడుకులు చేసిన కీడు పనులు నేను మనసులో పెట్టుకొనలేదు (మరిచేపోయాను). విధి వలన అజ్ఞానంతో ద్వేషం ఏర్పడి అటువంటి కీడు పనులు జరిగాయి. నాకు గాంధారీ, కుంతీ ఇద్రరూ ఒకటే. సమానంగా గౌరవిస్తాను. అటువంటి గాంధారీ, నీవూ ఏ విధంగా నైనా అడవికి పోవడం తప్పకపోతే వెన్నంటి నేనూ మితోపాటే వస్తాను. ఇది నిజం. సమయానికి తగినట్టు మాటాడటం కాదు. నా మనసులో ఉన్న మాట అదే.","విశేషం: ధృతరాష్ట్రుడు తనతో చెప్పిన మాట లన్నింటికీ సంగ్రహంగా ఇక్కడ ధర్మరాజు సమాధానం చెప్పాడు."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","035","క.","పలికెద నే సత్యము నా | కిల ప్రీతిం జేయ దధిప! యీ వి ట్లయినం\nగులము కలఁక దైవకృతం | బలఘుమతీ! విడువు శోక మరయుము నన్నున్‌.","ప్రతిపదార్థం: అధిప!= ఓ రాజా!; నేన్‌= నేను; సత్యము= యథార్థం; పలికెదన్‌= చెపుతున్నాను; ఈవు= నీవు; ఇట్టు+అయినన్‌= ఇట్టాగు అయితే; నాకున్‌= నాకు; ఇల= రాజ్యం; ప్రీతిన్‌= సంతోషాన్ని; చేయదు= కలిగించదు; అలఘుమతీ!= దొడ్డబుద్ధి కలవాడా; కులము కలక= మన వంశంలో ఏర్పడ్డ కలత; దైవకృతంబు= దేవుడు కల్పించిందే; శోకము= పుత్రవియోగాదులవలన పుట్టిన దుఃఖాన్ని; విడువు= విడిచిపెట్టుము; నన్నున్‌= నన్ను; అరయుము= కాపాడుము.","తాత్పర్యం: రాజా! నిజం చెపుతున్నాను. నీవు ఈ విధంగా శోకిస్తూ అరణ్యాలకు పోతే (నీవు లేని) యీ రాజ్యం వలన నాకు సుఖం లేదు. ఇంక మనకులంలో ఏర్పడ్డ కలతలు దైవం వలన కలిగినవే. దొడ్డబుద్ది గలవాడా!. ఇక దుఃఖాన్ని విడిచిపెట్నుము, నన్ను ఉద్దరించుము.","విశేషం: మొత్తం తన సమాధానం సారాన్ని ఇక్కడ ధర్మరాజు సంగ్రహంగా చెప్పుతున్నాడు. ఇక్కడినుండి ధర్మరాజు మాటలు సూటిగా అంతరార్థం ఇంకొక విధంగా లేకుండా తోస్తుంది. ఇదే సత్య మన్నమాట."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","036","తే.","నీకు శుశ్రూష యొనరించి నృపవరేణ్య! చిత్తతాపంబు మానంగఁ జేసికొందు\nనని తలంచు నన్‌ విడువంగ నగునె? యవన | తుండ నై నిన్ను వేఁడెదఁ దొఱఁగు వగలు.","ప్రతిపదార్థం: నృపవరేణ్య!= రాజులలో (శ్రేష్టుడా!: నీకున్‌= నీకు; శశ్రూష= (చెప్పిన పనులు చేస్తూ) సేవ; ఒనరించి= చేసి; ఆ విధంగా; చిత్త - తాపంబు= మనసులో చింతను; మానంగన్‌=ా అణగి పోయేటట్ల్టుగా; చేసికొందున్‌= చేసుకుంటాను; అనికా అనే విధంగా; తలంచు= ఆలోచించే; నన్‌= నన్ను; విడువంగన్‌= విడిచిపెట్టటం (అరణ్యాలకు వెళ్ళటం); అగునె?= ఉచితమా?; అవనతుండను= వినముడిని; ఐ= అయి (వంగి); నిన్నున్‌= నిన్ను; వేడెదన్‌= ప్రార్థిస్తున్నాను; వగలు= బాధలు; తొఅగుము)= విడిచిపెట్టుము:","తాత్పర్యం: రాజులలో శ్రేష్టుడి వైన ధృతరాష్ర్రుడా! నీకు సేవ చేసికొంటూ నా బాధలు మరచిపోవా లనుకొనే నన్ను విడిచి అరణ్యాలకు వెళ్ళకుము. ప్రాధేయపడుతున్నాను. నీ శోకాన్ని విడిచిపెట్టుము.","విశేషం: ధర్మరాజు ప్రాధేయపడడంలో ధృతరాష్ట్రుడి శోకం ధర్మరాజును చాలా బాధపెట్టినట్లు చెప్పుతుంది. ధృతరాష్రుడిని తృప్తి పరచలేకపోవడంతో 15 సంవత్సరాలుగా తాను పడ్డ శ్రమంతా వృథా అయినపుడు ఈ విధంగా బాధపడటం సహజమే."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","037","క.","అనుచు నతని చరణంబులు | తన ఫాలతలంబు చేర్చె ధర్మతనయుఁడా\nతని గ్రుచ్చి యెత్తి కౌఁగిట | నెనయంగాఁ జేర్చి యాతఁ డిట్లను నధిపా!","ప్రతిపదార్థం: అధిపా!= జనమేజయరాజా!; అనుచున్‌= పైవిధంగా అంటూనే; ధర్మతనయుడు= ధర్మరాజు; తన, ఫాలతలంబు= తన నుదుటి ప్రదేశాన్ని, శిరస్సును; అతని చరణంబులు= ధృతరాష్ట్రుడి పాదాలను; చేర్చెన్‌= చేరేటట్లు చేశాడు; అతడు= ఆ ధృతరాష్ట్రుడు; ఆతనిన్‌= పాదాభివందనం చేస్తున్న ధర్మరాజును; గ్రుచ్చి= గట్టిగా పట్టుకొని; ఎత్తి= సైకి లేపి; కౌగగిటన్‌= తన బాహువుల మధ్య; ఎనయంగాన్‌=ా కుదురుగా; చేర్చి= చేర్చుకొని; ఇట్టు+అనున్‌= ఈ విధంగా అంటున్నాడు.","తాత్పర్యం: జనమేజయమహారాజా! “నీ సేవ చేస్తూ నా విచారం పోగొట్టుకొంటా” నని మొదలుగా ఆ మాటలు అంటూనే ధర్మరాజు ధృతరాష్ట్రుడి పాదాలపై తన శిరస్సు ఉంచి ప్రణామం చేశాడు. ధృతరాష్ట్రుడు ఆ ధర్మరాజును పట్టుకొని లేపి కౌగిలిలో చేర్చుకొని ఇలా అంటున్నాడు.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","038","తే.","నీవు శుశ్రూష చిరకాలనియతిఁ జేసి | తేను వృద్ధుండ నైతి; నా కింకఁ దపము\nవలవదయ్య? రాజును బాలివాఁడ యెవ్వ | రేమి చేసిన ఫలములయెడ నృపాల!’","ప్రతిపదార్థం: నృపాల!= (ధర్మ) రాజా!: నీవు= నీవు; చిరకాల నియతిన్‌= చాలాకాలం నియమంగా; శుశ్రూషా సేవ; చేసితివి= (నాకు) చేశావు; ఏను= నేను; వృద్దుండన్‌= ముసలివాడిని; ఐతిన్‌= అయ్యాను; ఇంకను= ఈ వార్హక్యంలో; నాకున్‌= నాకు; తపము= తపస్సు చేసికొనటం; వలవదు+అయ్య?= వద్దా?; ఎవ్వరు= రాజ్యంలో ప్రజలలో ఎవరైనా; ఏమి= ఏపని; చేసినన్‌= చేసినా; ఫలముల - ఎడన్‌= దానికి కలిగే ఫలితం విషయంలో; రాజును= రాజు కూడా; పాలివాడడు+అ= భాగస్టుడే.","తాత్పర్యం: రాజా! నీవు చాలాకాలంగా నియమంగా నాకు శుశ్రూష చేస్తూనే వున్నావు. ఇపుడు నేను పెద్దవాణ్ణయిపోయాను. ఈ వార్రక్యంలో నైనా తపసు చేసికొనవద్దా? ప్రజలు చేసిన ప్రతిపనికి కలిగే ఫలంలో రాజుకు కూడా భాగం ఉంటుంది.”",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","039","వ.","అని పలికి విదుర కృప సంజయుల నుద్దేశించి తనకు ముఖశోషయుం దనుగ్లానియుం గలిమి నుగ్గడించి, నాలుక తొట్రుపడ వారలతో మీర లనునయవచనంబుల నజాతశత్రుం దెలి వొందం జేయుం’ డని చెప్పి డప్పి యెక్కుడు గదిరిన గాంధారి తనువున మేను సేర్చి మూర్ఛిల్లుటయు నార్తి నొంది యక్కుంతీనంద నాగ్రజుం డిట్లని పలవించె.","ప్రతిపదార్థం: అని= ఈ విధంగా; పలికి= చెప్పి; విదుర - కృప - సంజయులన్‌= విదురుడినీ, కృపాచార్యుడినీ, సంజయుడినీ; ఉద్దేశించి= లక్ష్యం చేసికొని - వాళ్లతో; తనకున్‌= తనకు (ధృతరాష్ర్రుడికి); ముఖశోషయున్‌= నోరు ఎండిపోవటమూ, (నాలుక తడి ఆరటం), తను గ్లానియున్‌= (ఎక్కువ మాటాడటం వలన) శరీరం బలహీనమై పోవటమూ; కలిమి= ఉన్నవిషయాన్ని; ఉగ్గడించి= చెప్పి; నాలుక= నాలుక; తొట్రుపడన్‌= తడబడుతుండగా; వారలతోన్‌= ఆ విదురుడు మొదలైన వారితో-మ్‌రలు= మిరు; అనునయవచనంబులన్‌= ఊరడింపు మాటలతో; అజాతశత్రున్‌= శత్రువులు లేనివాడిని - ధర్మరాజును; తెలివి+ఒందన్‌= తెలివి పొందేవిధంగా; చేయుండు= చేయండి; అని=ా అనే విధంగా; చెప్పి= పలికి; డప్పి= దాహం; ఎక్కుడు= అధికంగా; కదిరినన్‌= కలుగగా; గాంధారి తనువునన్‌= గాంధారి శరీరంపై; మేను= తన శరీరాన్ని, చేర్చి= ఉంచి; మూర్శిల్చుటయున్‌= సొమ్మసిల్లిపోగా; ఆ+కుంతీ నందన+అగ్రజుండు= కుంతి కొడుకులలో పెద్ద అయిన ధర్మరాజు; ఆర్తిన్‌= దుఃఖం; ఒంది= పొంది; ఇట్టు+అని= -ఈ విధంగా; పలవించెన్‌= దుఃఖించాడు.","తాత్పర్యం: ధర శ్రరాజుతో పైవిధంగా పలికిన ధృతరాష్ట్రుడు విదుర, కృప, సంజయులతో నాకు నాలుక తడి ఆరిపోతున్డది. శ్రమవలన శరీరం దుర్బల మవుతున్నది' అని, నాలుక తడబడుతుండగా “ఇక మీరే ధర్మరాజుకు ఊరటపు మాటలు చెప్పి విచారం పొగొట్టండి\" అని చెప్పి దాహం ఎక్కువ కావటంతో గాంధారి శరీరాన్ని ఆసరా చేసికొని స్పృహ తప్పిపోయాడు. ధర్మరాజు అది చూచి దుఃఖంతో ఇట్లా అన్నాడు.","విశేషం: విదురాదులు జ్ఞానులు, మాట నేర్చరులూ, పాండవులపై అభిమానం కలవారూ కాబట్టి వాళ్ళు జాగ్రత్తగా ధర్మరాజుకు అమోదయోగ్యంగా మాటాడగలరు. తనకంటె వాళ్ళ మాటలు ధర్మరాజు ఆప్తవాక్యంగా స్వీకరించనూ గలడు. కాబట్టి ధర్మరాజును సాంత్వనపరిచే బాధ్యత వారి కప్పగించాడు. ఉభయులకూ కావలసినవారు కాబట్టి తన అభిప్రాయాన్ని ధర్మరాజుకు నచ్చేటట్టుగా చెప్పుతారని. ధర్మరాజును అజాత శత్రువుగా పేర్కొనడంలో ధర్మరాజుకు తమపై శత్రుభావం ఉండదని మెచ్చుకోలూ, స్నేహంగా తమ అరణ్యవాసానికి అంగీకరించాలని సూచన. తనకు ముఖశోష తనుగ్గానీ ఉన్నవన్నాడు. దానివలన నాలుక తొట్రుపాటూ, చివరికి మూర్చా కలిగాయి. కార్యకారణభావం కుదిరింది. మూర్ఫాస్థితి రావడం ముందుగా గుర్తించటం వలన గాంధారిని ఆశ్రయించాడు."],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","040","క.","కరి దశసహస్ర బలవి | స్ఫురితుఁ డగు విచిత్రవీర్యపుత్త్రుఁ డొక తలో\nదరి నూఁత గొనియె; విధి యె | వ్వరి హీనులఁ జేయఁ డకట వక్రుం డైనన్‌!","ప్రతిపదార్థం: కరి= ఏనుగులు; దశసహస్ర= పదివేలయొక్క; బల= శక్తిచే; విస్ఫురితుండు= వెలిగేవాడు; అగు= అయిన; విచిత్ర వీర్య పుత్రుడు= విచిత్రవీర్యుడి కొడుకు ధృతరాష్ట్రుడు; ఒక తలోదరిన్‌= ఒకానొకస్ర్రీని; ఊత కొనియెన్‌= ఆధారం చేసికొని ఉన్నాడు; అకట!= అయ్యో!; విధి= బ్రహ్మ; వక్రుండు= వంకర; ఐనన్‌= అయితే; ఎవ్వరిన్‌= ఎంతటివారిని; హీనులన్‌= అల్పులుగా; చేయడు?","తాత్పర్యం: పదివేల యేనుగుల బలం కలిగిన ధృతరాష్ట్రుడు ఈనాడు ఒక అబలను ఆధారం చేసికొనవలసి వచ్చింది. బ్రహ్మ సరిగా చూడకపోతే ఎంతటి గొప్ప వాళ్ళనైనా మిక్కిలి హీనస్థితికి తెస్తాడు.","విశేషం: అలం; అర్థాంతరవ్యాసం. (సామాన్యంచేత విశేషం సమర్థింపబడుతుంది.)"],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","041","చ.","‘అనిలజు మేని చంద మగు నాయసరూపము చూర్ణితంబు చే\nసిన బలమాననీయుఁ డొక చేడియ నక్కట; యాశ్రయించె; నే\nమనఁగల దవ్విధాతృ’ నని యాతని కీడును మానసంబునం\nజొనుపమి లావు పేరుకొని శోకము ధర్మజుఁ డొందె భూవరా!","ప్రతిపదార్థం: అనిలజు= వాయుపుత్రుడి; మేని చందము= శరీరము వంటిది; అగు= అయిన; ఆయనరూపము= ఉక్కు విగ్రహాన్ని; చూర్హితంబు= పొడి అయ్యేటట్టుగా; చేసిన= చేసినట్టిః బల-మాననీయుడు= శక్తిచే ప్రశంసించ దగిన ధృతరాష్ట్రుడు; అక్కట= అయ్యో; ఒక చేడియన్‌= ఒకానొక ఆడదాన్ని; ఆశ్రయించెన్‌= అండగా చేసుకున్నాడు; ఆ+విధాతృన్‌= (అంతటి బలవంతుడి కీ గతి కల్గించిన) ఆ బ్రహ్మనుగూర్చి; ఏమి+అనన్‌+కలదు?= ఏమనవచ్చు?; అని= అని పలికి; భూవరా! ఓ జనమేజయ మహారాజా!; అతని కీడును= ధృతరాష్ట్రుడు చేసిన అపకారాన్ని; తన మానసంబునన్‌= తన మనస్సులో; చొనుపమి= పెట్టుకోకపోవడంచేత; ధర్మజుడు= ధర్మరాజు; లావు= ధృతరాష్ట్రుడి బలాన్ని; పేరుకొనికా ప్రశంసిస్తూ; శోకము= దుఃఖాన్ని; ఒందెన్‌= పొందాడు.","తాత్పర్యం: భీముడి రూపంలో ఉన్న ఉక్కు విగ్రహాన్ని పొడిగా చేసిన బలవంతుడైన ధృతరాష్ట్రుడు ఇపుడు ఒక ఆడదానిని ఆధారం చేసికొనవలసివచ్చింది. అంతటి బలవంతుడి కింతటి హీనస్థితిని తెచ్చిన విధాతను ఏ మనగలం?” అంటూ జనమేజయా ! ధృతరాష్ట్రుడు చేసిన అపకారాన్ని మనసులో సపెట్టుకొనకపోవటం వలన అతడి బలాన్ని తలచుకొని ధర్మరాజు అతడి ప్రస్తుతస్థితికి దుఃఖపడ్డాడు.",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","","సీ.","అప్పుడు గాంధారి యల్లన ధర్మజు | తోడ ‘మీతండ్రి యతుల తపంబు\nతోడి సంతతచింతఁ గూడు దొఱంగి తా | నుండుటఁ గూర్చుండ నోప కునికి\nనిట్లయ్యె’ ననవుడు నెవ్వని కతమున | నిమ్మహాత్మున కిట్టి యెడరు పుట్టె\nనట్టి నా మనువు నే మనఁ గల?’ దంచు నా| తఁడు శీతజలము హస్తమునఁ బుచ్చి","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","042","ఆ.","కొని యతని మోమునందు నక్కున విదిర్చు | సమయమున విదురుండును సంజయుండు\nనఖిలభరతభార్యలు నేడ్చి రవ్విభుండు | నివిరెఁ జలికేల నా నృపు నవయవములు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","043","క.","నివురంగఁ దెలిసి యతనిం | గవుఁగిటిలోఁ జేర్చి మస్తకము మూర్కొను కౌ\nరవవృద్ధు నతఁడు నా శ్లే | ష విశేషంబున నొనర్చె సంప్రీతునిఁగన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునితోఁ దన మనోరథంబుఁ దెలుపుట (సం. 15-5-1)","044","వ.","అట్లు తెలివొంది ధృతరాష్ట్రుండు ధర్మరాజుతో ‘నా కెట్లునుం దపంబునకయి కాననంబునకుం బోవ వలయు’ ననిన నజ్జనపతి, ‘నీ వారగింపు; మప్పని మఱి చెప్పెద’ నని త్రోపు మాటగాఁ బలికిన నయ్యాంబికేయుండు ‘పెక్కుమాట లాడ శక్తి లేదు; న న్నింక నలజడిఁ బెట్టకుము; తపశ్చరణంబునకు నీ యాజ్ఞ వడసి కాని కుడువ’ ననియె; నయ్యవసరంబున సాత్యవతేయుండు కృపావిధేయుండై యచటికి వచ్చి సకలజనంబుల వినతులు గైకొని దీవన లిచ్చి యా ధర్మతనయు నాననం బాలోకించి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","","సీ.","‘ఆంబికేయుఁడు చెప్పినట్టుల చేయుము | వృద్ధుఁడు నాత్మజ విరహితుండు\nనైన యీతఁడు తప మాచరింపఁగఁ గోర | కున్నె? గాంధారి శోకోపశమము\nతాలిమి నొదవి యిందాఁకఁ బ్రవర్తించె; | నింక నియ్యమకును నిదియ తలఁపుఁ\nగావున నీకు నీ కార్యంబు చెప్పంగ | వచ్చితి; వీరిఁ బోనిచ్చు టొప్పు","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","045","తే.","ననఘ! పూర్వ రాజన్యులు చనినయట్టి | సౌమ్యపథమున నీ రాజు చనుట మేలు\nగాన నీతని కానన గమనమునకు | ని మ్మనుజ్ఞ విచారంబు లెల్లఁ దక్కి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","046","క.","నీ వినయము భక్తియు, సం | భావనమును వీరి వగలఁ బాపఁగ శుశ్రూ\nషావశవర్తిత నడచితి | భూవర! చిరకాల మింకఁ బోనిమ్ము తగన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","047","చ.","అన విని యాకురుప్రవరుఁ డమ్మునివల్లభుమోముఁ జూచి యి\nట్లను - మహితాత్మ! మాకు గురుఁ డన్నను ధర్మవిధోపదేష్ట య\nన్నను బరదైవ మన్నను మనః ప్రియకార్యకలాపకర్త య\nన్నను విను నీవ; నీదువచనంబున కడ్డము పల్కువాఁడనే?’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","048","ఆ.","అనిన నమ్మహాత్ముఁ డను ‘రాజులకు రణ | మరణ మొండె దృఢ సమాధిఁ దనువు\nవిడుచు టొండెఁ గాక వృద్ధులై రోగ త | ల్పమునఁ జావు మేలె భరతముఖ్య!’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","049","వ.","అనిన విని ధర్మతనయుం డొండు పలుక వెఱచి యిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","050","క.","అనఘా! యిక్కురుముఖ్యున | కనుజ్ఞ యే నిచ్చితిని మహత్తర మగు మీ\nయనుమతియుఁ బడసెఁ జనుఁ గా | క నిజేచ్ఛను నాకు విఘ్నకరణముఁ దగునే?’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","","సీ.","అనుటయుఁ బ్రియ మంది యమ్మహాముని యమ్మ | హీశ్వరుతోఁ ‘బాండుఁ డీ నృపాలు\nగద్దియ నిడికొని క్రతువులు సేయించి | యవిరళభోగానుభవము నడపి\nయీతని వారలఁ బ్రీతి నీక్షించి తా | శిష్యుండ పోలె సంసేవనంబు\nభక్తిమై నొనరించెఁ; బదపడి నీవును | దిగ్విజయాదులఁ దేజమితని","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","051","తే.","నొందునట్లుగఁ జేసితి వొకటఁ; బిదప | దాన పదుమూఁడు వర్షముల్‌ ధరణి యేలె;\nనీవు శుశ్రూష యిత్తఱి నియతి నడపి | తితని మది లేదు కలఁక యొక్కింత యేని.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","052","క.","కేవలతపః క్రియా సం సేవన తాత్పర్య మిపుడు చిత్తంబునయం\nదావేశించినయది యీ | భూవరునకు నితని ననిచిపుచ్చు మడవికిన్‌ |’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","053","ఆ.","అనిన ధర్మ తనయుఁ ‘డట్టుల కా కని’ | పలికెఁ దత్‌క్షణంబ పరమయోగి\nవంద్యుఁ డయిన సత్యవతి కొడు కాత్మత | పోవనమున కరిగె భూపవర్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","","సీ.","తదనంతరమ ధర్మతనయుండు ధృతరాష్ట్రు | తోడ నీ కెట్టుల సూడఁ బోలె\nవిదురుండుఁ గృపుఁడు నెయ్యది కృత మని విని | శ్చయ మొనరించిరి సంజయుని యు\nయుత్సుని మనముల నొలసిన కర్తవ్య | మెద్ది దానిన చేయు టెంత యేని\nనాకుఁ బ్రియంబు భూనాథ యానతుఁడ నై | వేఁడెద నొకటి నీ విశదబుద్ధి","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","054","ఆ.","నేమి సేయఁదలఁచి తేని నీ వక్కట | యారగించి చేయు మయ్య!’ యనుడు\nనరిగె నా నృపాలుఁ డభ్యంతరావాస | మునకుఁ దోన సుబలతనయ సనఁగ","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రు వనవాసంబున కనుజ్ఞ యిచ్చుట (సం. 15-8-1)","055","వ.","ఇట్లు కురువృద్ధుండు వృద్ధసామజంబు చందంబునం జనునప్పుడు విదురుండును, యుయుత్సుండును గృపాచార్యుండును, సంజయుండును వెనుకన చని; రజ్జనపతి దివసకృత్యంబు లాచరించి భూమిసురులం బూజించి యాహారతంత్రంబు నిర్వర్తించె; గాంధారియుఁ గుంతీ ప్రముఖ భరత భార్య లనునయింప భోజనవిధి యొనర్చెం; దదనంతరంబ విదురాదులుం బాండవేయులును వనితా జనంబులుం గృతాహారులయి యా వైచిత్ర్యవీర్యుం బరివేష్టించియుండఁ, బాండవాగ్రజు నిప్పాండునృపాగ్రజుం డేకాంతస్థానంబునకుం దోడ్కొనిపోయి యతని తోడ ‘సప్తాంగం బయిన రాజ్యంబు పూజ్యం బగుధర్మంబుతో నెనయ నడపుట దుష్కరంబు గావున నా యెఱిఁగినంత బోధించెద నాకర్ణింపు’ మని పలికి యిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","","సీ.","‘నీవు నిచ్చలును విద్యావృద్ధజనములఁ | దగ నుపాసింపు, మర్థముల వారిఁ\nబ్రీతులఁ జేయుము; నీతులు వా రుప | దేశింప వాని నూఁదినమనంబు\nగలిగి నిర్వర్తింపు; కార్యంబు నింద్రియం | బుల రాజ్యతంత్రంబుఁ బోలె నరసి\nరక్షింపు; మప్పిండు రక్షితం బైన శు | భంబులం గావించు; భావశుద్ధి","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","056","ఆ.","ధామములును బితృపితామహక్రమసమా | గతులు విశదమతులుఁ గాఁగవలయు\nసచివు; లతివిదగ్ధ చారులఁ బనుపుము | పరుల యాప్తజనుల భంగు లరయ.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","057","క.","పురరక్షణము దృఢంబుగ | నరవర! చేయంగవలయు నమ్మఁగలుగు స\nత్పురుషుల నిడఁ దగుఁ గుడుపు ని | దుర మొదలగులోని పనుల తొడరువు లరయన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","","సీ.","ఆప్త వృద్ధులఁ బెట్టు మంగనాజనులసం | రక్షకు నెల్లకార్యముల మంత్రి\nజనములతోడ విచారించి చేయంగ | వలయును; గుప్త నివాస మొండె\nమాడువు మీఁ దొండె మాటు లేని యరణ్య | తల మొండె మంత్ర విధానమునకు\nనర్హముల్‌ గేవల మైనట్టి మంత్రంబు | గోపనం బొందినఁ గురువరేణ్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","058","ఆ.","యఖిల కర్మములు ఫలావాప్తి నొప్పుఁ బం | గ్వంధజడులు బధిరు లైన నీ ర\nహస్య భాషణములయప్పుడు చేరువ | నునికి యొప్ప దార్యవినుతచరిత!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","059","క.","విను మంత్ర భేదనమున వ | చ్చిన కీడున కనఘ! శాంతి సేయు టరిది గా\nవున మంత్రులతో మంత్రా | వన నియమం బూఁది చెప్పవలయుం జుమ్మీ!!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","","సీ.","వ్యవహారములు శుచు లైన విద్వాంసులఁ | దోడుగఁ గొని తీర్పు; దుష్టజనుల\nదండించునెడ వారి తప్పుల కొలఁదులు | మదిఁ దూఁచి చూచి తన్మాత్రదండ\nమాచరింపుము; విను మాయవ్యయములు సం | క్షేపరూపంబున రేపకడలు\nదానికి మును దేవతాపూజనము భూసు | రార్చనమును జేయు మమలబుద్ధి!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","060","తే.","ప్రొద్దు సాలంగ నెక్కినప్పుడు సమర్హ | భోజన క్రియ నిర్వహింపుము సుశీల\nమాన్య! తదనంతరమ గంధమాల్యభూష | ణాంబరములు నిజేచ్ఛమై ననుభవింపు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","061","క.","కొలు విమ్ము మాపుకడ యో | ధుల కెల్లను; సంధ్య వడ్డ దూతలనుం జా\nరుల సంభావింపుము; రా | త్రులఁ గాంతాభోగతత్పరుఁడ వగుము నృపా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","062","తే.","ఏమి క్రొత్తగఁ బుట్టిన నించు కేని | నలసుఁడవు గాక దాని నీ వరసి తీర్పు;\nమిది దెఱంగుగ నే ప్రొద్దు నింతవట్టు | నర్హములు కౌరవక్షితిపాగ్రగణ్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","063","క.","న్యాయంబుతోడ వివిధో | పాయంబుల నర్థముల నుపార్జింపుము భూ\nనాయక రాజ్య విఘాతము | సేయు జనుల నెఱిఁగి చంపఁ జెఱుపన వలయున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","064","క.","పనులయెడ మేలు గాంచిన | మనుగడ యగ్గలము చేసి మన్నింపుము రా\nజనయజ్ఞ! భృత్యకోటిం | గొనియాడుము సేఁతపేరు క్రుచ్చి కొలువునన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","065","క.","నీ వలనను భక్తిస్నే | హావేశము గలిగి శూరుఁడై యలజడికిం\nదా విసువని సత్కులజుం | గావింపుము సైన్యవిభునిగాఁ గురుముఖ్యా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","","సీ.","ఆత్మరంధ్రము లించు కైనను నొరులకు | నెఱుఁగ రాకుండఁగ మఱువు సేయు\nమన్య రంధ్రంబుల నారసి కనుము; శ | త్రుల కడ బుద్ధియు బలుపుఁ గలుగు\nవారల నెఱిఁగి భూవర! యొక్కమై నీగి | మన్నన నెఱపి తన్మానసములు\nనీ యెడ నార్ద్రంబులై యుండఁ జేయుము | చేరువనృపులకు వైరబంధ","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","066","ఆ.","మెట్లు గలుగు దాని నేమఱకుండుము | వారి యవుల నున్నవారు మిత్రు\nలగుదు రెల్ల భంగి నధిప! యుదాసీను | లట సమీపవర్తు లైన విభులు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","067","క.","వీరుల సప్తాంగంబులు | నారసికొని యునికి కార్య మవనీశ! సదృ\nక్సారబలుఁ డైన నృపుతో | గారవమున సంధి సేయఁగావలయుఁ దగన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","068","తే.","దైవమానుష బలములు దఱిఁగి యుండు | నెవ్వనికి నెప్పు డప్పుడ యెసక మెసఁగ\nవైర మతనితోఁ బాటింపవలయుఁ జెఱుచు | టప్పనము గొను టర్హత్వ మరసి నడపు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","069","క.","నడపునఁ గోల్పుచ్చఁగ నగు | నెడయు విడిసి యుండి చెఱుచు నిక్కయు నీ వే\nర్పడఁ గనుఁగొని యం దర్హము | నడపుము; నిజసైన్య రక్షణము వలయుఁ జుమీ!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","070","క.","ప్రెగడల మనసులు విరసము | లగుగతి నడచు రిపురాజ్య మరసి విభిన్నం\nబుగఁ జేసి కలఁచి పైకొని | జగతీవర! కొనఁగవలయు సౌకర్యమునన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మజునకు రాజనీతి విశేషంబులు చెప్పుట (సం. 15-9-7)","071","ఆ.","బలము లెసఁగ దైవబలమును గలిగి లో | గుట్టు చేటు లేనియట్టి నృపతి\nవలన మత్సరంబు వల; దాశ్రయంబు చం | దంబు పొందు వడయఁ దగు నృపాల!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","072","ఆ.","కుడువ నిచ్చు తఱియుఁ గురువర! కక్కించు | నవసరంబు నెఱిఁగి యరినృపాలు\nనీవు ధీరవృత్తి నిడుఁ ద్రాటఁ బోనిమ్ము | క్రమ్ము కపిల యనఁగ గ్రమ్మి చెఱపు?","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","","సీ.","ఉత్సాహ శక్తియు నుర్వీశ మంత్రశ | క్తియుఁ బ్రభుశక్తియుఁ గెలనివాని\nకిని నీకు నిట్టివి యని తారతమ్యముల్‌ | వెరవునఁ బరికించి వేర మెత్త |\nవలయుట నెఱిగల్గి పలుకక యుండంగఁ | దగుట యూహించు టుత్తమ విధంబు ;\nమూలబలంబును మొత్తాలవారును | మిత్త్రబలంబును శత్రుబలముఁ","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","073","ఆ.","గాననంబు బలముఁగై జీతగాండ్రును | నైనయట్టిబలము లాఱు నరసి\nయుచితకాల దేశ యుక్తంబులుగఁ బన్ని | కొనఁగ వలయు వాని కొలఁదు లెఱిఁగి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","074","తే.","సంపదల నాపదల నొక్క చంద మగుట | వికృతి నొందుట యా బలవితతులందుఁ\nగాంచి యెల్లప్పుడును హితకారి యైన | బలము నెక్కుడుగాఁ బ్రోవు భరతముఖ్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","075","క.","పరుల గెలిచి నిర్భయముగ | ధరణిఁ బ్రజం గాచువెరవు ధర్మపథమునం\nబరిపాలించిన వెలయుం | గురువర! కృపపెంపు వదలకుము ప్రజలయెడన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","076","క.","వినికి గలిగి రక్షించుచు | ననువున దయతోడిపాడి నాయతు లెల్లం\nగొనుచుఁ దగ నేలి పొగడొం | దినరాజున కుర్వి కామధేనువ కాదే!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","","సీ.","ధర్మమార్గంబున ధరణిఁ బాలించిన | నైహిక సుఖములు నగ్గలంపుఁ\nబొగడును బరలోక భూరి సౌఖ్యములును | సిద్ధించు; విపుల దక్షిణలు పెట్టి\nయశ్వమేధ ప్రముఖాధ్వరంబులు పెక్కు | లాచరించుట కంటె నధిక మండ్రు\nమేదినీ ప్రజల నత్యాదరంబును గరు | ణాతిశయంబు మధ్యస్థతయును","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","077","తే.","గలిగి బిడ్డల నరసిన కరణి గాఢ | రక్షణం బొనరించుట రాజవర్య!\nవినుము తమ్ముల నీగి మన్ననల ననుది | నంబుఁ గొనియాడు మానందనంబు గాఁగ.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","078","చ.","నరవర! రాజనీతుల జనస్తుతుఁడైన నదీ తనూజుఁడున్‌\nహరియుఁ బరాశరాత్మజుఁడు నాదిగఁ గల్గిన పెద్ద లెల్ల నీ\nకరయఁగఁ బెక్కు సెప్పిరి; మదాత్మయు నీదెసఁ బ్రీతి పెద్దయుం\nబొరయుట నేనుఁ గొన్ని యిటు పోలిన భంగి నెఱుంగఁ జెప్పితిన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","079","క.","నిత్యవిధి సద్వివేకము | సత్యవ్రతశీల! ధర్మసారజ్ఞ! భవ\nన్మత్యాకలితమ యైనను | నిత్యంబును వృద్ధసేవ నిష్ఠఁ జలుపుమీ!’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","","సీ.","అన విని ధర్మజుం డంబికా పుత్త్రుతో | ‘నాపగాసుతుఁడు లేఁ’ డబ్జనాభుఁ\nడాత్మపురంబున కరిగె; వాత్సల్యత | నీవు దక్కఁగ నాకు హితము సెప్ప\nనొడయఁ డెవ్వఁడు? భవదుపదిష్ట పథమున | నిష్ఠమై నడచెద; నెమ్మనమున\nనీవు ప్రీతిని బొందు నృపముఖ్య!’ నావుడు | నాతఁడు సంతసమంది యతని","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","080","ఆ.","‘నధిప! విశ్రమింపు మధికశ్రమంబు నా | తనువునందుఁ జెందె’ నని తగంగఁ\nబోవఁ జెప్పి; బాంధవావళి కభిముఖుఁ | డయి నిజాలయముల కరుగఁ బనిచి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","081","వ.","తాను నభ్యంతర గృహంబున కరిగి సుఖాసీనుం డైయున్న నమ్మానవనాథుతో గాంధారి ‘దేవా! వనంబున కెపుడు విచ్చేయువాఁడ?’ వని యడిగిన, నా భూవల్లభుం డద్దేవి కిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","082","క.","మా తండ్రి పరాశరసుతు | చేతం బడసితి ననుజ్ఞ; శీలపరత్వో\nపేతుఁ డగు ధర్మతనయుఁడు | ప్రీతి నొడంబడియె బంధుబృందయుతముగన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు ధర్మరాజునకు శత్రురాజుల జయించు తెఱంగు చెప్పుట (సం. 15-12-6)","083","ఆ.","ఇంకఁ దడయ నేల? యింతి! వే వెడలుద | మట్లు కల్లజూద మాడి పాప\nభాగు లైన నీదు పట్టుల సుగతికి | ననుచువాఁడఁ దపము నతిశయమున.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","084","వ.","అని పలికి యమ్మగువదిక్కు మొగం బయి ‘ వారికి సుగతి గల్గునట్లుగా నిప్పుడును గొన్ని పుణ్యక్రియ లజాతశత్రుననుమతితో నాచరించి పోదము గాక!’ యని నిశ్చయించి తనకుఁ దపోవనగమనంబునకై పౌరులయనుజ్ఞ గొనవలయు నని పాండవాగ్రజునకుం జెప్పం బనిచిన నతండు దగుపురజనంబుల నెల్లను బడి చేసి వెలార్చికొనుచు నఖిలబంధుమిత్త్రులునుం దానును వచ్చి ధృతరాష్ట్రు మందిర ద్వారపురోభాగంబున నిలిచె; నయ్యాంబికేయుండు గాంధారియుం దోడ రా వెడలి వారి సన్నిధికిం జని, బ్రాహ్మణ క్షత్రియ వైశ్య శూద్ర సంకులం బైయున్న యన్నగర జన ప్రకరంబు నుద్దేశించి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","","సీ.","‘కౌరవ కోటియు మీరుఁ బెద్దయుఁ గాల | మనఁగి పెనంగి యన్యోన్య సంభృ\nతాధిక స్నేహుల రై ప్రవర్తించితి | రనఘవర్తనులార! వినుఁడు నాదు\nపలుకు; వృద్ధునకుఁ దపశ్చరణంబున | కై వనంబున కేఁగు టర్హ కర్మ;\nముచిత కృత్యంబుల యోజ మీ రెఱిఁగిన - యదియ కా మదిముదమార మీర","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","085","ఆ.","లెల్ల నా కనుజ్ఞ యిచ్చి కానకుఁ బుచ్చుఁ | డనుడు సర్వజనులు నశ్రు పిహిత\nదృష్టు లగుచు గద్గదిక నెలుం గెడలఁగ | నార్తి దోఁప నేడ్చి రధిపముఖ్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","086","వ.","విని ధృతరాష్ట్రుఁడు వారి కిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","","సీ.","‘ప్రజ ముద మొందంగఁ బాలించెఁ బుడమి శం | తనుఁ; డనంతరము శాంతనవు చేత\nరక్షితుఁ డగుచు మీరలు ప్రీతిఁ బొదల వి | చిత్రవీర్యుండు నిద్ధాత్రి యేలెఁ |\nబదపడి పాండు నృపాలుండు మీరు హ | ర్షింపంగ భూమి రక్షించెఁ బిదప\nధర్మనందనుని చందము మీ యెఱింగిన | యది; సత్యధర్మాత్ముఁడైన యితని","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","087","తే.","ననుసరింపక యన్యాయ మాచరించి | దుర్ణయంబున నిల యేలి త్రుంచెఁ గులము\nనుర్విఁ గల భూపతులను దుర్యోధనుండు; | వాని దుశ్చేష్టలకు మూల మేన కాదె!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","088","వ.","అది మీ మనంబులం బెట్టక.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","089","క.","మహి లెస్సఁగ రక్షించిన | మహిత గుణుల యన్న కొడుకు మనుమం డని నా\nకు హితంబు గోరి కరుణా | సహితుల రై యిం డనుజ్ఞ సద్వ్రతమునకున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","090","వ.","అని యప్పు డజ్జనంబులమనంబుల లేకున్నను దన కీ ళ్లుగ్గడించి యరణ్యగమనానుజ్ఞాకరణంబునకుఁ బ్రార్థించి యవ్విభుండు వెండియు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","091","ఆ.","వృద్ధ కృపణ పుత్త్ర విరహిత గాంధారి | యీ నెలంతఁ జూచి యైన మీర\nలకట! కాననమున కరుగుట మే లని | మా కనుజ్ఞ యిండు మాన్యులార!’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","092","వ.","అని పలికి పాండవాగ్రజుం జూపి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","","సీ.","తమ్ముల నడుమ నీతండు దిక్పాలక | మధ్య భాసితుఁ డైన మఘవుఁ బోలి\nమహనీయ విభవ సమగ్రత వెలిఁగెడు | నేమిట నేమఱ కెపుడు మీర\nలీతనిఁ బొదివి సంప్రీతిగ వర్తింపుఁ | డయ్య! యిల్లడ యిమ్మహానుభావు\nనిడితి మీకడ; మిమ్ము నెల్ల భంగులఁ దన | పరిపాలనంబునఁ బరమసుఖులఁ","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","093","ఆ.","గా నొనర్చువాఁడు గా నప్పగించిన | వాఁడ నేను మీకు వేఁడి దాఁకు\nనట్లుగాఁ జరింప నస్మత్కులీనుల |కధిక దుఃఖకారి నైతిఁ గాని.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","094","క.","అరయ నెన్నం డైనను | మీరలు నా కెగ్గు గాఁగ మెలఁగుట లే; దో\nపౌరవరులార! నన్నున్‌ | గారవమున ననుపరయ్య కాననమునకున్‌!’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","095","వ.","అనినం బౌరజనంబు లేడ్పులు మ్రింగికొని యొండొరులం జూచుచు నూరకున్న నమ్మహీశ్వరుండు మఱియును.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","","సీ.","‘సాధుచరిత్రయు శాంతయు నైన యి | గ్గాంధారియును నేను గాఢ వినయ\nమార మీ తెలి విట్లు గోరుచు నున్నార | మఖిల ధర్మాభిజ్ఞుఁ డగు పరాశ\nరాత్మజుండును ధార్మికాగ్రణి పాండవా | గ్రజుఁడును నాకు నరణ్య గమన\nమునకు నిచ్చి రనుజ్ఞ; మోడ్పుఁ గే లౌదలఁ | గదియించి మిమ్ము వేఁడెదఁ గృపాఢ్యు","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","096","తే.","లార! యనుమతి సేయుఁడు మీరు’ ననుడు | వార లుత్తరీయంబులు వదన వినిహి\nతములుగాఁ జేసికొని రోదనము రవంబు | లెసఁగఁ జేసిరి విను ధరణీశవర్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుండు వనవాసంబునకుం బురజనులచే ననుజ్ఞ గొనుట (సం. 15-13-8)","097","వ.","అట్లేడ్చి యుడిగి తమయంతవట్టునుం గూడికొని కార్య వచనంబు లార్యచరితుండును జతురాలాప కల్యుం డును నగు శంబు వను విప్రోత్తమునకుం జెప్పి యిత్తెఱంగున ధృతరాష్ట్రునితో నాడుమని నియోగించిన నాతం డారాజు నగ్రభాగంబునఁ జేరి సవినయంబుగా ని ట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","","సీ.","‘భరతవంశోత్తమ | పౌరజనంబులు తమ మాటలుగ భవత్సన్ని ధాన\nమున న న్నుపన్యాస మొనరింపఁ బంచిన | యట్టిభాషణము లేకాగ్రబుద్ధి\nనవధరింపుము! మీ మహాన్వయంబున మహీ | విభులయం దొప్పమి వెదకి యైనఁ\nగానము మము మీరు గన్నట్టి ప్రజల నె | ట్లట్ల రక్షించితి రాదరమున","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","098","తే.","వినుము! దుర్యోధనుండు చేసిన యనర్హ | మొక్కటియు లేదు; నినుఁ ద్రిలోకోత్తరుండు\nసత్యవతి కొడు కే మని సమ్మతించి | పంచె దానిన చేయుము పరమనియతి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","099","క.","అడ లెడఁబడఁగా మమ్మును | విడిచితి గురు వైన శోక వేదన యే మిం\nకుడిపికొనునప్పటికిఁ దో | డ్పడు నీదగు సద్గుణములు బంధులు వోలెన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","100","ఆ.","ధాత్రి శంతనుఁడు విచిత్రవీర్యుఁడుఁ బాండు | రాజు నెట్టు లట్ల రాజరాజు\nప్రజకు సంతసముగఁ బాలించె; నీయందు | నతనియందుఁ గలదె యధిప! యెగ్గు?","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","101","వ.","భీష్మద్రోణ కృపద్రౌణి కర్ణ కృతవర్మ, శల్యు, లొక్క దిక్కును, భీమార్జుననకుల సహదేవ ద్రుపద విరాట సాత్యకు లొక్కదెసయు నై విధిప్రేరణంబునం బోరిరి; వారివలన నఖిల క్షత్త్రియసంక్షయం బావహిల్లె నది యొక్క దుర్యోధను చేతన యయ్యెనె? యట్లుం గాక రణంబు రాజుల కుత్తమ ధర్మంబ కాదె! యందుల మరణంబును సుగతికరణకల్యంబు; నీ సుతుండు సహాయులుం దానునుం బుణ్యలోకసౌఖ్యంబునంబొందియున్నవాఁడు; ధర్మాచరణశాలి వగు నీకును సుగతిప్రాప్తి సులభంబ యగు; నిట మీఁదటికి మా భాగ్యంబునం జేసి పరమ కృపాభరితు లైన పాండవులు మాకు రక్షకులుగాఁ బడసితి; మాకర్ణింపుము.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","102","తే.","స్వర్గ మైనను బాలింపఁ జాలువారు | వారలకు భూమిపాలన విధి యనంగ\nనెంతపని? వీరి చేతికి నిచ్చి తిపుడు | మమ్ము నెల్ల విధంబుల మనిచి తధిప!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","","సీ.","ధర్మపుత్త్రుఁడు దీర్ఘదర్శి, మహోదాత్త | సచివుండు, బంధు రక్షణ పరుండు,\nరిపు నెడ నైనను గృప పెద్ద, భావసం | శుద్ధియుఁ బ్రతిభయు సువ్రతంబు\nనితనికి వెన్నతో నిడినవి | యొరులను దనయట్ల కాఁ జూచుఁ దమ్ము లెల్ల\nసన్నుతి కెక్కిన సకలగుణముల ని | మ్మహితాత్ముచందాన మమ్ముఁ బ్రోచు","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","103","తే.","మాత్రయే దేవవిషయసమంచితాగ్ర | హార సజ్జన మాన్యంబు లైన గ్రామ\nములు దగంగ రక్షింతురు వెలయఁ దారు | నిత్తు రూళ్ళులు దేవమహీసురులకు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","104","క.","మృదువులకుఁ జాల మృదువులు; | విదితయశా! వినుము పాండవేయులు కడు బె\nట్టిదులు బెడిదంపు వారికి | మదలోభిత్వములు లేవు మందున కైనన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","105","క.","శూరులు, శాంత స్వాంతులు, | పౌరజన ప్రకర జానపదచయ నిత్యా\nపార ప్రమదాపాదన | పారగు లతుల గురుభక్తి పరతంత్రాత్ముల్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","106","తే.","గొంతి దేవికిఁ గోడండ్రకును మనములఁ | గరుణ యగ్గల మై యుండు ధరణినాథ!\nపౌరులందును జనపద ప్రజల యెడను | నాడుదురు మేలు తమ కగ్గ మైన యపుడు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","107","తే.","వీర లెప్పుడు మము నీవు గారవించు | టెఱిఁగి మన్నింతు రమలినహృదయ! కలఁక\nదక్కి ధర్మజుపై రాజ్యతంత్రభార | మిడి మనంబున నూఱడి యిచ్చ సలుపు.’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","108","వ.","అని చెప్పె ని ట్ల వ్విప్రముఖంబునఁ బౌరులభాషణంబులు విని ధృతరాష్ట్రుండు ప్రీతుం డయి సముచిత ప్రకారంబుల నజ్జనంబులం గ్రమంబున వీడుకొలిపి, కౌంతేయాది బంధువులను మిత్రులను నిజనివాసంబులకుం బోవం బనిచి, గాంధారీ సమేతుం డై యభ్యంతరమందిరంబున కరిగి యద్దినశేషంబును రాత్రియుం దగు వర్తనంబులఁ గడపి, మఱునాఁడు విదురుని రావించి ‘మృతు లయిన బాంధవుల కెల్లను సవిశేషశ్రాద్ధంబులు చేయు తలంపు పుట్టి కొన్ని దివసంబులు పయనంబు మానితి; మానిత మాననీయ చరిత్రుం డగు ధర్మపుత్త్రుపాలికిం బోయి నీ విక్కార్యంబు సంఘటింపు’ మని పనిచిన నతం ‘డట్ల చేసెద’ నని యనుజసహితుం డై యున్న యన్నరేంద్రునిం గాంచి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","","సీ.","‘మీ తండ్రి సురనదీసూతి బాహ్లికులకు | సోమదత్తునకుఁ, దత్సూనునకును,\nదుర్యోధనాదిసుతులకును; దక్కును | గలుగు బంధులకు నుత్కర్ష మెసఁగ\nశ్రాద్ధముల్‌ సేయు విచారంబు దోఁచిన | మసలెఁ గార్తికపౌర్ణమాసి దాఁక\nవనమున కరుగ కప్పని నీకుఁ బోలిన | యట్టులు గావింపు’ మనిన నాతఁ","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","109","తే.","డెంతయును వేడ్క నమ్మాట కియ్యకొనియె; | నర్జునుండును బ్రీతుఁ డై యర్హ మనియె;\nభీముఁ డపుడు కమర్చిన మోముతోడ | విదురు వదనంబు సూచుచుఁ బెదవు లదర","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","110","వ.","ఏమేనిం బలుకం జూచినన్‌ బీభత్సుండు మెలుపున నతని వారించి యల్లన యిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","","సీ.","‘రాజు వృద్ధుఁడు ధృతరాష్ట్రుండు భీష్మము | ఖ్య జ్ఞాతులకు శ్రాద్ధకర్మ మాచ\nరింపఁ దలంచి యర్థించె; భవజ్జిత | ధనధాన్యములు నీవు దాని కియ్య\nకొనమి యశంబునకును ధర్మమునకు వి | ధ్వంసంబు సేయదే? ధర్మతనయు\nతలఁచినపని విఘ్నితము సేయఁదగునయ్య? | మనకు నయ్యంబికాతనయుఁ దొల్లి","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","111","ఆ.","వేఁడికొందు మతఁడు వేఁడెడుఁ గానకు | నేఁగుచుండి మనల నిప్పు డింత\nసూడవలదె? యొండులాడక యప్పని | సలుపు టొప్పు బాహుశాలి! నీకు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రునితో శంబు వను విప్రుఁడు పౌరజన సమ్మతి చెప్పుట (సం. 15-15-10)","112","క.","అని చెప్పఁగ జెవిఁ దాఱిచి | విని ధర్మతనూజుఁ డంత విజయునిఁ బొగడెన్‌\nమనమున నమ్మాటల క | య్యనిలతనయుఁ డిట్టు లనియె నన్నరుతోడన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","113","క.","‘మును చేసినయవి చాలవె? | విను గాంగేయాది బంధువితతికిఁ దగ నిం\nకను శ్రాద్ధంబులు వలసిన | మనము దగమె చేయ దుష్టమతి యతఁ డేలా?","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","114","క.","మఱచితె యాతఁడు మనలం | బఱచిన బన్నములు భీష్మ బాహ్లిక ముఖు ల\nత్తఱి నెటఁ బోయిరి? వారల | నెఱుఁగమె మన? మట్టి బంధు లేటికి మనకున్‌?","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","115","వ.","వారి విషయం బైన మేలునకు మాఱాడుట యెగ్గు గా; దాకర్ణింపుము.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","116","తే.","కర్ణునకుఁ జేయవలసిన గారవమున | గొంతి యింకను శ్రాద్ధ మత్యంతవిభవ\nముల్లసిల్లంగఁ జేయుఁగా కుచిత నిరతి | యావిధమునకు మాఱాట సూవె యెగ్గు.’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","117","వ.","అని పలికి వెండియు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","","సీ.","‘పాంచాలి నవమానపఱిచిన తెఱఁగును | నయ్యింతి వెనుక రా నడవిఁ గలయ\nధర్మజుచన్న చందంబును మది గీఱి | యుండక మఱ పెట్టు లొలసె నీకు\nనాంబికేయుఁడు తండ్రి యగుట నాఁ డెటఁబోయె | భీష్ముండు మొదలగు పెద్దవారి\nబాంధవం బేమయ్యెఁ బార్థ! యీవిదురుఁ డె | ఱుంగఁడే వారల భంగి?’ యనిన","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","118","ఆ.","ధర్మజుండు భీముఁ దగువచనముల న | దల్చె నరుఁడు మరియుఁ దగఁడె పూజ\nకాంబికేయుఁ? డిట్టు లనకుము మనకు న | గ్రజుని పనుపు సేఁత వ్రతము గాదె!’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","119","క.","అని భీము నదిమి విదురునిఁ | గనుఁగొని మా తండ్రి పుణ్య కర్మము లెమ్మైఁ\nదన బంధులకై చేయఁగ | మనంబునం దలఁచె నా సమంచితభంగిన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","120","క.","నా యింటి ధనము గైకొని | చేయఁగలాఁ డమ్మహీశు చిత్తము సంతో\nషాయత్తంబుగ వేగమ | పోయి యనఘ! చెప్పు మవ్విభుఁడు ప్రియ మందన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","121","చ.","అన విని మెచ్చి ధర్మసుతుఁ డర్జునునిం గొనియాడి యాదరం\nబున విదురుం గనుంగొని ‘ప్రభూత విధానములన్‌ నిజేచ్ఛ నా\nధనమును నర్జునార్థమును దాఁ గొని శ్రాద్ధము లాచరించు నాఁ\nడనఘ! కురూద్వహుం డిది మదాత్మకు నిం పని విన్నవింపుమీ!’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","122","వ.","అని చెప్పి మఱియు ని ట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","123","క.","‘వనవాసాయాసంబుల | ననయంబును నలఁగి దాని నాత్మ నిడి మరు\nత్తనయుండు పెక్కులాడెఁ ద | గని మాటల; దీన రాజుఁ గనలకు మనుమీ!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","124","క.","ఇతఁ డేమి యన్ననే మగు? ధృతరాష్ట్రుఁడు మాకుఁ బరమదేవత; విను స\nమ్మతిఁ దత్ప్రసాదముం బడ | సితి మేమును దత్కృతాభిషిక్తుల మనఘా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","125","వ.","అని పలికి యప్పుడమిఱేఁడు వికచవదనుం డగుచు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","126","క.","మా తండ్రి నిష్ట విధములఁ | బైతృక విధు లాచరింపఁ బంపుము రథ్య\nవ్రాత కనక గో రథములన్‌ | జేతి కొదవ నర్జునుండు చేర్చుచు వచ్చున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","127","క.","గ్రామములు దేవతలకును | భూమిసురులకును గురు ప్రభువు ని మ్మను మీ\nపో మసలితి చెపు మాతని | కీ మాటలు వలయు పనుల కీవు మెలఁగుమీ!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","128","క.","అనినఁ బ్రియ మంది విదురుఁడు | చని యానృపుతో నజాతశత్రు కడకు నీ\nపనిచిన పనికిం బోయితి | వినిపించితిఁ దెఱఁ గతండు విని మోదమునన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","129","క.","నరువలను సూచె నతఁడుం | బరమ ప్రియ భరితుఁ డయ్యెఁ బార్థివవర! య\nయ్యిరువురుఁ బ్రాణంబులు డాఁ | పరు నీకును ధనము దాఁచు పని కలిగెడినే?","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","130","క.","చేయుము విచ్చలవిడి గాం | గేయ ప్రముఖులు నిరస్త కిల్బిషు లై మో\nదాయత్త చిత్తులుగ భూ | నాయక! శ్రాద్ధములు జగమునం బొగ డెసఁగన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","131","చ.","కనకము మేలి రత్నములు గ్రామములన్‌ హయగోవ్రజంబులుం\nదనియఁగ నిమ్ము సర్వవసుధాసుర కోటులకున్‌ నిజేచ్ఛ నీ\nతనయులు పుణ్యలోక సుఖధామము లై విలసిల్లునట్లుగా’\nననుటయు నాంబికేయుహృదయంబున మోదమెలర్చె భూవరా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","132","చ.","పదపడి భీముమాట లొకభంగి నెఱుంగఁగఁ జెప్పి, ‘వాఁడు దు\nర్మదుఁ, డవి పాటి గావు కురురాజ మహత్తర! పెట్టకుండు నీ\nహృదయమునందు వాని నని యేర్పడ ధర్మజు పార్థువాక్యముల్‌\nవిదురుఁడు సెప్పె సంతసము వెల్లిగొనంగ ననేకభంగులన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","133","ఆ.","అట్లు సంతసిల్లి యధిప కార్తిక పౌర్ణ | మాసి నవ్విభుండు మహిత భూమి\nదేవకోటి నెల్ల రావించి యంచిత | శ్రద్ధఁ జేయఁ దొడఁగె శ్రాద్ధవిభులు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","","సీ.","కనకాది వస్తువుల్‌ గడువేడ్క ధర్మనం | దనుఁడు పుత్తేర నుదాత్త భంగి\nబాహ్లికునకు, గంగపట్టికి, సోమద | త్తునకుఁ దదీయపుత్త్రునకుఁ దొలుత\nనంచిత శ్రాద్ధంబు లాచరించె సుయోధ | నాది కుమారుల కందఱకును\nబేర్వేర క్రియలు నీప్సిత విధంబులఁ దగ | నొనరించె సింధురాజునకుఁ దక్కుఁ","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","134","ఆ.","గలుగు బంధులకును వలయు రాజులకును | ద్రోణునకును బుద్ధిఁ దోఁచినట్టి\nయిష్టజనములకు నహీన భవ్యప్రకా | రములఁ బారలౌకికము లొనర్చి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","135","చ.","అతులితరత్న కాంచన గవాశ్వ విభూషణ వస్త్రకన్యకా\nక్షితిముఖ వస్తుదానములు గీర్తన కెక్కఁగ నవ్విభుండు సు\nవ్రతుఁ డయి చేసెఁ బంచదశవాసరముల్‌ నిజదానలౌల్య మ\nప్రతిహత వృత్తిఁ జెల్ల విని పాండుసుతాగ్రణి ప్రీతిఁ బొందఁగన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","భీముఁ డర్జునునితో ధృతరాష్ట్రు నుద్యోగంబునకుఁ బ్రతికూలించి చెప్పుట (సం. 15-17-15)","136","ఆ.","భూమి దాన విధులు భూవర యొక మాత్ర | నంబికాతనూజుఁ డాచరింప\nనంతఁ బోక యూళు లగ్రజన్ములకు నీ నతనిఁ బనిచెఁ బాండవాగ్రజుండు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","137","వ.","పనిచినం బ్రియంబు పెంపున హృదయంబు పల్లవింప నా భూవల్లభుం డనేకగ్రామంబు లగ్రహారంబులు గావించి గాంధారరాజు మొద లయిన నిజ బంధువులకు బహుళ దక్షిణలుగాఁ బార లౌకిక క్రియలు చేసెనిట్లు ధృతరాష్ట్రుండు; భారత రణంబున మరణంబు నొందిన బంధు లోకంబునకుం బుణ్యలోక సౌఖ్యాతిశయ పదంబు లగు పరమ శ్రాద్ధంబులు నిర్వర్తించి కృతకృత్యుం డై సర్వ కృత్యంబులుం జలిపి పాడ్యమి నాఁడు | రేపకడ ఋత్విక్సమేతుం డై యిష్టి నడపి | పాండవులను దక్కటి బంధువులను మిత్రులను రావించి వనవాసంబునకు సంకల్పంబు చేసి, సకల భృత్యజనంబులకు నర్హధనంబు లిచ్చి, గాంధారీ సమన్వితుం డై వల్కలాజినంబులు ధరియించి, యక్షత గంధ పుష్పంబుల గృహంబుఁ, బూజించి సర్వపదార్థంబులుం బరిత్యజించి యద్దేవియుఁ గదిసి నడవ యాజకు లగ్నులు నుపకరణంబులును ధరియించి ముందటం జేరువ నరుగ నగరు వెడలె, నట్టియెడ నేతెంచి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","138","క.","గొంతి మొద లైన కౌరవ | కాంతా జను లెల్ల నెవ్వగలఁ బొగులుచుఁ బ\nక్ష్మాంతంబుల బాష్పసలిల | సంతానము లురలఁ దోన చనుదేరంగన్‌","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","139","వ.","అజ్జనపతి చనుచుండె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","140","తే.","పాండవాగ్రజుఁ డక్కురుభర్తవలను | శోకదీనుఁడై తప్పక చూచి యేడ్చి\n‘హా మహారాజ ముఖ్య! యెం దరిగె?’ దనుచు | నొడలు కంపింపఁ జదికిలఁ బడియె నధిప!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","141","క.","నరుఁ డనునయించె వెస న | న్నరపతి నెత్తుచును దా ననయమున్‌ వనటం\nబురపురఁ బొక్కెం గురు భూ | వర! యద్దెస తెఱఁగు రాదు వాక్రువ్వంగన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","142","వ.","భీమసేన నకుల సహదేవులును గృప యుయుత్సు సంజయులును ధౌమ్యాది ధరణీ సురులును శోక వ్యాకులత్వంబు నొందిరి; గొంతి యడలుచు గాంధారి కరంబు నిజస్కంధంబున నిడికొని నడవ నంధనృపతి గాంధారీ స్కంధ భాగ కలిత బాహుం డై పోవుచుండె నప్పుడు పాంచాలియు సుభద్రయుఁజిత్రాంగదయు నులూపియు, సపుత్ర యగు నుత్తరయు మఱియుం గల యట్టి మగువలుం గురరీనిచయ నాదంబుల చందంబు దోఁప నాక్రందనంబు సేసి రయ్యవస్థ జూదంబునాఁడు పాండవులు పురంబు వెలువడునప్పటి దశం బోలియుండె నట్లు ధృతరాష్ట్రుకానన గమనంబు నిశ్చితం బగుటయు నాబాల వృద్ధంబుగాఁ బురజనంబు గనుంగొనం జనుదెంచిన.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","143","ఆ.","వచ్చి రెండ కన్ను వాన కన్నును నెఱుం | గనిపురంధ్రు లెల్లఁ గరము వంతఁ\nదలరు నంతరంగములతోడ నక్కురు | వృద్ధుఁ జూడ నార్తి వికలగతుల.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","144","క.","నేలను హర్మ్యంబులపై | నోలి నిలిచి చూచు మానవోత్కరముల శో\nకాలాప విలాపంబులు | నేలకు మింటికిని నడుమ నిండి చెలంగెన్‌","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","145","వ.","ధృతరాష్ట్రుండుఁ బురద్వారంబు నిర్గమించుచుండి సకల పౌరజనంబుల నిలువం బనిచె; విదురుం డక్కురు వృద్ధునితోడ వనంబున కరుగుటకు దృఢనిశ్చయుం డై పలికె; సంజయుండు నవ్విధంబు వాఁ డయ్యెఁ; గృపాచార్యుండును యుయుత్సుఁడు నత్తెఱంగుమాట లాడిన నాంబికేయుండు వారిని వారించి ధర్మనందనున కప్పగించి నిలిపి, కోడండ్ర నెల్లను సముచిత వచనంబుల మరల నియమించిన, వార లా వైచిత్రవీర్యునకు గాంధారికిం బ్రణమిల్లి బాష్పంబులు వదనంబున వెల్లిగొనుచుండ వీడ్కొనియును బాండురాజమహిషిం జూచికొని వెనుకం జనుచుండి; రా సమయంబున నజాతశత్రుం డాగొంతి కి ట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","146","క.","‘మా యయ్య కాననమునకుఁ | బోయెడు; నే నితనితోడఁ బోయెద శుశ్రూ\nషాయత్తుఁడ నై యుండెద | నీ యువిదలఁ గొనుచు మగిడి యేఁగుము తల్లీ!’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","147","చ.","అనుటయు గొంతి యక్కురుకులాగ్రణి కి ట్లను ‘నీవు తోడఁ గా\nననమున కేఁగుదెంచుట జనస్తవనీయచరిత్రుఁ డివ్విభుం\nడనుమతి చేయునే? యుడుగు మా పని; యియ్యమ యత్త నాకు, నీ\nమనుజవిభుండు మామ; గరిమంబుగ వీరలఁ గొల్చి పోయెదన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","148","తే.","ఇతని కియ్యమకును విను మేన చువ్వె | వలఁతి శుశ్రూష సేయంగ వత్స! మీర\nలాపనికి నేర్తురే? వీర లడవి కరుగ | నింట నుండఁగ నా మన మియ్యకొనునె?","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","149","వ.","అనిన నా ధర్మపుత్త్రుండును దమ్ములు నుచిత వచనంబుల వేఁడికొనిన నద్దేవి యగ్రతనయుం గనుంగొని.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","150","క.","‘వీరలయెడఁ గొడుకా! యప | చారంబులు పలుకుదునె? విచారము విడు; మే\nనే రూపంబున నిలువన | గారవమున నిది వ్రతంబుగాఁ గైకొంటిన్‌.’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","151","వ.","అని పలికి నిజస్కంధంబున నున్న గాంధారి కరంబుఁ గరంబు నయంబునం బాపి, యతని దిక్కు మొగం బై.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","152","క.","‘నీ వేమియు ననకుము సహ | దేవుని నేమఱక యరయు; దినకరసుతునిన్‌\nభావమునఁ దలఁపు; మే నా | దేవసముని పుట్టు వడఁచితిం గపటమునన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","153","క.","అది పాపము దానికి నా | మది నెప్పుడు వగతు విమలమానస! యక్కీ\nడు దొలంగునట్లుగా స | త్పదార్థ దానములు చేయు తాత్పర్యమునన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","154","ఆ.","అవ్విధమునఁ గర్ణుఁ డాఱడిఁ బోయిన | నాదు మానసంబు పోదు నూఱు\nపఱియ లై తలంప బలుఱాతఁ జేసిన | వారు గాఁగ వలయు వంశవర్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","155","క.","‘నీవును దమ్ములు భక్తి భ | రావేశముతోడఁ దలఁపుఁ డమ్మహితాత్మున్‌;\nద్రోవది నెప్పుడు దృఢ సం | భావన మన్నింపు మయ్య పౌరవముఖ్యా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","156","క.","భీమార్జున నకుల మనః | కామంబులు సఫలతా ప్రకాశంబులు గా\nభూమీశ! యరసి యొనరుపు | మేమిట నేమఱకు ధర్మ మిల యరయు నెడన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు గాంధారీసహితుండై వనంబునకుఁ బోవుట (సం. 15-20-1)","157","వ.","అని పలికి నానిశ్చయంబు శిథిలంబు గాదు | మీరు మరలుండని పలికినఁ బాండవాగ్రజుండు విషాదం బంది యూరకుండె; భీమాదులు డెందంబులు గొందలం బంద నశ్రు లొలుకం దలలు వాంచి; రిట్ల మ్మొత్తంబుగ మనంబు గుదిపడుచు మందం బై చెల్ల ధృతరాష్ట్రుండు గొండొకయెడగలుగం జనియె; నా ధర్మతనయుండు తల్లియాననం; బాలోకించి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","","సీ.","ఇది యేమి సేయంగ నెత్తి కొం టిమ్మాట | యాడకు; మేను ని న్నడవి కేఁగఁ\nబనుతునే? మముఁ దొల్లి పనిచి పనుల్‌ గొను | భంగిన సామ్రాజ్య భార నిర్వ\nహణము తెఱంగులు నప్పటి కప్పటి | కి ట్లని యానతి యిచ్చి నడపఁ\nబంపక యున్న నొప్పమి రాదె మాకు? ము | న్నీవును గృష్ణుండు నేవిధమున","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","158","తే.","నడిపితిరి కార్య మెఱుఁగవే యడలు వెల్లి | మమ్ముఁ బాంచాలి నిటు ముంచి యమ్మ! యడవి\nనెట్టు లుండెద?’ వనఁగ నయ్యింతి బాష్ప | పూర్ణనయన యై యూరక పోవుచుండె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","159","ఉ.","అయ్యమలాత్మతోడఁ బవనాత్మజుఁడి ట్లను ‘ధర్మపుత్త్రు నీ\nవెయ్యది యుక్త హేతువుగ నిమ్మెయిఁ బాసెదు? నీదు పన్పునం\nగయ్యము సేసి భూపతినికాయములం బరిమార్చెఁ దల్లి! నీ\nకియ్యన లక్ష్మి నూఁది చరియింపక యిప్పుడు వాయఁ బాడియే?","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","160","క.","మనమునఁ దోఁచిన దానము | లనుదినమును జేయుచును సమాశ్రిత జనులం\nబెనుచుచు బంధులఁ బ్రోచుచు | జననుతచరితమునఁ బరఁగు సౌజన్యనిధీ!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","161","క.","వనమున మాద్రీపుత్త్రులు | వెనుఁబడుటకుఁ దలరి తట్లు విక్రమమునకున్‌\nగొనకొల్పి తిట్లు వీరల | ననూన దుఃఖముల ముంచి యరుగం దగునే?’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","162","వ.","అనియె, నట్టియెడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","163","క.","ద్రోవదియు సుభద్రయు శో | కావేశం బడర మోము లశ్రులఁ దోఁగం???\nగా వెక్కి వెక్కి యేడ్చిరి, భూవర! పాండుక్షితీశ పుత్త్రులు నేడ్వన్‌!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","164","క.","పరిజనములు కన్నీళ్ళులు | దొరఁగఁగ నడ లొంది వారితోడం జని రి\nప్పరుసునఁ దనదుతనూజులు మరలమికిం బాండురాజమహిషి మఱుఁగుచున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","165","వ.","‘తెగ నాడకున్నఁ బోవ’ రని కన్నీరు దుడిచికొని వారలం గలయం గనుంగొని, వారలు వినుచుండం దత్పరి జనంబుల తోడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","","సీ.","‘దుర్ద్యూతమునఁ దారు దూలపోవుటయును | నా సభ యపకీర్తి యగు తెఱంగు\nపాటిల్లుటయుఁ, బెక్కుభంగుల నడవుల | నిడుమలఁ బడుటయు నే సహింపఁ\nజాలక కార్యంబు చర్చించి సంధిమై | నొవ్వని వా రెల్ల నవ్వఁ దలలు\nవంచి కౌరవులలో వర్తింప నే? లని | హరితోడ నాడితి; నవ్విధమున","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","166","ఆ.","మాననీయు ధర్మసూను నాగాయుత | బలుని భీము శత్రుభంజనైక\nశీలుఁ బార్థు శౌర్యలోలురఁ గవల దై | న్యంబు నొందఁ జూచు టర్హ మగునె?’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","167","వ.","అని ధర్మతనయు వదనంబు వీక్షించి, పాంచాలిం జూపి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","","సీ.","‘గౌరవంబున సుకుమారత్వమున నొప్పు | నిప్పొల్తిఁ దలవట్టి యీడ్చి తెచ్చి\nసభలోన నట్లు దుశ్శాసనుం డవమాన | పెట్టంగ నచ్చటి పెద్ద లెల్లఁ\nబలుకక యుండ నబ్బన్నంబునకు నోర్వ | వలసె మీ కప్పటి కలఘుతేజ!\nనీ తేజ మట్టులు నీ ఱయి పోయినఁ | బాండునికులము చెప్పంగఁ జూప","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","168","తే.","లేకపోదె యబ్భంగిఁ బల్కితి ముకుందు | తోడ నేను మీ రెమ్మెయి రూఢి కెక్కి\nవెలుఁగఁ గోరుట కతమునఁ దలఁచి; దాని | ననిలసుతుఁ డెత్తిపెట్టె; నే మనఁగఁ గలదు?’","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","169","వ.","అనిన విని ధర్మసుతుండును భీముండును సిగ్గు వడి; రిట్లు పలికి గొంతి యిమ్మాటకు భీము చిత్తం బె ట్లగునో యనుతలంపున ధర్మసుతున కతనిం జూపి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","170","ఉ.","‘నామది నొండు లేదు; విను నవ్వితి నీతనితోడ; నీదు ల\nక్ష్మీమహిమన్‌ మనం బలరఁ జేసితి నుత్తమదానముల్‌; జన\nస్తోమ నుతంబుగా నడపఁజూచితి జన్నము గన్నులార; నిం\nకేమి కొఱంత నా; కుడుగ; నెట్లును బోదు నరణ్యవృత్తికిన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","171","తే.","రాజ్య ఫలము కామింపఁ బుత్త్రా! సమగ్ర | తపమునకు ఫల మైన యుత్తమ గతి ప్ర\nసిద్ధి గోరుదు నది గల్గఁ జేఁత కిట్టి | తోడు మఱి నాకుఁ గలుగునే? దురితదూర!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","172","క.","కురు రాజునకును దేవికిఁ | బరిచర్య లొనర్చుచుం దపంబునఁ గృశతం\nబొరయు తనువుతోఁ గడపెదఁ | గరము నియతి నింకఁ గలుగు కాలము వత్సా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","173","వ.","మీరు మరలుం’ డనియె; నట్టియెడ నప్పాండురాజమహిషి, తమతోడ వనవాసంబునకై వచ్చుటకుం గడంగు టయు, దాని కొడంబడక పాండవులు దగు పలుకులం బ్రార్థించుటయు నెఱుంగుం గావున ధృతరాష్ట్రుండు ‘ధర్మతనయుం డెట్లు సెప్పెనట్లు సేయు’ మని విదురసంజయులచేత నద్దేవికిఁ జెప్పి పుత్తెంచిన వార లేతెంచి యబ్భంగి చెప్పినను వదలక వారి పలుకు లాయమ వారించి దృఢనిశ్చయంబునఁ గొడుకులఁ గోడండ్రను దక్కటి బంధుజనులకు సర్వభరత భార్యలను బరిజనంబులను గలయం గనుంగొని ‘యి ట్లేల వచ్చెదరు? నిలువుండు; సుఖుల రై యుండుం’ డనుటయు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","174","క.","హృదయములు దలర నందఱుఁ | బ్రదక్షిణము గాఁగ నేడ్పుఁ గ్రందుటెలుఁగు లె\nల్ల దెసలఁ జెలఁగఁ దిరిగి త | త్పదంబులకు నెఱఁగి నంతఁ దనువులు దూలన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","175","వ.","నిలిచి రందుఁ బాండవు లేవురుం బాండురాజ మహిషి ననుప మఱియుం జని యాయమను ధృతరాష్ట్ర గాంధారులను గలిపి ‘వారల నిరువుర నుద్దేశించి’ మీరు వనంబునకుం బోయి తానును లేకున్న మా కెట్లు కాలంబు గడపవచ్చు ననుతలంపునం దన్ను నెంత ప్రార్ధించినను గొంతి నిలుచుట కొడంబడ దయ్యె; నీ సాధ్వికి బుద్ధి సెప్పికొనుచుం బరిచర్యసేయించు కొం’ డని యప్పగించి, యారాజునకు నద్దేవికిం గుంతికిం బ్రదక్షిణంబు సేసి దండ ప్రణామంబు లాచరించిన, దీవించి వా రామంత్రణంబు సేయ నా ధర్మపుత్త్రాదు లశ్రుప్లావితంబు లగువదనంబులతోడ మరలి వనితాజనంబులం దోడ్కొని.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","176","తే.","పొగులుచును నల్ల నల్లన పురికి నరిగి | రదియు నుమ్మలికంబు ప్రోవైన యట్లు\nచూడఁ గూడక యుండంగఁ జొచ్చి రాత్మ | మందిరము లందఱును బుధమాన్యచరిత!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","177","వ.","అట్లు పుర ప్రవేశంబు చేసి ధర్మనందనుండును దమ్ములుం దగిన వర్తనంబుల నుండి; రట నక్కురువృద్ధుండు నిశ్చింతుం డై గాంధారియుఁ గుంతియు విదుర సంజయులు నగ్నిహోత్రంబునకు వలయు ఋత్వి గ్జనంబులతోడ నరుగుదేర నలయక భాగీరథీ తీరంబునకుం బోయి, యొక్క యోగ్య ప్రదేశంబున విడిసెఁ; దదనంతరంబ యతండు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","178","క.","స్నానాదిక విహితాను | ష్ఠానంబులు నడపి శ్రుతి విశారద భూదే\nవానీక ప్రణయనమున | మానిత రుచి వెలుఁగుచున్న మహితాగ్నులకున్‌","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధర్మరాజు కుంతిని వనంబునకుఁ బోవలదని ప్రార్థించుట. (సం. 15-22-19)","179","తే.","అర్చ లిచ్చి హోమంబు సమంచితముగఁ | జలిపి యెల్లవారలకు భోజనము సంఘ\nటించి యాహారవిధి యాచరించి విదుర | సంజయుల యొనర్చిన దర్భశయ్య నుండె.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు శతయూప రాజర్షి యాశ్రమంబున వసియించుట (సం. 15-25-9)","180","వ.","ఆ శయ్యకు ననతిదూరంబునం గల్పితం బైన తల్పంబున గాంధారియుం దదనంతర సన్నిహితశయనంబున గొంతియు నింత నంత విదుర సంజయులును జుట్లం దమకుఁ జూడం బోలిన చోటుల యాజకజనంబును విశ్రమించి; రట్లది న్ద శేషంబు సనిన సాయంతన కృత్యంబులు సలిపి; రయ్యామిని యచ్చటఁ గడపి సూర్యోదయ సమయంబునం గాలోచిత కరణీయంబులు నిర్వర్తించి యాంబికేయుండు తన వారును దానును గంగానది యుత్తరించి చని కురుక్షేత్రంబుఁ బ్రవేశించి యొక్క పుణ్యాశ్రమంబు నుపాంతంబునం దరుచ్ఛాయాశీతలంబైన సికతాతలంబున నాసీనుం డయ్యె; నట్లక్కురురాజు నిజాశ్రమప్రదేశంబునకు వచ్చుట శతయూప నామధేయుండును గేకయవంశ వర్యుండును దపోధుర్యుండును నైన రాజర్షిసత్తముండు విని యయ్యెడకు వచ్చి.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు శతయూప రాజర్షి యాశ్రమంబున వసియించుట (సం. 15-25-9)","181","క.","కని గారవంబునం దో | డ్కొని చని యర్ఘ్యాది విధు లకుంఠితవినయం\nబున నడపిన నయ్యాశ్రమ | మున నతఁడు వసింపఁగోరె భూపవరేణ్యా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు శతయూప రాజర్షి యాశ్రమంబున వసియించుట (సం. 15-25-9)","182","క.","కోరిన విదురాదులు నా | కౌరవపతితలఁపు మేలుగాఁ గొని తగ న\nచ్చేరువను బర్ణశాలలు | వే రచియించి రుచితంపు విధమున నధిపా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ధృతరాష్ట్రుఁడు శతయూప రాజర్షి యాశ్రమంబున వసియించుట (సం. 15-25-9)","183","వ.","అం దక్కురువిభుండు దానును గాంధారియుఁ జీరాజిన వసనులును సువ్రతపరులు నగుచుఁ గుంతీ విదుర సంజయులతో వసియించి తపం బాచరింప యాజకులు నిజకృత్యంబు నడపుచుండి రిట్లు నియమ నిష్ఠలతిశ యిల్ల నాభూవల్లభుం డచ్చటి మును ల చ్చేరువ నతి తీవ్రతపశ్చరణంబున నిజాంగంబు నిర్మాంసత్వంబునం జర్మాస్థులు గదియునట్టి కార్శ్యంబు దనకు నొప్పుగా వర్తి ల్లె నని యిట్లు ధృతరాష్ట్ర వృత్తాంతంబు చెప్పిన విని యవ్విచిత్రవీర్య నందనుండు పదంపడి యెట్టివాఁ డయ్యె? మునీంద్రా! యెఱిఁగింపు’ మనుటయు.","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ఆశ్వాసాంతము","184","శా.","ఆశాపాశ విమోచనోపకరణ వ్యాకోచహృద్ధామ! సం\nక్లేశో త్సారక దివ్యనామ! వర దృగ్లీలాప్త నిస్సీమ ల\nక్ష్మీశుంభ త్సురలోక చక్రపరశుచ్ఛిన్నా సురానీక! వి\nద్యాశోభా స్ఫురణాకృతీ! శమదమానంతర్య భాస్వీకృతీ!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ఆశ్వాసాంతము","185","క.","ముని హృదయ నిలయ పాదా! వినత జనావన వినోద! విద్యా విద్యా\nఘన చింతాంతిక దూరల | సన! పీత స్ఫీత సామజత్వగ్వసనా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ఆశ్వాసాంతము","186","మాలిని","అపరిమిత విభూతీ! యప్రమత్తానుయాతీ!\nలపన నిభృతవేదా! లక్షణ స్వైరనాదా!\nజపపర వరదాయీ! సర్వవిద్యా విధాయీ!\nవిపుల కృప కటాక్షా! విశ్వసంహ్లాదదక్షా!","","",""],
  ["ఆశ్రమవాసపర్వము","ప్రథమాశ్వాసము","ఆశ్వాసాంతము","187","గద్యము","ఇది శ్రీమదుభయ కవిమిత్త్ర కొమ్మనామాత్యపుత్త్ర బుధారాధనవిరాజి తిక్కన సోమయాజి ప్రణీతం బైన శ్రీమహాభారతంబున నాశ్రమవాసపర్వంబునందుఁ బ్రథమాశ్వాసము.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ఆశ్రమవాసపర్వము - ద్వితీయాశ్వాసము","001","క.","శ్రీసంబంధాయుర్గురు | తా సిద్ధిద చరణపద్మ! దాంత్యున్మీల\nద్ధీసద్మ శాంతిసేవ్యా | వ్యాసాది మునీంద్రభావ్య హరిహరనాథా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుని పాలికి నారదుండు మునులతో వచ్చి యత్తపోవనమహిమ చెప్పుట (సం. 15-26-1)","002","వ.","దేవా! వైశంపాయనుండు జనమేజయున కిట్లనియె; నట్లు వైచిత్రవీర్యుండు పరమతపోధుర్యుం డయి యుండె; నంత నొక్కనాఁడు నారద పర్వత దేవల మౌంజాయను లమ్మహీనాయకుం జూచువేడ్క నయ్యా శ్రమంబునకుం జనుదెంచిన.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుని పాలికి నారదుండు మునులతో వచ్చి యత్తపోవనమహిమ చెప్పుట (సం. 15-26-1)","003","క.","శతయూపుఁడు నయ్యెడకుం | గుతుకంబున వచ్చె; వారిఁ గుంతి వినయ సం\nభృతయై యందఱను సమ | ర్చితులుగఁ జేసినఁ బ్రహృష్టచేతసు లగుచున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుని పాలికి నారదుండు మునులతో వచ్చి యత్తపోవనమహిమ చెప్పుట (సం. 15-26-1)","004","వ.","ధృతరాష్ట్రుకడకుం బోయిన నతండు వినయ సంభ్రమంబులతో వినతుం డైన దీవన లిచ్చి యతని పెట్టించిన దర్భాసనంబుల నాసీనులై యుచిత సల్లాపంబులు సేయుసమయంబున నారదుం డన్నర నాథుతో శతయూప నామధేయుం డయిన ధరాధిపు పితామహుం డగు సహస్రచిత్యుం డను మహారాజు తన పెద్దకొడుకైన శతచిత్యునందు రాజ్యభారం బిడి యియ్యాశ్రమంబునకు వచ్చి తపశ్చరణంబున దుశ్చ్యవన సఖిత్వంబు వడసె; మఱియును బృషథ్రుండును, శైలాలయుండును, బురుకుత్సుండును నిందుఁ దపంబు చేసి యింద్రలోకంబు వడసి రా రాజర్షిసత్తముల నెల్లను నే నీలోకంబున మెలంగుచుండి యియ్యెడం గంటి నయ్యెడం జూచితి; నిది యితరదుష్ప్రాప్యంబయిన పుణ్యప్రదేశంబు; నీకుం గృష్ణద్వైపాయను ప్రసాదంబున నిచ్చట వసియింప సంభవించె’ నని పలికి వెండియు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుని పాలికి నారదుండు మునులతో వచ్చి యత్తపోవనమహిమ చెప్పుట (సం. 15-26-1)","","సీ.","‘ధరణీశ! యిచ్చటి తపమున నీవు నా | నృపుల యట్టుల విశిష్టపుఁ బదంబుఁ\nగందు; నీ తోడన గాంధారియును వచ్చు; | మీకు శశ్రూష యమేయ భక్తిఁ\nజేసి కుంతియుఁ బతిఁ జేరంగ నరుగు; న | ప్పాండుభూపతి సురపతి సమీప\nముననుండి యెప్పుడు నినుఁ దలంచు, నతండు | పోఁడిమి సేయఁగలాఁడు నీకు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుని పాలికి నారదుండు మునులతో వచ్చి యత్తపోవనమహిమ చెప్పుట (సం. 15-26-1)","005","ఆ.","ధర్మమూర్తి యైన ధర్మసూనుఁడు దన | యాత్మ గాన విదురుఁ డన్నరేంద్రు\nవినుతతనువుఁ దగఁ బ్రవేశించు సంజయుఁ | డతుల నాకలోకగతి వెలుంగు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుని పాలికి నారదుండు మునులతో వచ్చి యత్తపోవనమహిమ చెప్పుట (సం. 15-26-1)","006","వ.","అనిన విని యాంబికేయుండు గాంధారీకుంతీ సమేతంబుగా సంతోషంబు నొందె; నచ్చటియందఱును బ్రీతాత్ములై; రప్పుడు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుని పాలికి నారదుండు మునులతో వచ్చి యత్తపోవనమహిమ చెప్పుట (సం. 15-26-1)","007","క.","శతయూపుఁడు నారదుతో | ‘నతుల జ్ఞానాభిరామ’ యడిగెద నిన్నుం\nగుతుకంబున నొక్కటి; నీ | వితతకృపం దెలియఁ జెప్పవే నా’ కనుడున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుని పాలికి నారదుండు మునులతో వచ్చి యత్తపోవనమహిమ చెప్పుట (సం. 15-26-1)","008","వ.","ఆ దేవముని ‘నీ యడుగఁ దలంచినది యెయ్యది? యడుగు’ మనిన నతం ‘డిక్కురుపతి సుగతి గను’ నని నిర్దేశించితి; తద్విశేషంబు వినవలతు; వివరింపు’ మనుటయు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","","సీ.","ఆ సంయమీశ్వరుం డాతని కిట్లను | ‘నిచ్చమై నేను మహేంద్రు కడకు\nనరిగి సంభాషణ మాచరించుచు నుండ | నా సభ నిక్కౌరవాధినాథు\nవలనివార్తలు పుట్టి యలఘు తపోవృత్తి | నిష్ఠాతిశయము వర్ణించి’ రప్పు\nడవ్వాసవుఁడు చెప్పె ననఘ! నాతో ముని | జాతుఁడు ధృతరాష్ట్ర జనవిభుండు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","009","తే.","తపము మూఁడేఁడు లొనరించి తాను సతియు | దేహము ల్విడ్చి చని ధనాధీశు చెలిమి\nనతిశయిల్లు దివ్యాభరణాభిరాముఁ | డై విమానవిహార హృష్టాత్ముఁ డగుచు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","010","క.","అని పాండుని మది ప్రమదం | బునఁ దేలఁగఁ జెప్పె ‘ననుడు మోదము ధృతరా\nష్ట్రుని నెమ్మనమున నిండా | రె; నఖిల జనచిత్తములను బ్రియము దలిర్చెన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","011","వ.","ఇట్లు సద్గోష్ఠి నడపి యత్తాపసోత్తము లక్కురుపతిసత్తము నభినందించి యామంత్రణంబు సేసి నిజనివాసంబులకుం జని; రక్కాలంబున.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","","సీ.","పాండుపుత్త్రులు తల్లిఁ బలుమఱుఁ దలఁతురు | వగతురు, ధృతరాష్ట్రువలన సుబల\nనందన దెసను మనంబిడి; చింతింతు | రట్ల పౌరులు వంత నారఁ గూరి\n‘వృద్ధుండు ధృతరాష్ట్రవిభుఁడు సుఖార్హుఁడు | విగతజనం బైన విపినభూమి\nనెత్తెఱంగున వసియించు? గాంధారియుఁ | గుంతియు నత్యంత కోమలాంగు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","012","తే.","లడవి నుండంగ నెట్లోర్తు రకట! యిట్టి కొడుకులను రాజ్యసౌఖ్యంబు విడిచి యట్లు\nసనునె యక్కుంతిభోజుని తనయ? జనని | దొఱఁగిపోవుట కెంత గుందుదురొ వీరు!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","013","క.","ఆయాసంబున విదురుని | కాయము, సంజయుని మేనుఁ గందక యున్నే?\nపోయిరి ధృతరాష్ట్ర మహీ | నాయకుపై భక్తిఁ గాననమున వసింపన్‌.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","014","క.","అని యొండొరువులతోడ | న్వనట యెసఁగఁ బలుకుదురు మనంబులఁ గుంతీ\nతనయులు మాతృవియుక్తత | కనయము నడలుదురు కౌరవాన్వయముఖ్యా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","","సీ.","ధర్మపుత్త్రాదులందఱు నొక్కచో నుండి | ధృతరాష్ట్రు నాతని దేవిఁ బేరు\nకొని వారి కొడుకు లెల్లను ద్రుంగి రని, వార | లతి వృద్ధు లెమ్మెయి నడవిఁ గలిసి\nయున్నా రనియు, నింక నెన్నాళ్ళు లుండెడి | గొంతి వనంబునఁ గూరఁ దినుచు?.\nననియును, బంధుల నదయతఁ దునిమితి | మలుక ధైర్యంబున నడఁప మైతి","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","015","తే.","మనియు, నభిమన్యు వీరుని నతని తమ్ముఁ | గుఱ్ఱలను గర్ణునాఱడిఁ గోలుపోయి\nయొంటి వడితి మనియుఁ, గడు నుమ్మలంపు | మాట లాడుదు ర్పరిజనుల్‌ మఱుఁగుచుండ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","016","వ.","ఇ ట్లనుదినంబును ఘన చింతాక్రాంతులై యలంత నొందుదురు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","017","చ.","విదురుని సంజయుం దలఁచి వేదనఁ బొందుదు; రట్లు నెవ్వగల్‌\nహృదయముఁ గుందఁజేయఁ జెలువేది మనోజ్ఞము లైన భోగముల్‌\nవదలి వినోదముల్‌ సలుపు లాలసతం బెడఁబాసి రాజ్యసం\nపద నరయం దలం పెడలి పాడఱి యుండుదు, రేమి సెప్పుదున్‌!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","018","క.","ద్రౌపదియు సుభద్రయు సం | తాపం బందుదురు; పాండుతనయులు దలరన్‌\nభూపాల భవజ్జనకుని | చూ పందఱ మానసముల శోకము నదుమున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","019","ఆ.","పరమధీరు లైన పాండుతనూభవు | లిట్లు ధైర్యసార మెడలి వికల\nబుద్ధు లగుచు నుండి పోవం గడంగి ర | య్యంధనృపతిఁ జూడ నధిపముఖ్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","020","వ.","అట్టియెడ సహదేవుండు పాండవాగ్రజునకుం బ్రణమిల్లి భరితవినయుం డై.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","021","క.","‘ఏను మును చెప్ప వెఱచితిఁ | గాని యధిప! గొంతిఁ జూడఁగా జను టర్హం\nబైన పని; యింత కేదెస | దా నొందునొ విపినవాస దౌస్స్థిత్యమునన్‌?","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","022","తే.","గొంతి ప్రాణంబుతో నుండఁ గురువరేణ్య! | యచ్చటికిఁ జని యొకమరి యమ్మహాను\nభావ దర్శింప వలవదె? బావ నప్ప | ననుసరించుచు నెట్లున్న యదియొ సాధ్వి!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","023","క.","ధృతరాష్ట్రుఁడు గాంధారియు | నతిమృదులాంగకులు వల్కలాజినధరులై\nవ్రతచర్యల వన్యాహా | రత నలఁగుచు నున్నవారు రాజవరేణ్యా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","024","ఉ.","వారలఁ జూడఁ బోఁ దగు నవశ్యము దుర్దశ పుట్టకుండ మున్‌\nమీ‘రని చెప్ప నప్పుడు సమీపమునం జెవి దార్చి నెవ్వగం\nగూరుచు నున్న ద్రౌపది యగుం గరణీయము బంధు దుఃఖ సం\nతారక! మీకు నీతఁ డుచితంబుగఁ జెప్పిన కార్య మెమ్మెయిన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు శతయూపునితో ధృతరాష్ట్రాదులు సుగతిఁ బొందెడు తెఱంగు చెప్పుట (సం. 15-27-8)","025","తే.","గొంతి కోడండ్రు రెల్లను గురువరేణ్య! | యెత్తినడుగుల నున్నవా రత్తపస్వి\nనీ వరిష్ఠ దర్శింపంగఁ బోవఁ గోరి | యనియె నట్టు లయ్యిరువురు నాడుటయును.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","026","వ.","అమ్మానవనాథుండు కాననగమనంబు నిశ్చయించి పడవాళ్ళం బలిపించి ‘ధృతరాష్ట్రు దర్శింపఁ బోద; మనతి బహుళంబును బ్రధాన చతురంగ సముదీర్ణ భంగికంబునుం గా బలంబుల సమకట్టుం; డందలంబులునుం బాటబండ్లునుం గాఁ బెక్కాయితంబులు సేయుం; డనేక శకటంబులుం, బటకుటీరప్రకరంబును, నానావిధ భక్ష్య భోజ్యంబులునుం గొనివచ్చునట్లుగా నిపుణ పరిచారకుల నియమింపుండు; పౌర జనంబు లారాజుం జూచువేడ్కనెవ్వరు వచ్చినను వారల యోగక్షేమంబు లరసి సురక్షితంబుగా నడపింపం దగువారి నియోగింపుం; డెల్లి పయనం బని చాటింపుం’ డని పనిచిన వార లట్లు చేయ మఱునాఁడు యుయుత్సునిం గృపాచార్యుని ధౌమ్యుని రావించి ‘మీరు పురరక్షణంబునకు నిలువుం’ డని యత్యాదరంబునం జెప్పి,","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","","సీ.","ఏనికగములతో నేతెమ్ము నీ వని | బాహుదర్పోజ్జ్వలుఁ బవనతనయుఁ\nదేరులగమి చెలువారు నీచే నని | దేవసమాను గాండీవధరుని,\nగుఱ్ఱపు దళముల కొమరు వీ కలవడు | నని చారుతను మనోహారు నకులుఁ\nగాల్బల మమరు నీ కలిసి వచ్చుట నని | సన్నుతచేష్టితుఁ బిన్నతమ్ముఁ","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","027","తే.","బనిచె; వార లమ్మెయిఁ దూర్య నినద మెసఁగ | నాతపత్రావళి ధ్వజవ్రాత కలిత\nరత్నరోచులు రోదోంతరంబు నిండ | నరుగుదెంచిరి వైభవ మతిశయిల్ల.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","028","వ.","ద్రౌపదీ ప్రముఖ వధూజనంబులనుం దక్కునుం గల భరత భార్యల నందలంబులను గనకంపు బండ్లను నిడికొని రండని యంతఃపురాధికారుల నబ్భూరమణుండు నియమించిన, వార లట్ల చేసిరి; తానును మణిభా సమానంబును నీలవాలశోభిత షోడశ శ్వేతాశ్వ వ్యూఢంబును నైన రథం బెక్కి మౌక్తిక ప్రాలంబ మాలి కాద్యోతితంబు లగు నాతపత్రంబు లుల్లసిల్ల.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","029","తే.","వేణువీణారవంబులు వివిధ గాన | నాదములుఁ బాఠకారావ మేదురంబు\nలగుచు వంది బృందముల వాక్యాలి బెరసి | దిశలు దీటుకొనంగఁ బ్రదీప్తలీల.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","030","వ.","వెడలెఁ వివిధ వాహనారూఢు లయి పౌరు లప్పూరువంశవరు ననుగమించిరిత్తెఱంగున మెఱయు మహిమ నుజ్జ్వలుం డగుచుం జని భాగీరథి యుత్తరించి పాండవోత్తముండు కురుక్షేత్రంబు ప్రవేశించి చనుచుండ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","","సీ.","సంయమివరుఁ డైన శతయూప మునిపతి | యాశ్రమంబునఁ దదుపాంత భాగ\nమునఁ గదలీశోభియును మృగాకీర్ణంబు | నగు ధృతరాష్ట్రుని యాశ్రమంబు\nనెఱిఁగిన వా రదె యిదె యంచుఁ బేర్కొని | చూపి చెప్పిన ధర్మసుతుఁడు దేరు\nడిగిన భీమాదులు డిగ్గిరి; వాహనం | బులు సర్వజనులు నప్పురుష వరుల","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","031","ఆ.","ననుసరించి; రజ్జనాధిపుఁ డయ్యాంబి | కేయు నాశ్రమంబు డాయఁ జనుచు\nనచటిజనుల నడిగె ‘నయ్య వేఁడీ?’ యని | గద్గదిక నెలుంగు గడలుకొనఁగ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","032","వ.","అనిన వార లప్పుడమిఱేనితోడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు బంధుసహితంబుగా ధృతరాష్ట్రుఁ జూడఁబోవుట (సం. 15-29-18)","033","క.","‘యమునా స్నానంబునకును | సుమతోయాహరణమునకు సువ్రతుఁ డా సం\nయమి చనియె’ ననుచుఁ దన్మా | ర్గము సెప్పిరి నెమ్మిఁ దెలియఁ గౌరవముఖ్యా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","","సీ.","చెప్పినఁ బాండవు లప్పథంబున భక్తి | నరుగుచు నెదురుగ నరుగుదెంచు\nనంబికానందనుఁ డాదిగాఁ గలవారిఁ | గని రప్పు డన్నలఁ గడచి శీఘ్ర\nగామియై చని తల్లి కాళ్ళపైఁ బడి యేడ్చె | సహదేవుఁ; డధిక బాష్పప్లుతాస్య\nయగుచు నబ్భామిని వగచుచు నాతని | నెత్తి తాఁ గౌఁగిట నిఱియఁ జేర్చి","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","034","తే.","పేరుకొని చెప్పె నతని గాంధారి కంతఁ | గూడి యతఁడును దారు నక్కురుకుమారు\nలక్కురూద్వహు నన్నియతాత్ము దేవిఁ | గాంచి రనుజీవు లెఱిఁగింపఁ గౌరవేంద్ర!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","035","చ.","కని మఱి తల్లి పాదములఁ గ్రందుగఁ జేర్చిరి మస్తకంబు; ల\nవ్వనితయు నందఱం బొదివి వత్సలతన్‌ మన మార్ద్రభావ మొం\nద నురలు నశ్రుబిందువుల దందడిఁ జిక్కఁగఁ గౌఁగిలించి వా\nరి నయనవారి చేఁ దుడిచి ప్రీతిగ దీవెన లిచ్చె భూవరా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","036","తే.","అట్టియెడఁ బాండవాగ్రజ నధిక వినయ | భరితుఁడై కాంచి భీమునిఁ బార్థుఁ గవలఁ\nగనియె సంజయుఁ డెంతయు గారవమున | నాదరించి రయ్యేవురు నతనిఁ బ్రీతి.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","","సీ.","ద్రోవదిఁ దొట్టి వధూజనంబులుఁ దక్కుఁ | గలయట్టి భరత భార్యలుఁ గ్రమమునఁ\nగాంచిరి కురువృద్ధు గాంధారి గొంతిని; | వారలు గొనివచ్చు వారి కలశ\nములు పాండురాజ పుత్త్రులు పుచ్చికొని భరి | యించిరి; పురజను లెల్ల నధిక\nవినయత నమ్మువ్వురను గని; రవ్వేళ | నందఱు ముదమంది; రట్లు దగిన","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","037","ఆ.","వారు బలసి యునికి వారణపురమున | నున్నయట్ల కాఁగఁ దన్నుఁ దలఁచె\nమదిఁ గురూద్వహుండు తదనంతరంబ ని | జాశ్రమమున కెలమి నరుగుదెంచి.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","038","ఉ.","తారక శోభితాంబర విధంబునఁ బొల్పెసఁగంగ నాశ్రమో\nదారతలంబు బంధుజనతాకలనంబునఁ దాను జంద్రు నొ\nప్పార వహించి విస్ఫురితుఁ డై తనరెం గురుభర్త వచ్చి ర\nచ్చేరువఁ గల్గు తాపసులు చెచ్చెరఁ బార్థులఁ జూచు వేడుకన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","039","వ.","వచ్చినం గని వారల నెల్లను సవినయ ప్రణామంబులం బ్రీతులం జేసి పాండవు లలరు మొగంబులతో ధృతరాష్ట్రుం బరివేష్టించి యుండిరి; వనితాజనంబులు నొక్కవలన నిలిచి; రుచితాసనంబులనున్న యమ్మునులు సంజయు నాలోకించి ‘ధృతరాష్ట్రు బంధు జనంబుల నందఱం బేరువేర నేర్పడ మా కెఱింగింపవే’ యని యడిగిన నతండు వారల కి ట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","","సీ.","‘జాంబూనదచ్ఛాయ చందంబు వర్ణంబు | గలిగిన పలుచని గనప మేను,\nనుచిత దీర్ఘత్వ సమున్నత ఘ్రాణంబు | నిడుదలైన విశాల నేత్రములును,\nగంఠీరవంబు రేఖయు నొప్పఁ జూడ్కికి | నెంతయు వ్రేఁగైన యితఁడు ధర్మ\nతనయుఁ; డెఱ్ఱఁదనంబుఁ దనరిన మూఁపులు | నాయత స్ఫీతంబు లైన బాహు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","040","తే.","వులును వెడందయురంబు నై పొలుచు నితఁడు | భీముఁ; డుజ్జ్వల సుందర శ్యామ తనువు\nవారణేంద్రు కైవడియును, వారిజముల | యట్టి కనుదోయిఁ గల యితం డర్జునుండు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","041","తే.","సుందరాకారమునఁ దమ కెందు సదృశు | లొరులు లేమి తెల్లం బగుచుండ గొంతి\nయుభయ పార్శ్వంబు లందుఁ గూర్చున్న విష్ణు | శతమఖోపముల్‌ వినయభూషితులు కవలు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","","సీ.","నీలోత్పల చ్ఛాయఁ బోలు మై చాయయు, | నవపద్మదళములఁ దెవడు మెఱుఁగుఁ\nగనుదోయి, మధ్యాత్వమునకుఁ బ్రవేశించు | ప్రాయంబు, నత్యభిరామ మూర్తి\nయలవడఁ గైకొన్న యతులిత సంపద | చందంబు దోఁపించు చారుగౌర\nవంబును గలుగు నివ్వనిత పాంచాలి; యి | య్యింతి పార్శ్వమునఁ గట్టెఱ్ఱ మేను","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","042","తే.","వనజ సన్నిభ ముఖమునై యినుని మహిమ | యుజ్జ్వలాకృతి దాల్చినట్లున్న యీ ల\nతాంగి నారాయణుని చెలియలు సుభద్ర | నరుని వల్లభ సంయమినాథులార!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","043","ఆ.","వీరి కెలనఁ గనక గౌర మధూకాభ | తనువు లొప్పుచున్న వనిత లురగ\nపాండ్య సుతలు, నరుని భార్య; లులూపి చి | త్రాంగద యనఁ బరఁగ నాహ్వయములు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","","సీ.","ఇందీవరచ్ఛాయ కెనయైన చాయ నొ | ప్పిన మేను గలుగు నీ భీతహరిణ\nనయన భీముని భార్య; నవ్యచంపక దామ | గౌరాంగి యైన యిక్కమలవదన\nసహదేవు గృహిణి; మేచకనవకువలయ | వర్ణంబునకు సరివచ్చు కాంతిఁ\nజెలు వైన తనువునఁ బొలుచు నిన్నలినాయ | తాక్షి మాద్రీదేవి యగ్రతనయు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","044","తే.","పత్ని; వీరల కెలనఁ బాపటలు లేక | ధౌతసిత వస్త్ర పరిధానలై తనువుల\nనిభృతి దోఁపఁగ నున్న యిన్నెలఁత లాంబి | కేయు కోడండ్రు కరుణావిధేయులార!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","045","తే.","వీరి చందంబ యై కడు గారవమునఁ | దను సుభద్ర వొదువ నున్న తరుణి ద్రోణ\nకర్ణముఖ యోధవీరులఁ గలఁచి తెగిన | యట్టి యభిమన్యు ప్రియ యుత్తరాభిధాన.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","046","వ.","అని చూపి చెప్పె, నప్పు డాంబికేయుండు కౌంతేయాగ్రజున కిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","","సీ.","‘కుశలివై యుండుదే కురువంశ సత్తమ! | పౌరజనులు జానపదులుఁ దెఱఁగు\nతో నిన్ను ననుసరింతురె? తమ్ము లందఱు | సుఖ ముందురే? నీదు సఖులు సుఖులె\nబంధులు సంతోషభరితులే? యిష్ట భృ | త్యులు తగవైన కోర్కులు ఫలింపఁ\nగ్రాలుదురే? హర్షలీలలఁ బూర్వ రా | జన్యుల నడవడి సలుపఁబడునె?","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","047","ఆ.","నయముతోడి యప్పనముల భండారంబుఁ | బెనుతె? యగ్రహార జనులమీఁద\nగాలి యైన సుడియఁగా నీక యరయుదే? | యనఘ! పుణ్యకీర్తు లతిశయిల్ల.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","048","క.","మిత్ర నరపతుల శాత్రవ | ధాత్రీశుల నెమ్మిఁ బరుసఁ దనమున వశతా\nపాత్రములుగఁ జేయుదె? సుచ | రిత్ర! యుదాసీన నృప పరీక్ష నడచునే?","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","049","క.","దేవతల కతిథులకుఁ బితృ | దేవతలకుఁ బూజనములఁ దృప్తి యొనర్తే?\nయీ వసుధఁ జతుర్వర్ణ జ | నావళులు నిజోచితక్రియలఁ దగ మనునే?","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","050","తే.","బాలురకును దుర్బలులకు భామినులకు | వృద్ధులకును మనంబుల వెఱపు లేని\nయట్టి మెలఁకువ గలిగెడునట్లు గాఁగ | నడచునే యాజ్ఞ పురమునఁ బుడమియందు.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","051","క.","అనిన విని యా నృపతి య | జ్జనపతితో నిట్టు లనియె ‘జగదీశ్వర! నీ\nవినుతోపదేశమున భవ | దనుయుక్తము లెల్ల నడచు నవికలభంగిన్‌.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","052","వ.","అని పలికి యిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","053","క.","‘ఆయాసము సైరింపని | మీ యొడలు తపఃక్రియలకు మెయికొనియెనె? భూ\nనాయక! శుశ్రూష దగం | జేయునొకో గొంతి డప్పిఁ జెందక మీకున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","054","క.","మా పెద్దతల్లి యలజడి | కోపి తపోవృత్తి గడపుచున్నదియె? సుత\nవ్యాపాదనకారుల మముఁ | బాపాత్ములఁ దలఁచి యెట్లు పలుకునొ మీతోన్‌?","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","055","ఆ.","సంజయుండు తపము జాలికిఁ జాలి వ | ర్తిల్లుచున్నవాఁడె? ధీరచిత్తుఁ\nడిచట లేఁడు విదురుఁ డెచటి కేఁగినవాఁడొ? | యతనిఁ జూడ వలయు నధిప! నాకు.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","056","వ.","అనుటయు ధృతరాష్ట్రుఁడు ధర్మతనయుతోడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","","సీ.","‘ఏఁ దపంబున కోర్తు నెంతయు; శుశ్రూష | యలయక గొంతి మా కాచరించు;\nవినుము! గాంధారియు ననఘచరిత్ర త | పోనిష్ఠ కోర్చు; నిమ్మాననీయ\nమిముఁ దలంచిన యప్డు మెచ్చి దీవించు; సం | జయుఁడు ప్రాజ్ఞుఁడు; తపశ్చరణమునకు\nవిసువఁడు; మముఁ బాసి విదురుఁ డెచ్చట నేనిఁ | జరియించు మునిజనాశ్చర్యకారి","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","057","ఆ.","యగుచు; జలము లనిల మాహారముగఁ గొను; | నవియు నదియుఁ గొనక యయిన నుండు;\nశూన్య విపినమున విదైన్య స్వతంత్ర సం | చారియై వసించుఁ గౌరవేంద్ర!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","058","క.","ఒక్కొకమరి డబ్బాటీ | చక్కటిఁ గాన నగు ననియె జనవర తోఁచెన్‌\nగ్రక్కున నప్పుడ విదురుం | డక్కౌంతేయాగ్రజున కనతిదూరమునన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","పాండవులు కురుక్షేత్రంబున నున్న ధృతరాష్ట్ర గాంధారీ కుంతుల దర్శించుట (సం. 15-31-6)","059","వ.","కాంతారధూళి మలినాంగుండును జటీభూతకేశపాశుండును దిగంబరుండును నగు విదురుం డట్లు దోఁచి యయ్యాశ్రమంబున నున్న జనంబులం గని మగుడి పోవంజూచె; ధర్మతనయుండు తన యనుచరుల నిలువుం డనుచుఁదా నొక్కరుండును సత్వరంబుగా నవ్వినుత ప్రభావుని వెనుకం జనియె; నతండు గుల్మాంత రితుం డగుచుం దోఁచుచుఁ బోవం బోవ నప్పాండ వాగ్రజుం డెలుంగెత్తి ‘యో విదుర! నిలునిలు; మేను యుధిష్ఠిరుండ; నిన్నుఁ గాన వచ్చితి ‘నని పలుకుచుం బాఱిన నమ్మహాత్ముండు మరలి కనుంగొని వివిక్త ప్రదేశంబున నొక్క పాదపంబు చేరి నిలిచిన.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","","సీ.","ధర్మతనూజుండు తత్సమీపంబున | కేఁగి యయ్యోగి కట్టెదుర నిలిచి\nయాతండు నయనంబు లర్ధమీలితములై | యుండంగ నూరక యున్నఁ గాంచి\n‘నిర్మలాత్మక ! యేను ధర్మసూనుఁడ; నన్నుఁ | గనువిచ్చి చూడవే!’ యనుడు నతఁడు\nఱెప్పల నెగయించి యప్పాండవోత్తముఁ | దప్పక చూచి యుదాత్త యోగ","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","060","తే.","బలము గైకొని యింద్రియములను బ్రాణ | ములను నింద్రియములుఁ బ్రాణములను గలిపి\nనిజశరీరంబు విడిచి యా నృపతి తనువు | సొచ్చెఁ దేజోమయత్వవిస్ఫూర్తి మెఱయ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","061","ఆ.","వినుము ధర్మపుత్త్రు తనువునఁ గాంతియు | లావు నప్పు డగ్గలంబు లయ్యె,\nనొలసె బుద్ధి యధిక బల; మట్టు లగు టతఁ | డెఱిఁగి చోద్యమంది యెలమి నొందె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","062","క.","తదనంతరంబ యప్పతి | విదురశవము మ్రాను సెంది వికృతరహితమై\nనిదురమెయి నొఱగియున్న ప | గిది నుండం జూచి యగ్నికృత్యము నడపన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","063","చ.","తలఁచిన మింట నొక్కెలుఁగు ‘ధర్మతనూజ! యతిత్వ గౌరవో\nజ్జ్వలుని కళేబరంబునకు వహ్నివిధాన మొనర్చు టర్హమే?\nవల’దని మ్రోసె; నమ్మనుజవల్లభుఁ డప్పని దక్కి పోయి భ్రా\nతలకును దండ్రికిన్‌ సువిదితంబుగ నంతయునుం గ్రమంబునన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","064","వ.","ఎల్లవారును వినుచుండం జెప్పిన నందఱు నద్భుత రసంబున మునింగిరి; పదంపడి ధృతరాష్ట్రుం డామంత్రణంబు సేయ మునిజనులు నిజనివాసంబులకుం జనిరి; తదనంతరంబ యాంబికేయుండు ధర్మనందనుని తోడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","","సీ.","‘భరతకులోత్తమ! ఫలమూలముల నుప | యోగింపు మొసఁగెద నొదవి తనకు\nనెయ్యది యాహారమయ్యె నాతిథ్యంబు | దానిన నడపుట ధర్మసరణి’\nయనవుడు ‘నట్ల కా’ కని ఫలంబులు మూల | ములు నుపయోగించె మోదభరితుఁ\nడగుచు నప్పాండుసుతాగ్రణి యబ్భంగి | నఖిలజనములు నాహారకలన","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","065","తే.","మాచరించి రయ్యందఱు నవని శయన | మొంది యారాత్రి నిద్రించి రుదితసూర్య |\nకాలమగుటయు, సముచిత కర్మకరణ | మనుజులును దాను నడపె నమ్మనుజవిభుఁడు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","066","వ.","అట్లు కాలోచితకృత్యంబులు నడపి సహోదరసహితుండును దారోపేతుండును నర్హపరివారానుగతుండును నై యాశ్రమపథంబు గలయ మెలంగి, పావనస్నాన పావకార్చన జపధ్యానాది తాపసధర్మచర్యా విధంబులు, నానామృగ నిర్భయ సంచార ప్రకారంబులు వివిధపక్షికుల నిశ్శంక కేళీవిభవంబులు నాలోకించి, కృత ప్రాతస్సవనకరణీయుం డై యున్న కురువృద్ధు కడకు వచ్చి వందనాభినందన వచనంబుల నతని యుల్లంబు పల్లవింపంజేసి యతఁడు వనుపఁ బవిత్రాసనోపవిష్టుం డై.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","067","చ.","అనుజులుఁ దాను భక్తి మెయి నమ్మహనీయునిఁ గొల్చియుండ న\nయ్యునికిఁ గనుంగొనంగఁ గరముత్సుకతన్‌ శతయూపుఁ డాదిగా\nమునివరు లేఁగుదెంచినఁ బ్రమోదమునం గుశపీఠరాజిపై\nనునుపఁగఁ బంచె గాఢవినయోక్తుల నా ధృతరాష్ట్రుఁ డందఱన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","068","వ.","అట్లున్న యమ్మునిజనంబులును బాండు పుత్త్రులునుం బరమధర్మమయ సంభాషణంబులు సేయుచుండ నినుండు నభోమధ్యగతుం డయ్యె; నప్పు డాంబికేయుండు సవినయంబుగా నత్తాపసోత్తములతో ‘మీకు మధ్యందిన కృత్యంబు లాచరింపవలయు; విజయం చేయుం’డనిన వారలు నిజనివాసంబులకుం జనిరి; తదనంతరంబ కౌంతేయుల మాధ్యాహ్నిక కరణీయంబులు నిర్వర్తించుట కరుగుం డని పనిచె; నని చెప్పినవిని జనమేజయుం డప్పాండవేయు లవ్విధంబున వనంబున నెన్ని దినంబులు వసియించి?’ రని యడిగిన వైశం పాయనుం డిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","","సీ.","‘ధరణీశ! పాండునందను లట్లు సాంతఃపు | రంబును సపరివారంబుఁగాఁగ\nనడవికి నేఁగి యయ్యంబికానందనుఁ | గాంచిన దినమునఁ గరము నియతి\nఫలమూలసమితి నాఁకలి వుచ్చి భూమిశ | యనమున నిద్రించి రాగరిష్ఠుఁ\nడమ్మహితాత్ముల కర్థ్థితో మఱునాఁ | డనుజ్ఞ యిచ్చిన, సుమనోజ్ఞములును","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","069","ఆ.","సన్నుతములు నైన యన్నపానాదుల | ననుభవించి మృదులహారి తల్ప\nముల శయించి; రట్లు నెలనాళు లయ్యెడ | నతనిఁ గొల్చియుండి రధిపముఖ్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","విదురుఁడు యోగమార్గంబున ధర్మరాజునందుఁ గలియుట (సం. 15-33-22)","070","వ.","పదంపడి యొక్కనాఁ డెప్పటియట్ల పాండుపుత్త్రులు గాంధారీ కుంతీసముపాసితుండయియున్న విచిత్రవీర్యపుత్త్రుంబరివేష్టించియుండ నవ్విశిష్ట గోష్ఠికై శతయూపప్రభృతి మునివరులు చనుదెంచిన నక్కురువృద్ధుఁడర్హంబు లగునాసనంబులు వెట్టించి సంభావించిన.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","","సీ.","సముచితంబులు సధర్మములును నైన స | ల్లాపముల్‌ సెల్ల నుల్లంబు లలర\nవార లున్నెడ సత్యవతికొడు కందుల | కేతేర నందఱు నెదురువోయి\nవినతులై భక్తిఁ దోడ్కొనివచ్చి యతులకృ | ష్ణాజిన దర్భోత్తరాసనమున\nనునిచి యమ్మునివరుననుమతిఁ దమతమ | యాసనంబుల నుండి; రమ్మహాత్ము","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","071","ఆ.","నర్చితునిగఁ జేసె నాంబికేయుఁడు దద | నంతరంబ సమధికాదరమున\nనతఁడు మధుర మృదు విధాక్షరంబుగ నమ్మ | హీశముఖ్యుతోడ నిట్టు లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","","సీ.","‘వనవాసమున నీకు మన మలవడియెనే? | నియతిమైఁ దాపసక్రియల కోర్చి\nనడపెదవే పుత్త్రునాశజమైనశో | కము భవదంతరంగంబునందు\nలేదు గదా? ధర్మవేదిని గాంధారి | యుమ్మలికంబు లే కున్న యదియె?\nనీకుఁ బరిజ్ఞాననిష్ఠ గల్గెనె? గొంతి | శుశ్రూష మీ కొనర్చునె తగంగ?","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","072","తే.","రాజ్య మొల్లక వచ్చె నరణ్యవాస | మునకు నీయమ; మీరు రాఁ దనకు నింట\nనిలువఁ దగ దని యిమ్మేలు నీదు బుద్ధి | నొలసి యుండునె కౌరవకులపవిత్ర!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","073","చ.","అనఘ! యజాతశత్రునెడ నాదరణాతిశయాన్వితంబె నీ\nమనము? వృకోదరున్‌ నరుని మాద్రితనూజుల సత్క్రియాభినం\nదనముల గారవింతె? వినుతస్థితిఁ దద్దయు నిర్మలత్వ మొం\nదెనె భవదీయచిత్తమున ధీమహితా! దృఢశాంతిమూలమై.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","074","వ.","అని యంత నిలువక.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","075","ఆ.","‘వినుము! దీర్ఘవైర వృత్తియు’ ద్రోహచిం | తనము లేక వాక్కు మనము నొక్క\nచంద మగుట సకలజనములకును బంధు | సంపదాప్తి పరమసాధనంబు.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","076","వ.","అని చెప్పి వెండియు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","","సీ.","‘విదురుండు దేహంబు విడిచిన తెఱఁగెల్ల | నెఱిఁగితె? మాండవ్యుఁ డిచ్చినట్టి\nపటుశాపమున శూద్ర భావంబు నొందిన | ధర్మదేవత బోధనిర్మలాత్ముఁ\nడైన యమ్మహనీయుఁ డట్లగుటంబుజా | సనుని యాజ్ఞాపనమున విచిత్ర\nవీర్యనృపాధీన విశ్రుతక్షేత్రంబు | నం దేఁ బ్రవర్తింప నధిప! కలిగె","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","077","తే.","ధర్మదేవత మాఱట తనువు సూవె | యీ యుధిష్ఠిరు నుజ్జ్వలకాయ; మింత\nయెఱిఁగి కాదె యమ్మహిత యోగీశ్వరుఁడు స | మీడ్య యోగబలంబున నితనిఁ గలసె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","078","ఆ.","అట్లు దేవతామయాత్మకుఁ డైన యి | వ్విభుఁడు నిన్నుఁ బ్రేష్యవృత్తి నిట్లు\nగొలిచి యునికి బుద్ధిఁ దలపోసి సంతస | మంది యుండుదే కులాగ్రగణ్య!’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","079","వ.","అనిన విని వైచిత్రవీర్యుం డప్పారాశర్యునకుఁ బరమవినయంబున నిట్లనియె,","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","","సీ.","‘వనవాస మించుకయును నాకు దుఃఖంబు | సేయదు; దేహంబుఁ జిత్తమును ద\nపఃక్రియలకుఁ బనుపడి యున్నయవి నన్ను | గాంధారిఁ బుత్త్రశోకం బొకింత\nయేనియుఁ బొందంగ నీఁడు సభక్తిక | మైన వృత్తమున ధర్మాత్మజుండు\nమునివర! యితనిపై ననుజుల మీఁద వ | త్సలము నా హృదయ మిద్ధరణివిభుఁడు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","080","ఆ.","దేవతాత్ముఁ డగుట దెల్ల మై యునికి మ | ద్వచనవర్తనములవలన నితఁడ\nయెఱిఁగి యుండుఁ గొంతి తెఱఁగు శుశ్రూషయు | నద్భుతంబు ముదము నావహించు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","081","వ.","నాకుం బరిజ్ఞానంబును మానస నిర్మలత్వంబును భవత్‌ ప్రసాదంబునం గలిగెడుఁగాక’ యనియె; నా సమయంబున ద్రౌపదీసుభద్రలును దక్కునుంగల్గు నంగనాజనంబులును బారాశర్య సందర్శన ప్రవణత్వంబునం జనుదెంచి సభక్తి ప్రణామంబు లాచరించి యంతంత నిలిచి; రయ్యలఘుజ్ఞాన మాననీయుండు ధృతరాష్ట్రు తోడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","082","ఉ.","మీయెడ చింత వాయఁగ సమీహితబుద్ధి యొనర్పఁ గోరి యే\nనీ యెడ కిప్డు వచ్చితి నభీష్టము వేఁడుము శంక దక్కి భూ\nనాయక! యెల్లభంగిని మనః ప్రియముం దగ నిత్తు’ నన్నఁ గౌం\nతేయు లెలర్చి; రవ్వసుమతీపతి మోదము నొందె నెంతయున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","083","వ.","వ్యాసుండు వెండియు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","084","చ.","‘అనఘ! యమానుషం బయినయట్టిద యైనను నా తపంబుపెం\nపునకు మునీంద్రు లద్భుతముఁ బొందఁగ మీ కవలీల నిత్తు నే’\nననుటయు నా కురుక్షితిపుఁ డాదటఁ గోరఁగ మీర లిందు వ\nచ్చిన కరుణామయాదర విశేషముకంటెను మేలు గల్గునే?","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","085","క.","మానుష మైన నమానుష | మైనను బ్రార్థనకు విషయమైనది భవదీ\nయానూనకృపకు నెక్కుడు | గా నొక్కఁడుఁ గాన నేను గారుణ్యనిధీ!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","086","ఆ.","సంయమీంద్ర! నాదుజన్మంబు సఫలతఁ | బొందె మీరు విమలబుద్ధి నింత\nయాదరించినపుడ; లే దింకఁ బరలోక | భీతి ధన్యతముఁడ నైతి నేను.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","087","వ.","అట్లయినను మీ రొక్కటి గోరు మనిన నామనంబున నెప్పుడుం గలయది యెఱింగింపవలసె; విన్నవించెద.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","","సీ.","దుష్టచిత్తుం డగు దుర్యోధనుండు ని | ష్పాపస్వభావులఁ బాండుసుతులఁ\nబరిభవించి సమస్తనరనాథు లనిఁ గరి | తురగయుతంబుగాఁ ద్రుంగఁజేసి\nధరణి రాజ్యముఁ గోరి గురుభీష్మకర్ణాది | సత్పురుషుల నెల్లఁ జంపికొనియె;\nనన్నీచునకుఁగా ‘మహారాజు లాండ్రను | బిడ్డల విడిచి యభేద్య ధైర్య,","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","088","తే.","వృత్తి రణమృతిఁ బొంది; రవ్విభుల కేది | గతియొ? యిమ్మెయి మూఢులై కలనఁ బడిన\nకురుకుమారకు లెట్లైరొ పరమబోధ | మహిత! యెఱుఁగని వగ పెద్ద మాన్పు మనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","089","వ.","అనుటయు నప్ప్రేముడి పలుకులు విని గాంధారికిం గుంతికిం బాంచాలికి సుభద్రకు మఱియునుం గలయంగనలకుం జిత్తంబుల నెవ్వగలు గ్రొత్తలయ్యె; నప్పు డాసుబలనందన పట్టావృతలోచనత్వంబునన చూచి దయాధామం బై యున్న యా మామ నుద్దేశించి మోడ్చిన చేతు లద్దెసకు నిగిడ్చి యిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","","సీ.","‘మునినాథ యీ రాజు తనయు లందఱును గ | య్యంబునఁ దెగినదియాదిగాఁ బ\nదాఱేండ్లు వగలపా లగుచుఁ దత్సన్నిధి | గల్గుటఁ గోరు;లోకంబు లెన్ని\nయన్నియుఁ జూపంగనైనను జాలుదు | నిర్మలతపమున పేర్మి నీవు\nపుత్త్రసాన్నిధ్య మీ భూపతి కొనరించు | టెంతటిపని? నీకు గొంతి ద్రుపద","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","090","తే.","రాజపుత్రి సుభద్ర కౌరవ కుమార | శతము భార్యలు నూర్వురు సౌమదత్తి\nపత్ని, యత్తన్వియత్త యప్పడఁతి యత్త | గోరుదురు యుద్ధమృతబంధుకోటిఁ జూడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","091","వ.","అంతయును భవదీయ దివ్యబోధంబు గనుచుండు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","092","క.","పరమమునీంద్ర! సమరమృత | కురువీరుల మా మనముల గో డుడుగ భవ\nత్కరుణ వెలయ లోకం బ | చ్చెరువందఁగఁ జూపవే విచిత్రపుమహిమన్‌’.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","093","చ.","అనునెడ గొంతి వాడువదనాబ్జముతోడ మదిం దలంచెఁ గ\nర్ణుని; నది యత్తపోధనవరుం డెదఁ గాంచి దయానురక్తి న\nవ్వనిత గుఱించి యిట్లను ‘భవన్మతి నొందిన కోర్కి సెప్పు మే\nననఘచరిత్ర! దాని ఫల మందఁగఁజేసి యలంతఁ బాపెదన్‌’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వేదవ్యాసుఁడు పాండవసహితుండైన ధృతరాష్ట్రునాశ్రమంబునకు వచ్చుట (సం. 15-34-21)","094","వ.","అనిన విని యయ్యింతి సంతసిల్లి యా సంయమివల్లభునకు దండప్రణామంబు చేసి చేతులు మోడ్చి లజ్జా సహితం బగు నంతరంగంబుతో వినయనమ్ర యగుచు నిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","","సీ.","‘దేవతలకు నీవ దేవత; విట్టి ని | న్మామగాఁ బడసితి మహితకరుణ\nననుఁ జూచి నాదువిన్నప మాదరింపు మేఁ | గన్యాత్వదశ నుండఁగా మదీయ\nజనకుని కడకుఁ గోపనుఁ డైన దుర్వాసుఁ | డన్మహాముని వచ్చె; నతని సవిన\nయార్చన కలనాసమారాధితుండుగాఁ | జేసితిఁ బ్రీతుఁడై ‘చెలువ! నీకు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","095","ఆ.","నిత్తు వరము; వేఁడు మెయ్యది కోరికి?’ | యనియె; నతఁడు ‘మీ ప్రియంబుకంటె\nననఘ! మిగులు కోర్కియును గలదే? నాకు | నంటిఁ; గాని యొకఁడు నడుగ నైతి.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","096","వ.","అమ్మాట తనమనంబునకు రానిచందంబు మొగంబునం దోఁప నత్తాపసవరుండు ‘వరం బెల్లభంగి నొసంగక పోవ; నడుగు’ మనుటయు, వెఱచియు నాదువేడ్కతెఱం గట్ల యగుటను ‘బుత్త్రుంగోరితిఁ గోరిన నమ్ముని పతి యొక్క మంత్రం బనుగ్రహించి ‘దీన నీ వావహించిన దేవతలు భవద్వశగతులై సుతజన్మంబు గలిగింతురు; విశేషించి ధర్మువునకుఁ దల్లివి గాఁగలదాన’ వని పలికి యంతర్ధానంబు చేసిన.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","097","ఆ.","అద్భుతమునఁ బొంది యమ్మంత్రరూప ము | ల్లమున నెప్పుడును దలంతు; నొక్క\nనాఁడు మేడమీఁదఁ బోఁడిమి నే నుండి | కంటిఁ బొడుచుచున్న కమలమిత్త్రు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","098","క.","కని యిది కన్యకు దోషం | బని తలఁపక బాల్యసంభృతాజ్ఞానము వే\nడ్క నొనర్ప నావహించితి | ముని మంత్ర బలమున సూర్యు మునినాథవరా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","099","తే.","ఆవహించిన నద్దేవుఁ డాకసమున | నాత్మమూర్తి వర్తింప మూర్త్యంతరంబు\nదాల్చి నాకడ కేతెంచెఁ దత్‌క్షణంబ | నాదుచిత్త మాశ్చర్యమగ్నంబు గాఁగ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","100","వ.","ఇట్లు చనుదెంచి.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","","సీ.","‘అడుగు మిచ్చెద వరం’ బనిన వడంకుచుఁ | గేలు మొగిడ్చి ‘పొం డేల యిచట’\nననిన ‘వృథాహ్వాన మాచరించుట తప్పు | నిన్నును నెవ్వఁడు నీకు మంత్ర\nమిచ్చె నాతని శపియింతుఁ జుమ్మీ!’యని | పలికె నయ్యర్కుఁ; డే నలికి గురుని\nనిరపరాధుని శాపనిహతుఁగాఁ జేయుట | కోర్వక పుత్త్రకు నొసఁగు దేవ","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","101","తే.","కృప భవత్సము’ ననిన నయ్యపరిమేయ | తేజుఁ డాత్మతేజమున నా దృఙఙఙ్ముఙఖేంద్రి\nయములు మనసును సమ్మోహితములు సేసి | యపుడు తనయుండు పుట్టెడు’ ననియెఁ బిదప.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","102","వ.","అని నిర్దేశించి.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","103","తే.","‘నీకుఁ గన్యాత్వ వికలత గాక యుండ | వరము నిచ్చితి’ ననుచు దివమున కరిగె;\nజనకముఖబంధుచిత్తవంచనము నడపి | గూఢ మందిరాంతరమునఁ గొడుకుఁ గంటి.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","104","క.","కని యేటిలో నిడితిఁ గలఁ | గని నట్లయి యుండెఁ దత్ప్రకారం; బిది మీ\nకనినయది దివ్య బోధంబున నత్తెఱఁ గంతరంగమునఁ గొని కాలున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","105","తే.","పాప మయ్యెఁ గా కుండె నప్పనిఁ దలంచి | యళుకుచుండుదు; మద్భయ మపనయింపుఁ\nడతులకరుణ నిక్కురువృద్ధునభిమతమును | సఫలముగఁ జేయుఁ డివి నాకు సద్వరములు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","106","వ.","అనిన విని యమ్మునీంద్రుం డమ్మానిని కిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","","సీ.","‘నీ చెప్పినది యెల్ల నిక్కంబు కోడల! | యెగ్గు నీ యందు లే; దేల వెఱవ?\nసుర లద్భుతాపాదిచరితులు; కర్ణున | కట్లుగా నున్నది యగుటఁ జేసి\nయేటిలో నాతని నిడి తీవు; కన్యాత్వ | హాని లే కున్కిఁ గులాగ్రగణ్య\nవైతి; భవద్వృత్త మమలిన మగుటకు | ననుమాన మించుక యైన వలవ’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","107","ఆ.","దనుచు నాదరార్ద్రుఁడయి పల్కి గాంధారి | తోడ ‘నీవు సుతులఁ దోడఁబుట్టు\nవులను గాంతు, నీదు చెలియలు గొంతియుఁ | గర్ణుఁ జూడఁ గాంచు గణ్యచరిత!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","108","ఉ.","ద్రౌపదియున్‌ సుభద్రయును దక్కటి కాంతలు భ్రాతృపుత్త్ర పౌ\nత్త్రోపవిలోక నోత్సవము నొందుదు రిచ్చటి కిప్డు వచ్చు టే\nనీ పని యాచరించుటకు; నిమ్మనుజేంద్రుఁడు నీవు గొంతి చిం\nతాపరితాపనోదన విధంబుగఁ గోరితి రట్లు చేసెదన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","109","క.","నీ కొడుకులకు మనుమలకు | శోకింపఁగ వలదు; వారు శూరత వెలయం\nజే కొనిరి రణమరణమున | నాక భువనసుఖము సద్గుణస్తవనీయా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","110","ఆ.","భామ! విను మవశ్య భవితవ్య మైన భా | రతరణంబు పొంటె నతుల మహిమ\nమాననీయ దేవయోనులు జననంబు | నొంది రిందు మనుజయోనులందు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","","సీ.","ధృతరాష్ట్రుఁ డనఁగ వర్తిల్లెడు మేటి గం | ధర్వుఁడీ ధృతరాష్ట్రధరణివిభుఁడు\nతన్వి! పాండుఁడు మరుద్గణ మయజని; ధర్మ | దేవత సూవె యుధిష్ఠిరుండు;\nపవనుండు భీముఁడై ప్రభవించె; నరుఁ డను | ముని యర్జునుం డయి జనన మొందె.\nనారాయణుఁడు గృష్ణనాముఁడై జనియించెఁ; | గనుఁగొను కవల నాశ్వినులు గాఁగ;","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","111","తే.","ద్వాపరంబుగ నెఱుఁగు గాంధార రాజు; | గలి సుయోధనుఁ డయ్యె; రాక్షసులు పుట్టి\nరతని యనుజులై; కర్ణుని నరుణకిరణుఁ | గాఁగ; నభిమన్యుఁ జంద్రునిఁ గాఁగఁ గనుము.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","112","క.","అనలుఁడు ధృష్టద్యుమ్నుం | డన ద్రౌపదితోడఁబుట్టె; ననిలుని యంశం\nబున జనియించె శిఖండియు; | ననిమిషగురుఁ డుద్భవించె నస్త్రగురుండై.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","113","తే.","వినుము వసుశక్తి గాంగేయుఁ డనఁగ జనన | మొందె; రుద్రాంశమున ద్రౌణి యుదయ మయ్యెఁ\nదెలియఁ జెప్పితిఁ గొందఱు కలరు మఱియు | నిర్జరాసురాంశముల జన్మించినారు.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","114","క.","అని పలికి ‘మీ మనంబుల | వనట సమస్తంబుఁ బుచ్చి వైచెద నాతోఁ\nజనుదెండు మీరు గంగకుఁ గనియెద రనిఁ దెగిన బంధుగణముల నచటన్‌.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","115","తే.","అనుచు నుత్థితుఁ డగుటయు నార్పుటెలుఁగు | లాకసం బంద ధృతరాష్ట్రుఁ డాది గాఁగఁ\nగలుగు నా సర్వజనులు నొక్కటఁ గడంగి | యరిగి రమ్మునినాథుతోఁ గురువరేణ్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","116","క.","అరుగఁగ మునిజనములు న | చ్చెరు వందుచు నమ్మునీంద్రు సేవించి మరు\nత్సరిదుపకంఠ తలమునకు | నరిగిరి కౌతుకము మనములందు నెలకొనన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","కుంతి వేదవ్యాసునితోఁ గర్ణుఁడు దనకు జన్మించిన తెఱంగెఱింగించుట (సం. 15-38-1)","117","వ.","అట్లు పౌరజానపదసహితు లై సకలజనంబులుం జని సాత్యవతేయుండు వనుప భాగీరథీతీరంబున విడిసి; ర వ్విచిత్రచరిత్రుండు దన చేయంబూనిన పని మఱునాఁడు రేపకడ సేయువాఁడుగాఁ బలికిన నయ్యందఱు నద్దినశేషంబు నా యామినియును శతసంవత్సరంబులుంబోలె నుండ సూర్యోదయసమయం బగుటయుఁ గాలోచితకృత్యంబు లాచరించి ధృతరాష్ట్రుుండును బాండుతనయులుం దపోధనులు నప్పారాశర్యుపాలికి నరిగి యమ్మునివరుం బరివేష్టించిరి; గాంధారీప్రముఖభామినులు నేతెంచి యొక్కవలన నతనిం గొలిచి యుండిరి; సర్వజనులు నఱ్ఱు లెత్తికొని యంతంత నిలిచిరి; తదనంతరంబ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","","సీ.","సాత్యవతేయుండు జాహ్నవీసలిలావ | గాహన మొనరించి గారవమున\nనింపారు నెలుఁగున ‘నిందు రం’ డనవుడు | నీ కేమి సెప్పుదు? నీటియందు\nరవ మగ్గలముగ రారాజుఁ దమ్ములుఁ దత్కు | మారవర్గము నభిమన్యుఁ డాది\nయగు పాండుపౌత్త్రులు నర్కజుండును బాహ్లి | కప్రముఖాఖిల కౌరవులును","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","118","తే.","ద్రుపదమాత్స్యులు వారి బంధులును శకుని | యును దదీయానుజులును నాతని తనూజ\nరాజియును భీష్మగురులఁ బురస్కరించి | కొనుచుఁ దమదివ్యదేహముల్‌ కొమరు మిగుల.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","119","ఆ.","దివ్య మాల్యములును దివ్యాంబరంబులు | దివ్య భూషణములు దివ్యలేప\nనములుఁ జెన్నుఁ జేయఁ దమ మిత్త్ర సుభటసం | దోహములును దారుఁ దోఁచి రధిప!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","120","వ.","అట్టియెడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","121","క.","తగ నా కురువృద్ధునకు నొ | సఁగె నాఁటికి నెల్లదృష్టి సాత్యవతేయుం\nడగణితతపఃప్రభావం | బు గని యధిక విస్మయంబుఁ బొందఁగ జనముల్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","122","వ.","అవ్విశేషంబు విని యద్భుత ప్రమద భరితయై నిజనయనంబుల బంధించిన పట్టం బపనయించి గాంధారి యును గనుంగొనుచుండ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","123","క.","అవ్విధమునఁ దోఁచిన మఱి | నవ్వుచుఁ దెగడుచును బెరసి నరవర! పగ లే\nకవ్వీరవరులు నెయ్యము | నివ్వటిలఁగ విలసనములు నెఱయ మెఱయఁగన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","124","తే.","చతురగంధర్వు లప్సరోజనులు గాన | ములఁ బ్రమోద మొనర్పంగఁ బొగడ వంది\nసమితి నిరహంకృతులు హృదయముల గౌర | వములు తెల్లంబు సేయంగ వచ్చి రొప్పి.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","125","వ.","ఇట్లు వచ్చి సకలబంధుజనంబులకుం బరమప్రమోదం బావహిల్లం గలిపి సముచితాచారంబులు నడపి; రా రెండు దెఱంగులవారలు నర్హ ప్రకారంబులఁ బితామహాచార్య శిష్య మాతృ మాతామహ పితృపితామహ భ్రాతృ జామాతృ పుత్త్రపుత్త్రీభగినీ పౌత్త్ర దౌహిత్ర శ్వశుర శ్వశ్రూస్నుషా మాతుల స్యాలక ప్రియ ప్రియా మిత్ర సమాగమసుఖంబు లనుభవించుచు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","126","తే.","అనఁగి పెనఁగి నాఁడెల్ల నిచ్ఛానురూప | వృత్తి వర్తిల్లుచుండి; రవ్విధము సకల\nజనుల నద్భుతరసమున మునుఁగఁ జేసె; | నే మనఁగ వచ్చు నా సంయమీంద్రు మహిమ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","127","వ.","మఱునాఁడు రేపకడ యప్పారాశర్యుండు ననుప నయ్యిరు దెఱంగులవారలుం బరస్పరామంత్రణంబు సేసి; రాశూరజనంబులు తమతమలోకంబులకుం జనువారై జాహ్నవీజలంబులం బ్రవేశింప, నన్నిలింపవందనీ యుండు దానును జొచ్చి యచ్చటినుండి ‘పతుల ననుగమింప వలసిన యంగనలు గంగాతోయంబులంగ్రుం కుటకు రం ‘డనిన విని విధవలగు వీరభార్య లెల్లను ధృతరాష్ట్ర గాంధారీ కుంతీ ధర్మనందనుల యనుజ్ఞల గొని రయంబునం జని భాగీరథీ సలిలమగ్నలై మానుష దేహంబులు విడిచి దేవతనువులు దాల్చి దివ్యాలంకార సమలంకృతమూర్తులై మగలం గలసి; రవ్విశేషంబు చూచి సర్వజనులు నత్యంతాశ్చర్యసంతోషాధీన మానసులై రని చెప్పి వైశంపాయనుండు జనమేజయున కిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","","సీ.","‘జననాథ! యీ ప్రియసంగమోత్సవ కథ | వినినఁ బఠించిన వేవిధములఁ\nబరమప్రియము లిందుఁ బరలోకమున సంభ | వించు మనమ్మున కించు భంగి\nబాంధవయోగశోభనము వర్తిల్లు; న | నాయాసమున నామయాపగమము\nగలుగు; భూదేవనికాయంబునకు దీనిఁ | దగ వినిపించిన ధార్మికులకు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","128","తే.","నవ్యయానంద సంప్రాప్తి యావహిల్లుఁ; | దత్పరతఁ గొనియాడిన దైవతములు\nనీచదశఁ బొందకుండంగఁ గాచి తిరిగి | మే లొనర్తురు భరతభూపాలవర్య!’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","వ్యాసుఁడు ధృతరాష్ట్రాదులకు భారతరణ మృతుల రావించి చూపుట (సం. 15-40-4)","129","వ.","అనిన విని జనమేజయుండు వైశంపాయనుతో ‘ధృతరాష్ట్రుం డట్లు కృష్ణద్వైపాయన ప్రసాదలబ్ధం బైన తత్కాల కలితదృష్టి విశేషంబున బంధులోకంబు నాలోకించి మఱియేమి వర్తనంబున నుండెఁ? బాండవు లెట్లు వర్తించి? రెఱింగింపవే’ యనుటయు నతనికి నతం డిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","","సీ.","అ య్యద్భుతపువృత్త మమ్మెయిఁ జెల్లిన | ధృతరాష్ట్రమేదినీపతి తపస్వి\nగణము సవినయంబుగా నిజస్థానయా | నమునకు నామంత్రితముగఁ జేసి\nయాశ్రమభూమికి నరిగెఁ దోడన పాండు | రాజనందనులును రా నుదాత్త\nతేజు సత్యవతీ తనూజు మున్నిడికొని | యప్పు డమ్మునిపతి యతనితోడ","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","130","తే.","‘నీవు వేదశా స్త్రార్థముల్‌ భావితాత్ము | లగు మునీంద్రులచేఁ జెవులార వింటి,\nకంటి తనయుల నీ కన్న కంటె నొప్పి | యుండుదురు వారు దివిసౌఖ్యయోగ మెసఁగ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","131","ఉ.","కావున నింక వారికయి కౌరవసత్తమ! యుమ్మలింప కా\nత్మావిల భావముం దపము నగ్గలికం బెడఁబాపు నిన్ను సం\nభావనఁ గొల్చి యొక్కనెల పాండవముఖ్యుఁడు నిల్చె నిష్ఠమై\nనీ వనభూమి; నీ వసుమతీశ్వరుఁ బొమ్మనఁ గాదె వీటికిన్‌?’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","132","వ.","అని చెప్పిన నప్పౌరవోత్తముం ‘డట్ల చేసెద’ నని పలికి యమ్మునిసత్తమునకుం బ్రణమిల్లి ‘భవదీయకృపా విశేషం బునం గృతార్థుండనైతి’ నని యతని నామంత్రితుం జేసినం, బాండవులుం దగ నప్పరమముని వీడ్కొని; రయ్యం దఱను దీవించి యమ్మహాత్ముం డంతర్హితుం డయ్యెఁ; దదనంతరంబ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","","సీ.","ఆంబికేయుండు ధర్మాత్మజుఁ జిత్తసం | ప్రీతి మోమునఁ దోఁపఁ బేరఁ బిలిచి\n‘వసుమతీకార్య నిర్వహణంబు పెద్దకొ | ల్వున నుండి నీ వనుదినము నడప\nకునికి కర్తవ్యమే? వినుకులు భీష్మాది | మహితులచేత సమగ్రభావ\nమొందినయవి యింక నుపదేశ మేమియు | వలవదు; రంధ్ర మొవ్వని జనంబు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","133","తే.","వేచు; ననుజానుగతుఁడవై వేగపొమ్ము | దారయుతముగఁ బురికి నుదారచరిత!\nనీ కతమ్మున మున్న నా శోక మెల్లఁ | బాసెఁ, దేజంబు సౌఖ్యానుభవముఁ గంటి.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","134","చ.","‘తపమునెడన్‌ మదీయమతి తత్పర గావున దాని కోర్తు నీ\nవపగతఖేదమానసుఁడ వై నను నిం దతినిష్ఠ నొందఁ బం\nచి పురజనంబు సమ్మదముఁ జెందఁగ సైనికు లుల్లసిల్లఁగా\nనృపవర! యేఁగి రాజ్య భరనిర్వహణం బొనరింపు’, నావుడున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","","సీ.","ధర్మతనూజుఁ డాతని తోడ నిట్లను | ‘నధిప! భీమాదుల నరుగఁ బనుపు\nపుడమి రక్షింప; నీ యడుగులకడ నేను | నిలిచి మా తల్లుల నిన్నుఁ గొలిచి\nయంచితతపమున కనుగుణం బైనట్టి | శుశ్రూషణము సేయుచును దపోని\nయతితోడ నుండెద; ననవుడు గాంధారి | యి ట్లనఁ దగు ‘నన్న ‘యీవ కావె","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","135","తే.","కురుకులమునకు సంరక్షకుఁడవు; నీవు | తండ్రులకుఁ బిండ మొసఁగఁ గర్తవు; భవజ్జ\nనకునిపంపు చేయుము; భూజనము దలంక | కుండఁ బొ; మ్మది ప్రియము మా యుల్లములకు.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","136","వ.","అని పలికిన, నప్పాండవాగ్రజుండు పాండురాజాగ్రమహిషితో నిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","137","ఆ.","‘ఇట్లు మీరు నన్ను నెంతయుఁ దఱిమిన | విపినభూమి మిమ్ము విడిచి పోవ\nనియ్యకొనదు నాదుహృదయంబు; మునువోలెఁ | గలుగ దిపుడు రాజ్యకాంక్ష నాకు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","138","క.","విను పాంచాలురు మాత్స్యులు | వనితా జనశేషులైరి; వారలు లేమిన్‌\nజననీ! శూన్యంబై తోఁ | చినయది రాజ్యంబు నాదు చిత్తంబునకున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","139","వ.","అట్లుంగాక.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","140","క.","సమరము దీఱినకోలెను | శమనిరతా! నా మనంబు సారతపమునన్‌\nరమియింపఁ గోరు యుష్మ | త్సమధిక తపమునకు నేను సందడి సేయన్‌.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","","సీ.","అన విని సహదేవుఁ డతనితో ‘నేఁ దప | మాచరించెద; వీర లందఱకును\nశుశ్రూష సేయు చియ్యాశ్రమంబున’ నన్న | నక్కుమారునిఁ గుంతి యక్కుఁ జేర్చి\n‘వలవదు మీరు రా వలఁతులై మామీఁది | భక్తి నింపెసఁగ నీ పలుకు నెట్లు\nపలుక మీ యునికి తపమునకు విఘ్నంబ | కాక యెఱిఁగి మీర లెల్లభంగి","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","141","ఆ.","మాకు నియమవిధి సమాచరణములపై? | నింత యెఱిఁగి మీర లెల్లభంగి\nనరుగు టొప్పుఁ గాని కురుకులోద్వహు మాట | గొనక యునికి చనదు తనయులార!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","142","వ.","‘మీకు సర్వకార్యంబుల యెడను శుభంబులయ్యెడును; బోయి రం’ డనిన నజాతశత్రుండు మఱియొండు వలుకం బుయిలోడి ధృతరాష్ట్రునితోడం’ దపోమహనీయులైన మిమ్ముం గొలిచి గత కల్మషుండ నైతి మీ యాజ్ఞాపనంబు దలనిడికొని పురంబునకుం బోయి వచ్చెద’ ననుటయు నక్కురువృద్ధుం డతని దీవించుచు నాలింగనంబు చేసి, భీమసేను సాంత్వన వచనంబులం బ్రీతుం గావించి కౌఁగిలించుకొని, గాండీవిం గొనియాడి సంశ్లేషం బాచరించి, కవల సంభావించి పరిరంభణంబు నిర్వర్తించిన, నయ్యేవురు నతని పాదంబులకుఁ బ్రణమిల్లి యాశీర్వాదంబులు వడసి.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","","సీ.","అతిభక్తి గాంధారి యడుగుల కెఱఁగిన | నద్దేవి వారల నక్కుఁ జేర్చి\nదీవించె; వారుఁ గుంతీ చరణంబులు | ఫాలముల్‌ వొందంగఁ బ్రణతు లైనఁ\nదప్పక గ్రుచ్చి యందఱ నొక్క కౌఁగిటఁ | బొదివి యాశీర్వాదములు గ్రమమున\nనర్మిలిపెంపున నలరుమనంబుతో | వేర్వేఱ యిచ్చె నా వీరజనని","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","143","తే.","ద్రుపద పుత్త్రికా ప్రభృతి వధూజనములు | తగు తెఱంగుల మామ నత్తలను వీడు\nకొనిరి వారును వారు నగ్గురు జనముల | నల్ల వలగొని చనిరి నృపాగ్రగణ్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","144","క.","చని పరిజనములుఁబౌరులు | ననుమోదము తోడఁ గొలువ నరిగిరి నగరం\nబునకున్‌ గన్నుల పండువు | జనపదముజనం బొనర్ప జనసంస్తుత్యా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధృతరాష్ట్రుఁడు భాగీరథీ తీరంబుననుండి నిజాశ్రమంబు ప్రవేశించుట (సం. 15-44-2)","145","వ.","అరిగి సముచిత వర్తనంబుల నుండిరి; కొంతకాలంబు చనిన నొక్కనాఁడు నారదమునీంద్రుం డనుజనహితుం డై యున్న ధర్మతనయుకడకుఁ జనుదెంచిన, నజ్జననాథుండు దమ్ములుం దానును నమ్మహాత్మునకు భక్తిం బ్రణమిల్లి యాసనార్ఘ్య పాద్యాదిసత్కారంబు లొనర్చి తదీయ సమీపంబున నాసీనులై; రతని వదనంబు విలోకించి వినయం బెసంగ నమ్మహీపతి ‘మహా భాగ! యెందుండి రాక! యేదేశంబులఁ జరించితిరి? నేను మీకు నేమిపని సేయుదుఁ జెప్పుం ‘డనిన నప్పరమసంయమి యప్పుడమిఱేనితోడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","","సీ.","‘భూపవరేణ్య! తపోవనంబుననుండి | వచ్చితిఁ దీర్ధసేవా పరత్వ\nమున నేను బహుదేశములఁ జరించితి; నినుఁ | గని పెద్దకాలంబు గానఁ జూడఁ\nదివిరి యిందులకు నేతెంచితి; ధృతరాష్ట్రు | చరితంబు జాహ్నవీపరిసరంబు\nజనములచే వింటి’ ననిన నజ్జనపతి | ‘యా రాజవరుఁడు గాంధారి గొంతి","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","146","తే.","సంజయుండు సమాధాన సహితులై శ | రీరముల వింత పుట్టకున్నారె?’ యనియె;\nననుడు నద్దేవముని ‘వారి యఖిల వర్త | నంబు వినుము సుస్థిర హృదయంబుతోడ.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","147","వ.","అని పలికి యిట్లను ‘మీరు పోయి కాంతారంబున నక్కురువృద్ధుం గొలిచియుండి, యతం డనుమతి సేయ నిట వచ్చితిరి; మఱి కొన్ని దినంబులకు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","","సీ.","ఆ రాజు నియతి గాంధారియు గొంతియు | సంజయుండును దోన చనఁగ నగ్ని\nహోత్రంబు గొని యాజకోత్కరం బగ్రేస | రంబయి పో నిజాశ్రమము విడిచి\nయరిగె గంగాద్వార పరిసరారణ్య భా | గమునకు; నందు దుష్కరతపంబు\nవాయుభక్షతఁ బూని చేయఁ దొడంగె; గాం | ధారియు నీళ్ళ నాహారకలన","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","148","తే.","మోపి యొనరించె; గొంతి మాసోపవాస | నియమ మూఁది వర్తించె; సంజయుఁడు సప్త\nభోజనాంతరితం బగు భోజనంబు | వ్రతము గాఁగఁ జరించెఁ గౌరవ్యముఖ్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","149","తే.","యాజకులు దార యక్కురురాజు భక్తి | యుక్తి నొద్దనుండఁగ నగ్నిహోత్ర హోమ\nమాచరింతు రొక్కొకమరి యతఁడు పర్ణ | శాల వెడలి శూన్యాటవి సంచరించు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","150","వ.","విషమ ప్రదేశంబుల నవ్విభునకు సంజయుండును | గాంధారికిఁ గుంతియుఁ గన్నై మెలంగుదు; రొక్కనాఁడు వారలందఱు గంగాద్వారంబునం గృతస్నానులై యాశ్రమంబునకు వచ్చుచుండ మహావాతోద్ధూతంబై.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","","సీ.","పటుతరం బగు ఛటచ్ఛటరవ మెసఁగంగ | మ్రాఁకులుఁ బొదలును గాఁచికొనుచుఁ\nగమరును నార్తనాదంబును బెల్లుగ | నఖిలమృగంబుల నాఁచికొనుచు\nలాఁగలఁ బుట్టల లోఁగిన శిఖల భు | జంగమ కులముల మ్రింగికొనుచు\nవెగడొంది యఱచుచు నెగయు బల్పులుఁ గులఁ | బొగ నూర్థ్వకీలలఁ బొదివి కొనుచు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","151","తే.","దెసల నన్నిటఁ దన సముదీర్ణగతులు | దారుణ స్ఫురణమున విస్తార మొంద\nఖేచరులకును భయముగ నేచి పరఁగె | నద్భుతోద్భవం బైన మహానలంబు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","152","వ.","ఇట్లెరగలి చిచ్చు గవిసి చుట్టు ముట్టిన నమ్మనుజనాథుండును నన్నాతులు నిరాహారులై యునికిం జేసి యొక్క చోటఁ దఱియ నుఱికి తొలంగిపోవ లావులేరై; రట్టియెడ నా రాజర్షిసత్తముండు సంజయుతోడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","","సీ.","‘ఒక్కింత దెఱపి నీ వెక్కడ నైనను | గనుఁగొని పా మ్మగ్ని దనుకకుండ’\nనని చెప్పి తలఁగిపోఁ దనకు గాంధారికిఁ | గుంతిభోజాత్మజకును నశక్య\nమగుటయుఁ జెప్పిన నడలొంది యా సూత | సుతుఁడు ‘మీరును నొకచోట వెడలి\nపోవుట గలిగినఁ బోదు గా కే దవా | గ్నికి మిమ్ము నెర చేసి యకట పోదు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","153","ఆ.","నే మహాత్మయనుడు ‘నిలువాసి యిట్లున్న | జనుల కివ్విధమున సమయు టెగ్గు\nగాదు; నీకుఁ బోవఁగా వచ్చి యుండంగఁ | బోవ కునికి పాపమునకుఁ బట్టు.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","154","వ.","అని పలికి యతనిం బోవ నొడంబఱిచి యప్పౌరవ సత్తముండు సమాహితచిత్తుండై ప్రాఙ్ముఖాసీనుం డయ్యె; గాంధారియుం గుంతియు నవ్విధంబునం గూర్చుండి; రప్పుడు సంజయుండు ధృతరాష్ట్రుతో ‘యోగయుక్తుం డవు గ’ మ్మనియె; నతండు నట్లు సేసెఁ; దదనంతరంబ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","155","ఆ.","ఒక్కతెఱపి సంజయుఁడు సని హిమశైల | మెక్కె;నంత వారి నెల్ల నగ్ని\nవొదివికొనియె; నిట్లు వోయి రమ్మువ్వురుఁ | బుణ్యలోకమునకు భూపవర్య!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","","సీ.","పదపడి నృప! యేను భాగీరథీతీర | మున వచ్చుచుండి యవ్వనము దివ్య\nమునులచే మీ రటు సని క్రమ్మఱంగ వ | చ్చినది యాదిగ నయ్యశేష వృత్త\nమును నేర్పడఁగ వింటి, మూఁడు కళేబర | ములుఁ గంటి; నక్కురుపుంగవుండు\nభార్యయుఁ బాండుని పత్నియు సద్గతి | నొందిరి; నీ వింక నుమ్మలింప","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","156","ఆ.","కుండు’ మనిన శోక మొదవి యాతఁడు బాహు | లెత్తి యెలుఁగు సెలఁగ నేడ్వఁ దమ్ము\nలడలు గదిరి యేడ్చి; రవ్వార్త నంతఃపు | రమున రోదనార్తరవము లెసఁగ!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","157","వ.","అవ్విశేషంబు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","158","క.","విని పౌరజనసమూహము | లనయంబును వనట మునిఁగి హాహారవముల్‌\nవినువీథి ముట్ట రోదన | మొనరిచె నవ్వేళఁ గరుణ ముత్కట మయ్యెన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","నారదుఁడు పాండవులకు ధృతరాష్ట్రాదుల నిర్యాణంబు చెప్పుట. (సం. 15-45-1)","159","క.","నారదుఁ డుపశమ ఫణితులఁ | గౌరవసత్తమునిఁ దేర్పఁ గ్రమమున నాక్రం\nదారవము లుడిగె బంధుజ | నారబ్ధము లైన యనునయాలాపములన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","160","వ.","అట్లు సమస్త జనంబులును విగతరోదను లై రప్పు డక్కౌరవనాథుండు నారదముని యాననం బాలోకించి యిట్లనియె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","","సీ.","‘ఎఱుఁగఁగ వచ్చునే యెవ్వరి కెత్తఱి | నేదెస యగునొ మునీంద్ర! యేము\nగలుగంగ దెస లేని పులుమానిసికిఁ బోలె | నక్కురువృద్ధున కట్టిచావు\nపాటిల్లె; సుముదీర్ణ బాహుదర్పోజ్జ్వలు | లైన పుత్త్రులు నూర్వు రట్లు గలిగి\nబలము నాగాయుతప్రాణసమం బగు | నమ్మహారా జట్టి యడవిచిచ్చు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","161","తే.","వలనఁ దెగటాఱె; నే మనఁ గలదు కమల | ముఖుల తాలవృంతానిలముల సుఖించు\nప్రభువె కంక గృధ్రావలీపక్షవాయు | వడర నిలఁబడియున్నవాఁ డక్కటకట!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","162","క.","కల మృదుమాగధ గానం | బుల మేల్కనురాజు గృధ్రములునుం గాకం\nబులు నఱవఁగ నిడుద నిదుర | నొలసి తెలుప దిక్కుమాలి యున్నాఁడు గదే!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","","సీ.","వల్లభుం డొక్క సద్వ్రతముఁ బూనినఁ దానుఁ | దద్వ్రత మూని గాంధారి యతని\nపోయినగతిఁ బోయె; నాయమకై యంత | వగవఁ; బుత్త్రుల రాజ్యవైభవంబు\nవిడిచి మే యోమక యడవికి బోయిన | తల్లికి వగచెద; ధర్మసుతుఁడు\nభీమసేనుండును, బీభత్సుఁడును దన | కడుపునఁ బుట్టిన కొడుకు; లట్టి","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","163","తే.","యెగ్గతంబునఁ దానుఁ గారగ్గిఁ గాలె | నటె యనాథయై దీనికి నంతరంగ\nమలఁదురక తల్లడిల్లక యారటమున | నుడుక కలమటఁ బడక యెట్లుండుఁ జెపుమ!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","164","క.","విను ఖాండవ దహనంబునఁ | దనకుఁ బ్రమోదంబు శక్రతనయుఁ డొసఁగె; నా\nతని తల్లిఁ గాల్పఁ దగునే | యనలునకుం; గడుఁగృతఘ్నుఁ డయ్యె మునీంద్రా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","","సీ.","మఱియొక్క నెవ్వగ మనమున జనియించె; | నాంబికేయుండు కారగ్గి నెరసె\nదానికి నెయ్యది యేను జేయుదు నొక్కొ?’ | యనవుడు నారదుం డానృపాలు\nతోడ నబ్భరతవృద్ధుఁడు శాంతి యెక్కుడై | సవిశేషమైన పూజా విధాన\nమున నుపాసించి తగిన యిష్టి సేసి య | గ్నులఁ దొలునాఁడ వీడ్కొనియె; ననియు","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","165","తే.","నపుడు యాజకజనము లయ్యగ్ని చయము | నడవిలోన నుద్వాసించి యరిగె; ననియుఁ\nబేర్చి యది యవ్వనం బెల్ల నేర్చె ననియు | వింటి నాత్మాగ్నిఁ గాలె నా విభుఁడు వత్స!’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ధర్మరాజు ధృతరాష్ట్రప్రభృతులు మృతు లగుటకు శోకించుట(సం. 15-46-1)???","166","ఉ.","కావున నెవ్వగం బొరయఁగాఁ బనిలేదు నరేంద్ర! గొంతియుం\nబావకు నప్పకుం గరము భక్తి దగం బరిచర్య సేసి దే\nవావలి ప్రస్తుతింపఁగ నిరామయలోకము నొందె; వారికిన్‌\nనీ వుదకంబు లీవలయు నిష్ఠమెయిం దిలసంయుతంబుగాన్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","యుధిష్ఠిరుఁడు ధృతరాష్ట్రాదులకుఁ దిలోదక ప్రదానంబు చేయుట (సం. 15-47-10)","167","క.","అనుజన్ములు నంతఃపుర | వనితాజనములును నీవు వసుధేశ్వర ! వే\nచని నడపుఁ డుదకవిధి నీ | జనకునకును జననులకును జాహ్నవిలోనన్‌.’","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","యుధిష్ఠిరుఁడు ధృతరాష్ట్రాదులకుఁ దిలోదక ప్రదానంబు చేయుట (సం. 15-47-10)","168","ఆ.","అనిన లెస్స గాక! యని ధర్మసుతుఁ డేక | వస్త్ర ధరణనియతి వఱల నెల్ల\nవారు నట్ల యేఁగుదేరఁగఁ బౌరులు | బలసి చనఁగఁ జనియెఁ బౌరవేంద్ర!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","యుధిష్ఠిరుఁడు ధృతరాష్ట్రాదులకుఁ దిలోదక ప్రదానంబు చేయుట (సం. 15-47-10)","169","వ.","ఇట్లు చని గంగాస్నానం బాచరించి యమ్మహీపతి మొదలగు నర్హజనంబులు ధృతరాష్ట్రునకు గాంధారికిం గుంతికిం దిలోదకప్రదానంబులు నిర్వర్తించి, నివృత్తులై యశుచిత్వం బపనయించుటకుం బుర బహిరంగణంబునఁ బటకుటీర ప్రకరంబుల వసియించి; రట్టియెడ.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","యుధిష్ఠిరుఁడు ధృతరాష్ట్రాదులకుఁ దిలోదక ప్రదానంబు చేయుట (సం. 15-47-10)","","సీ.","ఆంబికేయాదుల యస్థిపుంజముల గం | గాద్వార సలిల సంగమ విశిష్ట\nసంస్కారమునఁ గూర్పఁ జాలెడు సంశుద్ధ | జనముల రావించి సబహుమాన\nఫణితుల వారి కప్పని యేర్పడఁగఁ జెప్పి | పనిచె నక్కౌరవ జనవిభుండు;\nశ్రాద్ధార్హదినమున వృద్ధానుమతి నతం | డక్కురువృద్ధున కతని సతికి","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","యుధిష్ఠిరుఁడు ధృతరాష్ట్రాదులకుఁ దిలోదక ప్రదానంబు చేయుట (సం. 15-47-10)","170","తే.","గొంతికిని రత్నకాంచన గోతురంగ | హస్తి కన్యా ధరిత్రీ గృహాది దాన\nవిధుల సర్వజనంబులు విస్మితులుగ | నియతిమెయిఁ బారలౌకిక క్రియ లొనర్చె.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","యుధిష్ఠిరుఁడు ధృతరాష్ట్రాదులకుఁ దిలోదక ప్రదానంబు చేయుట (సం. 15-47-10)","171","ఆ.","మునిజనములు వచ్చి యనుమోద మందంగ | సకల బంధుజనులు సంతసిల్ల\nనన్న పర్వతముల నాజ్యనదులఁ బితృ | మేధ ముల్లసిల్లె మేదినీశ!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","యుధిష్ఠిరుఁడు ధృతరాష్ట్రాదులకుఁ దిలోదక ప్రదానంబు చేయుట (సం. 15-47-10)","172","క.","ద్వాదశ దినములు నారదుఁ | డాదరమున నొద్ద నుండి యంతయుఁ గని స\nమ్మోదంబుతోడ నాశీ | ర్వాదం బొనరించెఁ బాండవ ప్రవరునకున్‌.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","యుధిష్ఠిరుఁడు ధృతరాష్ట్రాదులకుఁ దిలోదక ప్రదానంబు చేయుట (సం. 15-47-10)","173","వ.","అమ్మునీంద్రునిఁ దక్కునుం గలుగుతపస్విసత్తముల సమర్చితులం గావించి యుధిష్ఠిరుం డామంత్రితులం జేసిన నాసంయమివరులు నిజనివాసంబులకుం జని; రానృపకుంజరుండు బంధుమిత్రసహితుండై కుంజర పురంబు ప్రవేశించె; నిత్తెఱంగున నాంబికేయునకు భారతరణంబు పిదప దానాది పుణ్య క్రియాకలాపకరణంబులం బురంబునం బదియేనును, దపోనియమంబున వనంబున మూఁడునుంగాఁ బదునెనిమిది సంవత్సరంబులు చనియె; నివ్విధంబున వైచిత్రవీర్యుని సంసేవన సమస్తప్రకారంబుల సంఘటించి కృతార్థతానందంబునొంది ధర్మ నందనుండు జనంబు లభినందించుచందంబున సామ్రాజ్యంబుఁ బాలించె నని యిట్లు ధృతరాష్ట్రుని యాశ్ర మ వాసంబు విషయంబైన వర్తనంబు వైశంపాయనుండు చెప్పిన విని జనమేజయుండు ‘మహాత్మా యిట్లు కృతకృత్యతం బొందిన పాండవాగ్రజుండు భూభారంబు నిర్వహించుచుండం బదంపడి పుట్టిన విశేషంబు లెఱింగింపవే! యనుటయు.","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ఆశ్వాసాంతము","174","శా.","కారుణ్యాత్మక దృక్ప్రచార! గతసంకల్పాంతరంగస్థితి\nస్మేరాకార! పతంగమధ్యమ మరీచివ్యాప్తి మూర్ఛత్సుధా\nధారారూపవిహార! నిర్మిత జగత్సంసార! నానాగమ\nక్షీరోద్యన్నవనీతతాలసిత! నిశ్చిత్తత్వ సంభావితా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ఆశ్వాసాంతము","175","క.","నిర్మలసంవిదుపాస్యా! | ధర్మకరణ! దుర్వికాస్య దైత్యశ్రేణీ\nనిర్మథన కేళి! నిర్జర | శర్మకృతి విహారశీల! సంయమిలోలా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ఆశ్వాసాంతము","176","మాలిని","సమదవిమద దూరా సన్న రక్షా! ప్రసన్నా!\nశమశుభమయమూర్తి! స్ఫారదుర్లక్ష సారా!\nదమవిభవసముద్యద్ధామ! నిస్సీమభూమా!\nసమహృదయలసత్సంసర్గ! సానందవర్గా!","","",""],
  ["ఆశ్రమవాసపర్వము","ద్వితీయాశ్వాసము","ఆశ్వాసాంతము","177","గద్యము","ఇది శ్రీమదుభయకవిమిత్త్ర కొమ్మనామాత్యపుత్త్ర బుధారాధనవిరాజి తిక్కన సోమయాజి ప్రణీతం బైన శ్రీమహాభారతంబున నాశ్రమవాసపర్వంబునందు సర్వంబు ద్వితీయాశ్వాసము.","","",""]
];
